                className="w-full max-w-sm bg-white/90 backdrop-blur-xl rounded-3xl shadow-2xl p-6 border border-white/50 max-h-[90vh] overflow-y-auto"
            >
                <div className="flex justify-between items-center mb-6">
                    <div>
                        <h2 className="text-2xl font-black text-gray-800">Select Version</h2>
                        <p className="text-xs text-gray-500">Choose your AI experience</p>
