                        title="Sifra Premium Plus"
                        description="Unlock the ultimate power. Exclusive features, fastest speeds & unique personalities."
                        icon={<SparklesIcon />}
                        color="bg-gradient-to-br from-indigo-500 via-purple-500 to-pink-500"
                        onClick={() => { onSelectPremiumPlus(); onClose(); }}
