                    <VersionCard 
                        title="SIFRA PRO"
                        description="Personal Pro-Assessment Mode (P-A.M.). Deep customization."
                        icon={<UserIcon />}
                        color="bg-gradient-to-br from-yellow-400 to-orange-500"
                        onClick={() => { onSelectPro(); onClose(); }}
                    />

                    {/* Option 2: Quantum Leap */}
                    <VersionCard 
                        title="Quantum Leap"
                        description="Dual Mode Engine. Advanced Persona & Voice Studio."
                        icon={<BoltIcon />}
                        color="bg-gradient-to-br from-[#2B0A3D] to-[#B45CFF]"
                        onClick={() => { onSelectQuantum(); onClose(); }}
                    />

                    {/* Option 1: Free / Current */}
                    <VersionCard 
                        title="SIFRA T-XON"
                        description="Standard Mode. Free access to general chat features."
                        icon={<SparklesIcon />}
                        color="bg-gradient-to-br from-pink-400 to-purple-500"
                        onClick={() => { onSelectFree(); onClose(); }}
                        isActive={false} 
