import { UserProfile } from '../types';
import { motion, AnimatePresence } from 'framer-motion';
import { GoogleGenAI, LiveSession, Modality, LiveServerMessage, Blob } from '@google/genai';
import { encode, decode, decodeAudioData } from '../utils/audioUtils';
import HeartSparkleIcon from '../components/icons/HeartSparkleIcon';
import XMarkIcon from '../components/icons/XMarkIcon';
import MicrophoneIcon from '../components/icons/MicrophoneIcon';
import SpeakerWaveIcon from '../components/icons/SpeakerWaveIcon';
import MicrophoneSlashIcon from '../components/icons/MicrophoneSlashIcon';
import AdjustmentsHorizontalIcon from '../components/icons/AdjustmentsHorizontalIcon';
import CheckCircleIcon from '../components/icons/CheckCircleIcon';

if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable is not set");
}

// --- UTILS ---
const createBlob = (data: Float32Array): Blob => {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
        const s = Math.max(-1, Math.min(1, data[i]));
        int16[i] = s * 32767;
    }
    return {
        data: encode(new Uint8Array(int16.buffer)),
        mimeType: 'audio/pcm;rate=16000',
    };
};

// --- TYPES ---
interface PremiumSetupData {
    name: string;
    partnerType: 'Girlfriend' | 'Boyfriend';
    idealDescription: string;
    religion: string;
    behaviorMode: string;
    relationshipContext: string;
}

const BEHAVIOR_MODES = [
    "Sweet & Caring (Soft)", 
    "Possessive & Protective (Yandere)", 
    "Strict & Disciplined", 
    "Flirty & Romantic", 
    "Intellectual & Calm",
    "Funny & Childish"
];

const RELIGIONS = ["Muslim", "Hindu", "Christian", "Other"];

// --- ONBOARDING WIZARD COMPONENT ---
const SetupWizard: React.FC<{ onComplete: (data: PremiumSetupData) => void, onCancel: () => void }> = ({ onComplete, onCancel }) => {
    const [step, setStep] = useState(1);
    const [formData, setFormData] = useState<PremiumSetupData>({
        name: '',
        partnerType: 'Girlfriend',
        idealDescription: '',
        religion: '',
        behaviorMode: '',
        relationshipContext: ''
    });
    const [acceptedTnc, setAcceptedTnc] = useState(false);

    const next = () => setStep(s => s + 1);
    const back = () => setStep(s => s - 1);

    return (
        <div className="fixed inset-0 z-[250] bg-black flex items-center justify-center p-6 font-sans text-white overflow-hidden">
            {/* Ambient Background */}
            <div className="absolute inset-0 bg-gradient-to-br from-[#1a0010] via-black to-[#0f0014]"></div>
            <div className="absolute top-[-20%] left-[-20%] w-[50%] h-[50%] bg-[#ff0055] opacity-10 blur-[120px] rounded-full"></div>

            <motion.div 
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                className="relative z-10 w-full max-w-lg bg-white/5 backdrop-blur-xl border border-white/10 rounded-3xl p-8 shadow-2xl flex flex-col h-[80vh]"
            >
                {/* Header */}
                <div className="flex justify-between items-center mb-6">
                    <h2 className="text-xl font-bold tracking-widest text-[#ff4d6d]">INITIATION <span className="text-white/50 text-sm">Step {step}/7</span></h2>
                    {step === 1 && <button onClick={onCancel}><XMarkIcon className="text-white/50" /></button>}
                </div>

                <div className="flex-1 overflow-y-auto pr-2">
                    {step === 1 && (
                        <div className="space-y-4 animate-fade-in">
                            <h3 className="text-2xl font-light">What should I call you?</h3>
                            <input 
                                type="text" 
                                value={formData.name} 
                                onChange={e => setFormData({...formData, name: e.target.value})}
                                placeholder="Your Name" 
                                className="w-full bg-white/10 border-b-2 border-white/20 p-4 text-xl outline-none focus:border-[#ff4d6d]" 
                                autoFocus
                            />
                        </div>
                    )}

                    {step === 2 && (
                        <div className="space-y-4 animate-fade-in">
                            <h3 className="text-2xl font-light">I want a...</h3>
                            <div className="grid grid-cols-2 gap-4 mt-6">
                                {['Girlfriend', 'Boyfriend'].map(type => (
                                    <button 
                                        key={type}
                                        onClick={() => setFormData({...formData, partnerType: type as any})}
                                        className={`p-6 rounded-2xl border transition-all ${formData.partnerType === type ? 'bg-[#ff4d6d] border-[#ff4d6d] text-white shadow-[0_0_20px_#ff4d6d]' : 'bg-white/5 border-white/10 hover:bg-white/10'}`}
                                    >
                                        <span className="text-lg font-bold">{type}</span>
                                    </button>
                                ))}
                            </div>
                        </div>
                    )}

                    {step === 3 && (
                        <div className="space-y-4 animate-fade-in">
                            <h3 className="text-2xl font-light">Describe your ideal partner</h3>
                            <p className="text-white/50 text-sm">What do they look like? How do they talk?</p>
                            <textarea 
                                value={formData.idealDescription}
                                onChange={e => setFormData({...formData, idealDescription: e.target.value})}
                                placeholder="e.g. She has long hair, talks softly, loves cats..."
                                className="w-full h-40 bg-white/10 rounded-xl p-4 mt-2 outline-none focus:ring-1 focus:ring-[#ff4d6d] resize-none"
                            />
                        </div>
                    )}

                    {step === 4 && (
                        <div className="space-y-4 animate-fade-in">
                            <h3 className="text-2xl font-light">Cultural Background / Religion</h3>
                            <p className="text-white/50 text-sm">This helps align values and greetings.</p>
                            <div className="grid grid-cols-2 gap-3 mt-4">
                                {RELIGIONS.map(r => (
                                    <button 
                                        key={r}
                                        onClick={() => setFormData({...formData, religion: r})}
                                        className={`p-4 rounded-xl border text-left ${formData.religion === r ? 'bg-[#ff4d6d]/20 border-[#ff4d6d] text-[#ff4d6d]' : 'bg-white/5 border-white/10 text-white/70'}`}
                                    >
                                        {r}
                                    </button>
                                ))}
                            </div>
                        </div>
                    )}

                    {step === 5 && (
                        <div className="space-y-4 animate-fade-in">
                            <h3 className="text-2xl font-light">How should I treat you?</h3>
                            <div className="space-y-2 mt-4">
                                {BEHAVIOR_MODES.map(mode => (
                                    <button 
                                        key={mode}
                                        onClick={() => setFormData({...formData, behaviorMode: mode})}
                                        className={`w-full p-4 rounded-xl border text-left transition-all ${formData.behaviorMode === mode ? 'bg-white text-black font-bold' : 'bg-white/5 border-white/10 text-white/70 hover:bg-white/10'}`}
                                    >
                                        {mode}
                                    </button>
                                ))}
                            </div>
                        </div>
                    )}

                    {step === 6 && (
                        <div className="space-y-4 animate-fade-in">
                            <h3 className="text-2xl font-light">Our Relationship Context</h3>
                            <p className="text-white/50 text-sm">Write a story about us. How did we meet? What is our current status? (Max 500 words)</p>
                            <textarea 
                                value={formData.relationshipContext}
                                onChange={e => setFormData({...formData, relationshipContext: e.target.value})}
                                maxLength={3000} // approx 500 words
                                placeholder="We met at a coffee shop 2 years ago. We are deeply in love but currently long-distance..."
                                className="w-full h-64 bg-white/10 rounded-xl p-4 mt-2 outline-none focus:ring-1 focus:ring-[#ff4d6d] resize-none text-sm leading-relaxed"
                            />
                            <p className="text-right text-xs text-white/30">{formData.relationshipContext.length}/3000 chars</p>
