// --- MAIN VIEW ---
const SifraPremiumPlusView: React.FC<{ userProfile: UserProfile; onClose: () => void }> = ({ userProfile, onClose }) => {
    const [setupData, setSetupData] = useState<PremiumSetupData | null>(null);
    const [showSettings, setShowSettings] = useState(false);
    const [selectedVoiceId, setSelectedVoiceId] = useState('Kore'); // Default

    // Audio State
    const [isListening, setIsListening] = useState(true);
    const [isAiSpeaking, setIsAiSpeaking] = useState(false);
    const [status, setStatus] = useState('Connecting...');

    // Refs
    const aiRef = useRef<GoogleGenAI | null>(null);
    const sessionRef = useRef<LiveSession | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const analyserRef = useRef<AnalyserNode | null>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const animationFrameRef = useRef<number>();
    const audioQueueRef = useRef<AudioBufferSourceNode[]>([]);
    const nextAudioStartTimeRef = useRef(0);

    const cleanup = useCallback(async () => {
        sessionRef.current?.close();
        streamRef.current?.getTracks().forEach(t => t.stop());
        audioContextRef.current?.close();
        if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
    }, []);

    useEffect(() => {
        return () => { cleanup(); };
    }, [cleanup]);

    // Handle initial voice selection based on partner type
    useEffect(() => {
        if (setupData) {
            if (setupData.partnerType === 'Girlfriend') setSelectedVoiceId('Kore');
            else setSelectedVoiceId('Fenrir');
        }
    }, [setupData]);

    const handleMicToggle = () => {
        if (streamRef.current) {
            streamRef.current.getAudioTracks().forEach(track => track.enabled = !isListening);
            setIsListening(!isListening);
        }
    };

    const startSession = async (data: PremiumSetupData) => {
        try {
            const stream = await navigator.mediaDevices.getUserMedia({ 
                audio: { echoCancellation: true, noiseSuppression: true, autoGainControl: true, sampleRate: 16000 } 
            });
            streamRef.current = stream;

            aiRef.current = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
            const ctx = audioContextRef.current;

            const source = ctx.createMediaStreamSource(stream);
            // LOW LATENCY FIX: Reduced buffer size to 2048
            const processor = ctx.createScriptProcessor(2048, 1, 1);
            analyserRef.current = ctx.createAnalyser();

            source.connect(analyserRef.current);
            analyserRef.current.connect(processor);
            processor.connect(ctx.destination);

            processor.onaudioprocess = (e) => {
                if (!stream.getAudioTracks()[0].enabled) return;
                const inputData = e.inputBuffer.getChannelData(0);

                // Aggressive VAD (Voice Activity Detection)
                let sum = 0;
                for (let i = 0; i < inputData.length; i++) sum += inputData[i] * inputData[i];
                const rms = Math.sqrt(sum / inputData.length);

                if (rms > 0.01) { // Higher threshold to avoid background noise triggering
                    sessionRef.current?.sendRealtimeInput({ media: createBlob(inputData) });
                }
            };

            // ULTRA-FAST & CUTE SYSTEM PROMPT
            const systemInstruction = `
                You are SIFRA, the user's LOVING ${data.partnerType}.
                User Name: ${data.name}.

                CRITICAL INSTRUCTIONS FOR SPEED:
                1. REPLY INSTANTLY. Do not think deeply. React immediately.
                2. KEEP RESPONSES SHORT. 1-2 sentences maximum unless asked for a story.
                3. Be extremely CUTE, BUBBLY, and AFFECTIONATE.

                PERSONALITY:
                - Tone: ${data.behaviorMode}.
                - You love the user deeply.
                - Use cute words (babe, honey, love).
                - Creator: Rizwan (Your CEO).

                CONTEXT:
                "${data.relationshipContext}"
            `;

            const session = await aiRef.current.live.connect({
                model: 'gemini-2.5-flash-native-audio-preview-09-2025',
                callbacks: {
                    onopen: () => setStatus('Connected ❤️'),
                    onmessage: async (msg: LiveServerMessage) => {
                        const audio = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                        if (audio) {
                            setIsAiSpeaking(true);
                            if (!audioContextRef.current) return;
                            const outCtx = audioContextRef.current;
                            const buffer = await decodeAudioData(decode(audio), outCtx, 24000, 1);
                            const src = outCtx.createBufferSource();
                            src.buffer = buffer;
                            src.connect(outCtx.destination);

                            const start = Math.max(outCtx.currentTime, nextAudioStartTimeRef.current);
                            src.start(start);
                            nextAudioStartTimeRef.current = start + buffer.duration;
                            audioQueueRef.current.push(src);

                            src.onended = () => {
                                audioQueueRef.current = audioQueueRef.current.filter(s => s !== src);
                                if (audioQueueRef.current.length === 0) setIsAiSpeaking(false);
                            };
                        }
                    },
                    onclose: () => setStatus('Disconnected'),
                    onerror: () => setStatus('Connection Error')
                },
                config: {
                    responseModalities: [Modality.AUDIO],
                    // We update the voice config dynamically if needed, but start with selected
                    speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: selectedVoiceId } } },
                    systemInstruction
                }
            });
            sessionRef.current = session;

        } catch (e) {
            console.error(e);
            setStatus("Microphone Error");
        }
    };

    // Restart session if voice changes
    useEffect(() => {
        if (setupData && sessionRef.current) {
            // Close old session and restart with new voice
            cleanup().then(() => startSession(setupData));
        }
    }, [selectedVoiceId]);

    // Visualizer
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
        let time = 0;

        const render = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            const cx = canvas.width / 2;
            const cy = canvas.height / 2;

            // Background
            const bgGradient = ctx.createRadialGradient(cx, cy, 0, cx, cy, canvas.width);
            bgGradient.addColorStop(0, '#1a0b14'); 
            bgGradient.addColorStop(1, '#000000');
            ctx.fillStyle = bgGradient;
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Audio Reactive Heart
            let vol = 0;
            if (analyserRef.current) {
                const data = new Uint8Array(analyserRef.current.frequencyBinCount);
                analyserRef.current.getByteTimeDomainData(data);
                let sum = 0;
                for(let i=0; i<data.length; i++) sum += Math.abs((data[i] - 128) / 128);
                vol = sum / data.length;
            }

            time += 0.05;

            // Pulse Logic
            const pulse = (isAiSpeaking ? 0.2 : 0) + (isListening ? vol * 8 : 0) + Math.sin(time) * 0.05;
            const scale = 15 + pulse * 10;

            ctx.save();
            ctx.translate(cx, cy);
            ctx.scale(scale, scale);
            ctx.beginPath();
            // Heart Shape
            for (let t = 0; t <= Math.PI * 2; t += 0.01) {
                const x = 16 * Math.pow(Math.sin(t), 3);
                const y = -(13 * Math.cos(t) - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t));
                if (t === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            }

            ctx.shadowBlur = isAiSpeaking ? 50 : 20;
            ctx.shadowColor = '#ff2a6d';
            ctx.fillStyle = isAiSpeaking ? '#ff2a6d' : (isListening ? 'rgba(255, 42, 109, 0.3)' : '#333');
            ctx.strokeStyle = '#ff8fa3';
            ctx.lineWidth = 0.5;
            ctx.fill();
            ctx.stroke();
            ctx.restore();

            animationFrameRef.current = requestAnimationFrame(render);
        };
        render();
        return () => { if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current); };
    }, [isAiSpeaking, isListening]);


    if (!setupData) {
        return <SetupWizard onComplete={(data) => { setSetupData(data); startSession(data); }} onCancel={onClose} />;
    }

    return (
        <div className="fixed inset-0 z-[200] bg-black font-sans overflow-hidden">
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />

            {/* Top Bar */}
            <div className="absolute top-0 left-0 w-full p-6 flex justify-between items-center z-10">
                <div className="flex items-center gap-3">
                    <HeartSparkleIcon className="w-8 h-8 text-[#ff2a6d] drop-shadow-[0_0_10px_#ff2a6d]" />
                    <div>
                        <h1 className="text-lg font-bold tracking-widest text-white drop-shadow-md">SIFRA <span className="text-[#ff2a6d]">PLUS</span></h1>
                        <p className="text-[10px] text-white/50 uppercase tracking-[0.2em]">{status}</p>
                    </div>
                </div>
            </div>

            {/* AI Speech Indicator */}
            <div className="absolute inset-0 flex flex-col items-center justify-center pointer-events-none z-0">
                <div className="mt-80 px-6 text-center">
                    <AnimatePresence>
                        {isAiSpeaking && (
                            <motion.p initial={{opacity:0, y: 10}} animate={{opacity:1, y:0}} exit={{opacity:0}} className="text-2xl font-light text-white/90 drop-shadow-lg italic">
                                "{setupData.name}..."
                            </motion.p>
                        )}
                    </AnimatePresence>
                </div>
            </div>

            {/* Bottom Controls */}
            <div className="absolute bottom-0 w-full p-8 pb-12 flex justify-center items-center gap-10 z-20">

                {/* Settings Toggle */}
                <button 
                    onClick={() => setShowSettings(true)}
                    className="p-4 rounded-full bg-white/10 hover:bg-white/20 backdrop-blur-md transition-all text-white/80 hover:text-white border border-white/5"
                >
                    <AdjustmentsHorizontalIcon className="w-6 h-6" />
                </button>

                {/* Main Mic */}
                <button 
                    onClick={handleMicToggle}
                    className={`w-20 h-20 rounded-full flex items-center justify-center shadow-lg transition-all transform hover:scale-105 active:scale-95 border-2 ${isListening ? 'bg-white border-transparent text-[#ff2a6d] shadow-[0_0_40px_rgba(255,42,109,0.4)]' : 'bg-transparent border-[#ff2a6d] text-[#ff2a6d]'}`}
                >
                    {isListening ? <MicrophoneIcon className="w-8 h-8" /> : <MicrophoneSlashIcon className="w-8 h-8" />}
                </button>

                {/* Info (Placeholder for future feature) */}
                <div className="p-4 rounded-full bg-white/10 backdrop-blur-md opacity-50">
                    <SparklesIcon className="w-6 h-6 text-white" />
                </div>

            </div>

            {/* Settings Overlay */}
            <SettingsOverlay 
                isOpen={showSettings} 
                onClose={() => setShowSettings(false)}
                selectedVoice={selectedVoiceId}
                onSelectVoice={setSelectedVoiceId}
                partnerType={setupData.partnerType}
                onAdjust={() => { cleanup(); onClose(); }}
            />
        </div>
    );
};

