                        if (audio && audioContextRef.current) {
                            setIsAiSpeaking(true);
                            const outCtx = audioContextRef.current;

                            // High-performance decoding
                            const buffer = await decodeAudioData(decode(audio), outCtx, 24000, 1);
                            const src = outCtx.createBufferSource();
                            src.buffer = buffer;
                            src.connect(outCtx.destination);

                            const start = Math.max(outCtx.currentTime, nextAudioStartTimeRef.current);
                            src.start(start);
                            nextAudioStartTimeRef.current = start + buffer.duration;
                            audioQueueRef.current.push(src);

                            src.onended = () => {
                                audioQueueRef.current = audioQueueRef.current.filter(s => s !== src);
                                if (audioQueueRef.current.length === 0) setIsAiSpeaking(false);
                            };
                        }
                    },
                    onclose: () => setStatus('Link Closed'),
                    onerror: () => setStatus('Sync Error')
                },
                config: {
                    responseModalities: [Modality.AUDIO],
                    speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: selectedVoiceId } } },
                    systemInstruction
                }
            });
            sessionRef.current = session;
        } catch (e) { setStatus("Hardware Error"); }
    };

    const cleanup = useCallback(async () => {
        sessionRef.current?.close();
        streamRef.current?.getTracks().forEach(t => t.stop());
        audioContextRef.current?.close();
        interruptPlayback();
    }, [interruptPlayback]);

    useEffect(() => {
        if (setupData && sessionRef.current) {
            cleanup().then(() => startSession(setupData));
        }
    }, [selectedVoiceId]);

    // Enhanced Heart Visualization
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
        let time = 0;

        const render = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            const cx = canvas.width / 2;
            const cy = canvas.height / 2;

            // Atmosphere
            const grd = ctx.createRadialGradient(cx, cy, 0, cx, cy, canvas.width);
            grd.addColorStop(0, isAiSpeaking ? '#2b0a1a' : '#0a0a0f');
            grd.addColorStop(1, '#000000');
            ctx.fillStyle = grd;
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            let vol = 0;
            if (analyserRef.current) {
                const data = new Uint8Array(analyserRef.current.frequencyBinCount);
                analyserRef.current.getByteTimeDomainData(data);
                let sum = 0;
                for(let i=0; i<data.length; i++) sum += Math.abs(data[i] - 128);
                vol = sum / data.length / 128;
            }

            time += 0.04;
            const pulse = (isAiSpeaking ? 0.3 : 0) + (isListening ? vol * 12 : 0) + Math.sin(time) * 0.08;
            const scale = 14 + pulse * 12;

            ctx.save();
            ctx.translate(cx, cy);
            ctx.scale(scale, scale);

            // Pulsing Glow
            ctx.shadowBlur = 40 * (1 + pulse);
            ctx.shadowColor = THEME.accent;

            ctx.beginPath();
            for (let t = 0; t <= Math.PI * 2; t += 0.02) {
                const x = 16 * Math.pow(Math.sin(t), 3);
                const y = -(13 * Math.cos(t) - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t));
                if (t === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            }

            ctx.fillStyle = isAiSpeaking ? THEME.accent : (isListening ? 'rgba(255, 42, 109, 0.4)' : '#222');
            ctx.fill();
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 0.3;
            ctx.stroke();
            ctx.restore();

            animationFrameRef.current = requestAnimationFrame(render);
        };
        render();
    }, [isAiSpeaking, isListening]);

    if (!setupData) {
        return <SetupWizard onComplete={(data) => { setSetupData(data); startSession(data); }} onCancel={onClose} />;
    }

