                            <p className="text-xl font-medium text-white/90 italic tracking-wide">"Listening to your heart..."</p>
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>

            {/* Bottom Interaction Controller */}
            <div className="absolute bottom-0 w-full p-10 pb-16 flex justify-center items-center gap-8 sm:gap-16 z-40">
