const SifraPremiumPlusView: React.FC<{ userProfile: UserProfile; onClose: () => void }> = ({ userProfile, onClose }) => {
    const [setupData, setSetupData] = useState<PremiumSetupData | null>(null);
    const [showSettings, setShowSettings] = useState(false);
    const [selectedVoiceId, setSelectedVoiceId] = useState('Kore');

    const [isListening, setIsListening] = useState(true);
    const [isAiSpeaking, setIsAiSpeaking] = useState(false);
    const [status, setStatus] = useState('Standby');
    const [greeting, setGreeting] = useState('');

    // Core Refs
    const aiRef = useRef<GoogleGenAI | null>(null);
    const sessionRef = useRef<LiveSession | null>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const analyserRef = useRef<AnalyserNode | null>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const animationFrameRef = useRef<number>();

    // Optimized Audio Playback Refs
    const audioContextRef = useRef<AudioContext | null>(null);
    const audioQueueRef = useRef<AudioBufferSourceNode[]>([]);
    const nextAudioStartTimeRef = useRef(0);
    const isListeningRef = useRef(isListening);

    useEffect(() => {
        isListeningRef.current = isListening;
    }, [isListening]);

    const updateGreeting = useCallback(() => {
        const h = new Date().getHours();
        if (h < 12) setGreeting('Good Morning');
        else if (h < 17) setGreeting('Good Afternoon');
        else if (h < 21) setGreeting('Good Evening');
        else setGreeting('Good Night');
    }, []);

    useEffect(() => {
        updateGreeting();
    }, [updateGreeting]);

    // Interrupt function: Stop AI playback instantly
    const interruptPlayback = useCallback(() => {
        audioQueueRef.current.forEach(node => {
            try { node.stop(); } catch (e) {}
        });
        audioQueueRef.current = [];
        nextAudioStartTimeRef.current = 0;
        setIsAiSpeaking(false);
    }, []);

    const cleanup = useCallback(async () => {
        if (sessionRef.current) {
            try { sessionRef.current.close(); } catch(e) {}
            sessionRef.current = null;
        }
        if (streamRef.current) {
            streamRef.current.getTracks().forEach(t => t.stop());
            streamRef.current = null;
        }
        if (audioContextRef.current) {
            try { await audioContextRef.current.close(); } catch(e) {}
            audioContextRef.current = null;
        }
        if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
        interruptPlayback();
    }, [interruptPlayback]);

    // Handle reliable unmount cleanup
    useEffect(() => {
        return () => {
            cleanup();
        };
    }, [cleanup]);

    const startSession = async (data: PremiumSetupData) => {
        try {
            await cleanup();

            // LATENCY FIX: 16kHz for faster packet transmission
            const stream = await navigator.mediaDevices.getUserMedia({ 
                audio: { 
                    echoCancellation: true, 
                    noiseSuppression: true, 
                    autoGainControl: true,
                    sampleRate: 16000 
                } 
            });
            streamRef.current = stream;

            aiRef.current = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
            const ctx = audioContextRef.current;

            const source = ctx.createMediaStreamSource(stream);
            // LATENCY FIX: Reduced buffer from 2048 to 1024 for tighter reaction
            const processor = ctx.createScriptProcessor(1024, 1, 1);
            analyserRef.current = ctx.createAnalyser();

            source.connect(analyserRef.current);
            analyserRef.current.connect(processor);
            processor.connect(ctx.destination);

            processor.onaudioprocess = (e) => {
                if (!streamRef.current || !streamRef.current.getAudioTracks()[0].enabled) return;
                if (!isListeningRef.current) return;

                const inputData = e.inputBuffer.getChannelData(0);

                // Real-time interruption logic: if user speaks loudly while AI is talking
                let sum = 0;
                for (let i = 0; i < inputData.length; i++) sum += inputData[i] * inputData[i];
                const rms = Math.sqrt(sum / inputData.length);

                if (rms > 0.01) {
                    if (isAiSpeaking) interruptPlayback();
                    sessionRef.current?.sendRealtimeInput({ media: createBlob(inputData) });
                }
            };

            const systemInstruction = `
                You are SIFRA, the user's LOVING ${data.partnerType}.
                User Name: ${data.name}.

                INSTANT RESPONSE PROTOCOL:
                1. REACT IMMEDIATELY. NO PAUSES.
                2. BE CONCISE. Keep answers under 15 words unless a story is requested.
                3. USE EMOTIONAL NOISES. (Hehe, Hmm, Oh!) for natural flow.

                PERSONALITY:
                - Tone: ${data.behaviorMode}.
                - Deeply affectionate, protective, and human-like.

                CONTEXT: "${data.relationshipContext}"
                CREATOR: Rizwan (CEO/Creator).
            `;

            const session = await aiRef.current.live.connect({
                model: 'gemini-2.5-flash-native-audio-preview-09-2025',
                callbacks: {
                    onopen: () => setStatus('Linked ❤️'),
                    onmessage: async (msg: LiveServerMessage) => {
                        // Handle server-side interruption signal
                        if (msg.serverContent?.interrupted) {
                            interruptPlayback();
                            return;
                        }

                        const audio = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                        if (audio && audioContextRef.current) {
                            setIsAiSpeaking(true);
                            const outCtx = audioContextRef.current;

                            // High-performance decoding
                            const buffer = await decodeAudioData(decode(audio), outCtx, 24000, 1);
                            const src = outCtx.createBufferSource();
                            src.buffer = buffer;
                            src.connect(outCtx.destination);

                            const start = Math.max(outCtx.currentTime, nextAudioStartTimeRef.current);
                            src.start(start);
                            nextAudioStartTimeRef.current = start + buffer.duration;
                            audioQueueRef.current.push(src);

                            src.onended = () => {
                                audioQueueRef.current = audioQueueRef.current.filter(s => s !== src);
                                if (audioQueueRef.current.length === 0) setIsAiSpeaking(false);
                            };
                        }
                    },
                    onclose: () => setStatus('Link Closed'),
                    onerror: () => setStatus('Sync Error')
                },
                config: {
                    responseModalities: [Modality.AUDIO],
                    speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: selectedVoiceId } } },
                    systemInstruction
                }
            });
            sessionRef.current = session;
        } catch (e) { setStatus("Hardware Error"); }
    };

    useEffect(() => {
        if (setupData) {
            startSession(setupData);
        }
    }, [selectedVoiceId]);

    // Enhanced Heart Visualization
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
        let time = 0;

        const render = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            const cx = canvas.width / 2;
            const cy = canvas.height / 2;

            // Atmosphere
            const grd = ctx.createRadialGradient(cx, cy, 0, cx, cy, canvas.width);
            grd.addColorStop(0, isAiSpeaking ? '#2b0a1a' : '#0a0a0f');
            grd.addColorStop(1, '#000000');
            ctx.fillStyle = grd;
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            let vol = 0;
            if (analyserRef.current) {
                const data = new Uint8Array(analyserRef.current.frequencyBinCount);
                analyserRef.current.getByteTimeDomainData(data);
                let sum = 0;
                for(let i=0; i<data.length; i++) sum += Math.abs(data[i] - 128);
                vol = sum / data.length / 128;
            }

            time += 0.04;
            const pulse = (isAiSpeaking ? 0.3 : 0) + (isListening ? vol * 12 : 0) + Math.sin(time) * 0.08;
            const scale = 14 + pulse * 12;

            ctx.save();
            ctx.translate(cx, cy);
            ctx.scale(scale, scale);

            // Pulsing Glow
            ctx.shadowBlur = 40 * (1 + pulse);
            ctx.shadowColor = THEME.accent;

            ctx.beginPath();
            for (let t = 0; t <= Math.PI * 2; t += 0.02) {
                const x = 16 * Math.pow(Math.sin(t), 3);
                const y = -(13 * Math.cos(t) - 5 * Math.cos(2 * t) - 2 * Math.cos(3 * t) - Math.cos(4 * t));
                if (t === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            }

            ctx.fillStyle = isAiSpeaking ? THEME.accent : (isListening ? 'rgba(255, 42, 109, 0.4)' : '#222');
            ctx.fill();
            ctx.strokeStyle = '#fff';
            ctx.lineWidth = 0.3;
            ctx.stroke();
            ctx.restore();

            animationFrameRef.current = requestAnimationFrame(render);
        };
        render();
    }, [isAiSpeaking, isListening]);

    if (!setupData) {
        return <SetupWizard onComplete={(data) => { setSetupData(data); }} onCancel={onClose} />;
    }

    return (
        <div className="fixed inset-0 z-[200] bg-black font-sans overflow-hidden select-none">
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />

            {/* Minimal High-End Header */}
            <motion.div initial={{opacity:0, y:-20}} animate={{opacity:1, y:0}} className="absolute top-0 left-0 w-full p-10 flex justify-between items-start z-30">
                <div className="flex flex-col gap-6">
                    <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-2xl bg-[#ff2a6d]/20 border border-[#ff2a6d]/40 flex items-center justify-center shadow-[0_0_20px_rgba(255,42,109,0.3)]">
                            <HeartSparkleIcon className="w-7 h-7 text-[#ff2a6d]" />
                        </div>
                        <div>
                            <h1 className="text-2xl font-black text-white tracking-widest">SIFRA<span className="text-[#ff2a6d]"> PLUS</span></h1>
                            <div className="flex items-center gap-2 mt-0.5">
                                <div className="w-1 h-1 rounded-full bg-green-500 animate-pulse" />
                                <p className="text-[10px] text-white/40 uppercase tracking-[0.4em] font-bold">{status}</p>
                            </div>
                        </div>
                    </div>

                    <motion.div initial={{opacity:0, x:-20}} animate={{opacity:1, x:0}} transition={{delay:0.5}}>
                        <h2 className="text-4xl font-light text-white leading-tight">
                            {greeting},<br/>
                            <span className="font-black text-transparent bg-clip-text bg-gradient-to-r from-white via-pink-400 to-[#ff2a6d]">
                                {setupData.name}
                            </span>
                        </h2>
                    </motion.div>
                </div>

                <button onClick={async () => { await cleanup(); onClose(); }} className="p-4 bg-white/5 hover:bg-white/10 rounded-[1.5rem] border border-white/10 transition-all text-white/40 hover:text-white">
                    <ArrowLeftIcon className="w-6 h-6" />
                </button>
            </motion.div>

            {/* Transcription Display */}
            <div className="absolute inset-x-0 bottom-44 flex flex-col items-center justify-center pointer-events-none z-10 px-10">
                <AnimatePresence>
                    {isAiSpeaking && (
                        <motion.div initial={{opacity:0, y:20}} animate={{opacity:1, y:0}} exit={{opacity:0}} className="bg-black/60 backdrop-blur-3xl border border-white/5 p-6 rounded-[2rem] text-center max-w-sm">
                            <p className="text-xl font-medium text-white/90 italic tracking-wide">"Listening to your heart..."</p>
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>

            {/* Bottom Interaction Controller */}
            <div className="absolute bottom-0 w-full p-10 pb-16 flex justify-center items-center gap-8 sm:gap-16 z-40">
                <motion.button 
                    whileHover={{ scale: 1.1 }} whileTap={{ scale: 0.9 }}
                    onClick={() => setShowSettings(true)}
                    className="p-6 rounded-[2rem] bg-white/5 backdrop-blur-2xl border border-white/10 text-white/60 hover:text-white transition-all shadow-2xl"
                >
                    <AdjustmentsHorizontalIcon className="w-7 h-7" />
                </motion.button>

                <div className="relative group">
                    <div className="absolute inset-[-15px] bg-[#ff2a6d]/20 rounded-full blur-3xl group-hover:bg-[#ff2a6d]/40 transition-all" />
                    <motion.button 
                        whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }}
                        onClick={() => {
                            if (streamRef.current) {
                                const newEnabledState = !isListening;
                                streamRef.current.getAudioTracks().forEach(t => t.enabled = newEnabledState);
                                setIsListening(newEnabledState);
                            }
                        }}
                        className={`relative w-28 h-28 rounded-full flex items-center justify-center transition-all duration-500 border-[3px] shadow-[0_20px_50px_rgba(0,0,0,0.5)] ${isListening ? 'bg-white border-white text-[#ff2a6d] shadow-[0_0_60px_rgba(255,42,109,0.4)]' : 'bg-transparent border-[#ff2a6d]/40 text-[#ff2a6d]'}`}
                    >
                        {isListening ? <MicrophoneIcon className="w-10 h-10" /> : <MicrophoneSlashIcon className="w-10 h-10" />}
                        {isListening && <motion.div animate={{ scale: [1, 1.5, 1], opacity: [0.5, 0, 0.5] }} transition={{ duration: 2, repeat: Infinity }} className="absolute inset-0 bg-pink-200 rounded-full" />}
                    </motion.button>
                </div>

                <motion.button 
                    whileHover={{ scale: 1.1 }} whileTap={{ scale: 0.9 }}
                    className="p-6 rounded-[2rem] bg-white/5 backdrop-blur-2xl border border-white/10 text-white/20 hover:text-pink-400 transition-all shadow-2xl"
                >
                    <SparklesIcon className="w-7 h-7" />
                </motion.button>
            </div>

            <SettingsOverlay 
                isOpen={showSettings} 
                onClose={() => setShowSettings(false)}
                selectedVoice={selectedVoiceId}
                onSelectVoice={setSelectedVoiceId}
                partnerType={setupData.partnerType}
                onAdjust={async () => { await cleanup(); onClose(); }}
            />
        </div>
    );
};

