import React, { useState, useRef } from 'react';
import MicrophoneIcon from './icons/MicrophoneIcon';
import SendIcon from './icons/SendIcon';
import PlusCircleIcon from './icons/PlusCircleIcon';
import XMarkIcon from './icons/XMarkIcon';

interface ChatInputProps {
    onSendMessage: (text: string, imageData?: { data: string, mimeType: string }) => void;
    isLoading: boolean;
    onVoiceClick: () => void;
}

const ChatInput: React.FC<ChatInputProps> = ({ onSendMessage, isLoading, onVoiceClick }) => {
    const [text, setText] = useState('');
    const [selectedImage, setSelectedImage] = useState<{ data: string, mimeType: string } | null>(null);
    const fileInputRef = useRef<HTMLInputElement>(null);

    const handleSubmit = (e: React.FormEvent) => {
        e.preventDefault();
        if ((text.trim() || selectedImage) && !isLoading) {
            onSendMessage(text, selectedImage || undefined);
            setText('');
            setSelectedImage(null);
        }
    };

    const handleImageSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (event) => {
                const base64 = (event.target?.result as string).split(',')[1];
                setSelectedImage({
                    data: base64,
                    mimeType: file.type
                });
            };
            reader.readAsDataURL(file);
        }
        // Reset file input value to allow selecting same file again
        e.target.value = '';
    };

    return (
        <div className="flex flex-col gap-2">
            {selectedImage && (
                <div className="flex items-center gap-2 p-2 bg-pink-50 rounded-xl animate-fade-in self-start relative">
                    <img 
                        src={`data:${selectedImage.mimeType};base64,${selectedImage.data}`} 
                        alt="Preview" 
                        className="w-16 h-16 object-cover rounded-lg shadow-sm border-2 border-white"
                    />
                    <button 
                        onClick={() => setSelectedImage(null)}
                        className="absolute -top-2 -right-2 bg-pink-500 text-white rounded-full p-1 shadow-md hover:bg-pink-600 transition-colors"
                    >
                        <XMarkIcon />
                    </button>
                </div>
            )}
            <form onSubmit={handleSubmit} className="flex items-center space-x-2 md:space-x-4">
                <input 
                    type="file" 
                    ref={fileInputRef} 
                    onChange={handleImageSelect} 
                    accept="image/*" 
                    className="hidden" 
                />
                <textarea
                    value={text}
                    onChange={(e) => setText(e.target.value)}
                    onKeyDown={(e) => {
                        if (e.key === 'Enter' && !e.shiftKey) {
                            e.preventDefault();
                            handleSubmit(e);
                        }
                    }}
                    placeholder="Type your message..."
                    className="flex-1 p-3 border border-gray-300 rounded-2xl focus:outline-none focus:ring-2 focus:ring-pink-400 resize-none shadow-sm transition disabled:bg-gray-200"
                    rows={1}
                    disabled={isLoading}
                />
                <button
                    type="button"
                    onClick={() => fileInputRef.current?.click()}
                    className="p-3 rounded-full transition-colors duration-200 ease-in-out shadow-md bg-white text-pink-500 hover:bg-pink-100 disabled:bg-gray-200"
                    disabled={isLoading}
                    aria-label="Upload image"
                >
                    <PlusCircleIcon />
                </button>
                <button
                    type="button"
                    onClick={onVoiceClick}
                    className="p-3 rounded-full transition-colors duration-200 ease-in-out shadow-md bg-white text-pink-500 hover:bg-pink-100 disabled:bg-gray-200"
                    disabled={isLoading}
                    aria-label="Use voice input"
                >
                    <MicrophoneIcon />
                </button>
                <button
                    type="submit"
                    className="p-3 bg-pink-500 text-white rounded-full hover:bg-pink-600 disabled:bg-pink-300 transition-colors duration-200 ease-in-out shadow-md"
                    disabled={isLoading || (!text.trim() && !selectedImage)}
                    aria-label="Send message"
                >
                    <SendIcon />
                </button>
            </form>
        </div>
    );
};

