import React from 'react';
import { Message, Role } from '../types';
import SpeakerIcon from './icons/SpeakerIcon';
import Avatar from './Avatar';

interface ChatMessageProps {
    message: Message;
    isPlayingAudio: boolean;
    onReplayAudio: (text: string, messageId: string) => void;
    userAvatar: string | null;
    userName: string | null;
    sifraAvatarUrl: string;
    isLoading: boolean;
    isLastMessage: boolean;
}

const ChatMessage: React.FC<ChatMessageProps> = ({ message, isPlayingAudio, onReplayAudio, userAvatar, userName, sifraAvatarUrl, isLoading, isLastMessage }) => {
    const isModel = message.role === Role.MODEL;

    const messageBg = isModel ? 'bg-purple-50/95' : 'bg-white';
    const textColor = isModel ? 'text-black' : 'text-black';
    const alignment = isModel ? 'justify-start' : 'justify-end';
    const borderRadius = isModel ? 'rounded-b-xl rounded-tr-xl' : 'rounded-b-xl rounded-tl-xl';
    const border = isModel ? '' : 'border border-gray-200';

    // Thinking indicator for empty model responses
    const showThinkingIndicator = isModel && isLoading && isLastMessage && (!message.parts[0]?.text || message.parts[0].text.length === 0);
    const showTypingCursor = isModel && isLoading && isLastMessage && (message.parts[0]?.text && message.parts[0].text.length > 0);

    return (
        <div className={`flex ${alignment} animate-fade-in-up`}>
            <div className={`flex items-start gap-2.5 max-w-lg md:max-w-xl ${isModel ? '' : 'flex-row-reverse'}`}>
                 {isModel ? (
                    <Avatar src={sifraAvatarUrl} isSifra />
                 ) : (
                    <Avatar src={userAvatar} initials={userName || 'U'} />
                 )}
                <div className={`flex flex-col gap-1 w-full`}>
                   <div className={`leading-relaxed p-4 ${messageBg} ${borderRadius} ${border} shadow-md overflow-hidden`}>
                        {message.parts.map((part, pIdx) => (
                            <React.Fragment key={pIdx}>
                                {part.inlineData && (
                                    <div className="mb-2">
                                        <img 
                                            src={`data:${part.inlineData.mimeType};base64,${part.inlineData.data}`} 
                                            alt="Sent content" 
                                            className="max-w-full rounded-lg shadow-sm"
                                        />
                                    </div>
                                )}
                                {part.text && (
                                    <p className={`text-sm font-medium ${textColor} whitespace-pre-wrap`}>
                                        {part.text}
                                        {showTypingCursor && pIdx === message.parts.length - 1 && (
                                            <span className="inline-block w-0.5 h-4 bg-black ml-1 animate-ping"></span>
                                        )}
                                    </p>
                                )}
                            </React.Fragment>
                        ))}
                        {showThinkingIndicator && (
                             <div className="flex items-center justify-center space-x-1 p-2">
                                <span className="w-2 h-2 bg-pink-400 rounded-full animate-pulse [animation-delay:-0.3s]"></span>
                                <span className="w-2 h-2 bg-pink-400 rounded-full animate-pulse [animation-delay:-0.15s]"></span>
                                <span className="w-2 h-2 bg-pink-400 rounded-full animate-pulse"></span>
                            </div>
                        )}
                    </div>
                </div>
                 {isModel && message.parts.some(p => p.text) && (
                    <button
                        onClick={() => {
                            const text = message.parts.find(p => p.text)?.text || '';
                            onReplayAudio(text, message.messageId);
                        }}
                        className="self-center p-2 -m-2 rounded-full hover:bg-black/10 transition-colors"
                        aria-label="Play audio for this message"
                    >
                        <SpeakerIcon isPlaying={isPlayingAudio} />
                    </button>
                 )}
            </div>
        </div>
    );
};

