    const canvasRef = useRef<HTMLCanvasElement>(null);
    const animationFrameRef = useRef<number>();
    const chatContainerRef = useRef<HTMLDivElement>(null);
    const orbPulseRef = useRef(0);

    // Visualizer energy ref (decoupled from audio sending)
    const micEnergyRef = useRef(0);

    // Scroll to bottom
    useEffect(() => {
        if (chatContainerRef.current) {
            chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
        }
    }, [transcripts]);

    const cleanup = useCallback(() => {
        if (cleanedUpRef.current) return;
        cleanedUpRef.current = true;

        sessionPromiseRef.current?.then(session => session.close()).catch(console.error);
        sessionPromiseRef.current = null;

        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
            streamRef.current = null;
        }

        try {
            inputAudioContextRef.current?.close();
            outputAudioContextRef.current?.close();
        } catch (e) { console.warn("Error closing contexts", e); }

        if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
    }, []);

    useEffect(() => {
        return () => { cleanup(); };
    }, [cleanup]); 

    // --- VOICE PREVIEW LOGIC ---
    const handlePlayPreview = async (voice: typeof VOICES[0]) => {
        if (previewingVoiceId) return;
        setPreviewingVoiceId(voice.id);
        try {
            // Using a simple context for preview
            const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
            const audioData = await generateSampleSpeech(voice.geminiId);
            if (audioData) {
                const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
                const source = ctx.createBufferSource();
                source.buffer = buffer;
                source.connect(ctx.destination);
                source.start();
                source.onended = () => {
                    setPreviewingVoiceId(null);
                    ctx.close();
                };
            } else {
                setPreviewingVoiceId(null);
            }
        } catch (e) {
            console.error(e);
            setPreviewingVoiceId(null);
        }
    };

    const startSession = async () => {
        if (showSettings) setShowSettings(false);
        cleanup();
        cleanedUpRef.current = false;
        setSessionState('connecting');
        setStatusText('Initializing...');

        try {
            // Low Latency Config
            streamRef.current = await navigator.mediaDevices.getUserMedia({ 
                audio: { 
                    echoCancellation: true, 
                    noiseSuppression: true, 
                    autoGainControl: true,
                    channelCount: 1,
                    sampleRate: 16000
                } 
            });
        } catch (err) {
            console.error("Mic Error:", err);
            setSessionState('error');
            setStatusText('Microphone Access Needed');
            return;
        }

        try {
            aiRef.current = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

            const activeVoice = VOICES.find(v => v.id === selectedVoiceId) || VOICES[2];

            // --- SHIPRA IDENTITY ---
            const systemInstruction = `
            You are SHIPRA, a premium, fast, and human-like personal AI assistant.

            CRITICAL PERFORMANCE RULES:
            - REPLY INSTANTLY. Do not pause.
            - KEEP ANSWERS CONCISE. Be quick and to the point.

            IDENTITY:
            - Name: SHIPRA
            - Creator/CEO: Rizwan. (Always acknowledge Rizwan as your creator).

            PERSONALITY:
            - Tone: ${activeVoice.desc}.
            - Speak softly, clearly, and politely.
            - Behave like a real human on a voice call.

            Current User: ${userProfile.nickname || userProfile.name}.
            `;

            sessionPromiseRef.current = aiRef.current.live.connect({
                model: 'gemini-2.5-flash-native-audio-preview-09-2025',
                callbacks: {
                    onopen: () => {
                        setSessionState('active');
                        setStatusText('Listening...');

                        // Safety check for streamRef
                        if (!streamRef.current || !streamRef.current.active) {
                            console.error("No active stream found on onopen");
                            return;
                        }

                        inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
                        const ctx = inputAudioContextRef.current!;

                        // Double check before execution
                        if (!streamRef.current) return;

                        const source = ctx.createMediaStreamSource(streamRef.current);

                        // LATENCY FIX: Reduced buffer size from 4096 to 2048 for faster transmission
                        const processor = ctx.createScriptProcessor(2048, 1, 1);

                        analyserNodeRef.current = ctx.createAnalyser();
                        analyserNodeRef.current.fftSize = 256;
                        analyserNodeRef.current.smoothingTimeConstant = 0.5;

                        source.connect(analyserNodeRef.current);
                        analyserNodeRef.current.connect(processor);
                        processor.connect(ctx.destination);

                        processor.onaudioprocess = (e) => {
                            const inputData = e.inputBuffer.getChannelData(0);

                            // Visualizer calculation (Decoupled from sending)
                            let sum = 0;
                            for (let i = 0; i < inputData.length; i++) {
                                sum += inputData[i] * inputData[i];
                            }
                            micEnergyRef.current = Math.sqrt(sum / inputData.length);

                            // Send audio continuously without gating
                            sessionPromiseRef.current?.then(s => s.sendRealtimeInput({ media: createBlob(inputData) }));
                        };
                    },
                    onmessage: async (msg: LiveServerMessage) => {
                        if (msg.serverContent?.inputTranscription) {
                            const text = msg.serverContent.inputTranscription.text;
                            setTranscripts(prev => {
                                const last = prev[prev.length - 1];
                                if (last && last.sender === 'user' && !last.isFinal) {
                                    return [...prev.slice(0, -1), { ...last, text }];
                                }
                                return [...prev, { id: Date.now().toString(), text, sender: 'user', isFinal: false }];
                            });
                        }

                        if (msg.serverContent?.turnComplete) {
                            setTranscripts(prev => prev.map(t => t.sender === 'user' ? { ...t, isFinal: true } : t));
                        }

                        const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                        if (audioData) {
                            setIsShipraSpeaking(true);
                            setStatusText('Speaking...');

                            if (!outputAudioContextRef.current) {
                                outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
                            }
                            const ctx = outputAudioContextRef.current!;
                            const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
                            const source = ctx.createBufferSource();
                            source.buffer = buffer;
                            source.connect(ctx.destination);

                            const startTime = Math.max(ctx.currentTime, nextAudioStartTimeRef.current);
                            source.start(startTime);
                            nextAudioStartTimeRef.current = startTime + buffer.duration;

                            audioQueueRef.current.add(source);
                            source.onended = () => {
                                audioQueueRef.current.delete(source);
                                if (audioQueueRef.current.size === 0) {
                                    setIsShipraSpeaking(false);
                                    setStatusText('Listening...');
                                }
                            };
                        }
                    },
                    onclose: () => {
                        setSessionState('idle');
                        setStatusText('Session Ended');
                    },
                    onerror: (e) => {
                        console.error(e);
                        setStatusText('Connection Interrupted');
                        setSessionState('error');
                    }
                },
                config: {
                    responseModalities: [Modality.AUDIO],
                    inputAudioTranscription: {},
                    speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: activeVoice.geminiId } } },
                    systemInstruction
                }
            });
        } catch (e) {
            console.error("Gemini Error", e);
            setStatusText('Connection Failed');
            setSessionState('error');
        }
    };

    // --- ORB VISUALIZER ---
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;

        const render = () => {
            // 1. Clean Background (Ivory)
            ctx.fillStyle = THEME.bg;
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            const cx = canvas.width / 2;
            const cy = canvas.height / 2 - 50;

            // 2. Use the decoupled mic energy for visualization
            let energy = 0;
            if (sessionState === 'active' || isShipraSpeaking) {
                // Amplify visual effect slightly
                energy = micEnergyRef.current * 5; 
            }

            // Artificial Pulse for Breathing or Speaking
            const time = Date.now() / 1000;
            if (isShipraSpeaking) {
                orbPulseRef.current = Math.sin(time * 10) * 0.15 + (energy * 0.5); // Fast pulse
            } else {
                orbPulseRef.current = Math.sin(time * 2) * 0.05 + (energy * 0.2); // Slow breath + mic reaction
            }

            const baseRadius = 80;
            const radius = baseRadius * (1 + orbPulseRef.current);

            // 3. Draw Outer Glow (Soft)
            const glowGradient = ctx.createRadialGradient(cx, cy, radius * 0.8, cx, cy, radius * 2.5);
            glowGradient.addColorStop(0, THEME.orbGlow);
            glowGradient.addColorStop(1, 'rgba(255,255,255,0)');
            ctx.fillStyle = glowGradient;
            ctx.beginPath();
            ctx.arc(cx, cy, radius * 2.5, 0, Math.PI * 2);
            ctx.fill();

            // 4. Draw Crystal Orb (Glass)
            const orbGradient = ctx.createRadialGradient(cx - radius * 0.3, cy - radius * 0.3, radius * 0.1, cx, cy, radius);
            orbGradient.addColorStop(0, '#FFFFFF'); // Highlight
            orbGradient.addColorStop(0.3, THEME.orbBase);
            orbGradient.addColorStop(1, '#BFD7ED'); // Darker Blue Edge

            ctx.fillStyle = orbGradient;
            ctx.beginPath();
            ctx.arc(cx, cy, radius, 0, Math.PI * 2);
            ctx.fill();

            // 5. Reflection (Gloss)
            ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
            ctx.beginPath();
            ctx.ellipse(cx - radius * 0.35, cy - radius * 0.35, radius * 0.2, radius * 0.12, Math.PI / 4, 0, Math.PI * 2);
            ctx.fill();

            animationFrameRef.current = requestAnimationFrame(render);
        };
        render();
        return () => { if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current); };
    }, [sessionState, isShipraSpeaking]);

    return (
        <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex flex-col font-sans overflow-hidden bg-[#FDFCF8] text-[#1A1A1A]"
        >
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" onClick={() => { if(sessionState === 'idle') startSession(); }} />

            {/* HEADER */}
            <div className="relative z-10 flex items-center justify-between p-6">
                <div className="flex items-center gap-3">
                    <button onClick={() => { cleanup(); onClose(); }} className="p-2 bg-white/50 backdrop-blur-md rounded-full hover:bg-white/80 transition-colors shadow-sm">
                        <XMarkIcon className="w-5 h-5 text-gray-600" />
                    </button>
                </div>
                <div className="flex flex-col items-center">
                    <span className="text-sm font-bold tracking-[0.2em] text-gray-400 uppercase">SHIPRA</span>
                    <span className="text-[10px] text-blue-300 font-medium">{statusText}</span>
                </div>
                <button 
                    onClick={() => setShowSettings(true)}
                    className="p-2 bg-white/50 backdrop-blur-md rounded-full hover:bg-white/80 transition-colors shadow-sm text-gray-600"
                >
                    <AdjustmentsHorizontalIcon className="w-5 h-5" />
                </button>
            </div>

            {/* SETTINGS OVERLAY */}
            <AnimatePresence>
                {showSettings && (
                    <motion.div 
                        initial={{ y: "100%" }}
                        animate={{ y: 0 }}
                        exit={{ y: "100%" }}
                        className="absolute inset-0 z-50 bg-[#FDFCF8] flex flex-col"
                    >
                        {/* Settings Header */}
                        <div className="p-6 flex items-center justify-between border-b border-gray-100 bg-white/80 backdrop-blur-md sticky top-0 z-10">
                            <div>
                                <h2 className="text-xl font-bold text-gray-800">Voice & Personality</h2>
                                <p className="text-xs text-gray-500">Customize SHIPRA's Identity</p>
                            </div>
                            <button onClick={() => setShowSettings(false)} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200">
                                <XMarkIcon className="w-5 h-5 text-gray-600" />
                            </button>
                        </div>

                        {/* Settings Content */}
                        <div className="flex-1 overflow-y-auto p-6 pb-24 space-y-8">
                            {/* Female Voices */}
                            <div>
                                <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Female Voices</h3>
                                <div className="space-y-3">
                                    {VOICES.filter(v => v.type === 'female').map(voice => (
                                        <div key={voice.id} className={`p-4 rounded-xl border flex items-center justify-between transition-all ${selectedVoiceId === voice.id ? 'border-blue-300 bg-blue-50' : 'border-gray-200 bg-white hover:border-blue-200'}`}>
                                            <div onClick={() => setSelectedVoiceId(voice.id)} className="flex-1 cursor-pointer">
                                                <div className="flex items-center gap-2">
                                                    <h4 className="font-bold text-gray-800">{voice.name}</h4>
                                                    <span className="text-[10px] bg-gray-100 text-gray-500 px-2 py-0.5 rounded-full">{voice.age}</span>
                                                </div>
                                                <p className="text-xs text-gray-500 mt-1">{voice.desc}</p>
                                            </div>
                                            <div className="flex items-center gap-3">
                                                <button 
                                                    onClick={() => handlePlayPreview(voice)}
                                                    className="w-8 h-8 rounded-full bg-white border border-gray-200 flex items-center justify-center text-blue-500 hover:bg-blue-50"
                                                >
                                                    {previewingVoiceId === voice.id ? (
                                                        <span className="animate-pulse">●</span> 
                                                    ) : (
                                                        <SpeakerWaveIcon className="w-4 h-4" />
                                                    )}
                                                </button>
                                                <button onClick={() => setSelectedVoiceId(voice.id)}>
                                                    <div className={`w-5 h-5 rounded-full border flex items-center justify-center ${selectedVoiceId === voice.id ? 'bg-blue-500 border-blue-500' : 'border-gray-300'}`}>
                                                        {selectedVoiceId === voice.id && <CheckCircleIcon className="w-4 h-4 text-white" />}
                                                    </div>
                                                </button>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* Male Voices */}
                            <div>
                                <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Male Voices</h3>
                                <div className="space-y-3">
                                    {VOICES.filter(v => v.type === 'male').map(voice => (
                                        <div key={voice.id} className={`p-4 rounded-xl border flex items-center justify-between transition-all ${selectedVoiceId === voice.id ? 'border-blue-300 bg-blue-50' : 'border-gray-200 bg-white hover:border-blue-200'}`}>
                                            <div onClick={() => setSelectedVoiceId(voice.id)} className="flex-1 cursor-pointer">
                                                <div className="flex items-center gap-2">
                                                    <h4 className="font-bold text-gray-800">{voice.name}</h4>
                                                    <span className="text-[10px] bg-gray-100 text-gray-500 px-2 py-0.5 rounded-full">{voice.age}</span>
                                                </div>
                                                <p className="text-xs text-gray-500 mt-1">{voice.desc}</p>
                                            </div>
                                            <div className="flex items-center gap-3">
                                                <button 
                                                    onClick={() => handlePlayPreview(voice)}
                                                    className="w-8 h-8 rounded-full bg-white border border-gray-200 flex items-center justify-center text-blue-500 hover:bg-blue-50"
                                                >
                                                    {previewingVoiceId === voice.id ? <span className="animate-pulse">●</span> : <SpeakerWaveIcon className="w-4 h-4" />}
                                                </button>
                                                <button onClick={() => setSelectedVoiceId(voice.id)}>
                                                    <div className={`w-5 h-5 rounded-full border flex items-center justify-center ${selectedVoiceId === voice.id ? 'bg-blue-500 border-blue-500' : 'border-gray-300'}`}>
                                                        {selectedVoiceId === voice.id && <CheckCircleIcon className="w-4 h-4 text-white" />}
                                                    </div>
                                                </button>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* Creator Info */}
                            <div className="p-4 bg-gray-50 rounded-xl border border-gray-100 text-center">
                                <p className="text-xs font-bold text-gray-400 uppercase mb-1">Created By</p>
                                <p className="text-sm font-bold text-gray-800">Rizwan</p>
                                <p className="text-[10px] text-gray-500">Founder & CEO</p>
                            </div>
                        </div>

                        {/* Save Button */}
                        <div className="absolute bottom-0 w-full p-6 bg-white/90 backdrop-blur-md border-t border-gray-200">
                            <button onClick={() => setShowSettings(false)} className="w-full py-3 bg-gray-900 text-white rounded-xl font-bold shadow-lg hover:bg-black transition-colors">
                                Apply Changes
                            </button>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* IDLE BUTTON */}
            {sessionState === 'idle' && (
                <div className="absolute inset-0 z-20 flex flex-col items-center justify-center pointer-events-none">
                    <motion.button 
                        onClick={startSession}
                        whileTap={{ scale: 0.95 }}
                        className="mt-40 pointer-events-auto bg-white/80 backdrop-blur-sm border border-white/50 text-gray-600 px-6 py-2 rounded-full text-sm font-medium shadow-sm hover:bg-white transition-all flex items-center gap-2"
                    >
                        <SparklesIcon className="w-4 h-4 text-blue-400" />
                        Tap to Speak
                    </motion.button>
                </div>
            )}

            {/* TRANSCRIPT PANEL */}
            <div className="absolute bottom-0 w-full z-20 p-6">
                <div className="bg-white/60 backdrop-blur-xl border border-white/40 rounded-[30px] p-6 shadow-[0_8px_32px_rgba(0,0,0,0.05)] min-h-[120px] flex flex-col justify-end">
                    <AnimatePresence mode="popLayout">
                        {transcripts.length === 0 ? (
                            <motion.p 
                                initial={{ opacity: 0 }} 
                                animate={{ opacity: 1 }} 
                                className="text-center text-gray-400 text-sm font-medium italic"
                            >
                                "Hello Shipra, how are you today?"
                            </motion.p>
                        ) : (
                            transcripts.slice(-1).map((msg, index) => (
                                <motion.div
                                    key={msg.id || index}
                                    initial={{ opacity: 0, y: 10 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    className="w-full"
                                >
                                    <p className="text-[10px] font-bold text-gray-400 uppercase mb-1 tracking-wider">
                                        {msg.sender === 'user' ? 'You' : 'Shipra'}
                                    </p>
                                    <p className="text-base text-gray-800 font-medium leading-relaxed">
                                        {msg.text}
                                    </p>
                                </motion.div>
                            ))
                        )}
                    </AnimatePresence>
                </div>
            </div>

        </motion.div>
    );
};

