                            </p>
                        </div>
                    </div>

                    <div className="space-y-1">
                        <DetailRow label="System Status" value={isTierActive ? "Verified Online" : "Inactive Node"} color={isTierActive ? "text-emerald-600" : "text-slate-400"} />
                        <DetailRow label="Asset Version" value={activePage === 1 ? "v2.8.4 Stable" : activePage === 2 ? "v3.0.0 Alpha" : "v5.1.0 Experimental"} color="text-slate-700" />
                        <DetailRow label="Deployment" value={isTierActive ? formatDate(issueDate) : "Access Denied"} disabled={!isTierActive} />
                        <DetailRow label="End Validation" value={isTierActive ? formatDate(expiryDate) : "Access Denied"} disabled={!isTierActive} color="text-rose-500" />
                    </div>

                    {!isTierActive && (
                        <div className="mt-8 pt-8 border-t border-slate-100">
                            <h4 className="text-[9px] font-black text-slate-400 uppercase tracking-[0.25em] mb-5">Subscription Gateways</h4>
