                                <PaymentButton icon="🏦" name="Net Banking" onClick={() => setShowComingSoon(true)} />
                                <PaymentButton icon="📱" name="UPI / QR" onClick={() => setShowComingSoon(true)} />
                                <PaymentButton icon="💳" name="Cards" onClick={() => setShowComingSoon(true)} />
                                <PaymentButton icon="🌐" name="International" onClick={() => setShowComingSoon(true)} />
                            </div>
                            <div className="mt-6 flex flex-wrap gap-4 justify-center opacity-20 filter grayscale">
                                <span className="text-[9px] font-black">SBI</span>
                                <span className="text-[9px] font-black">ICICI</span>
                                <span className="text-[9px] font-black">VISA</span>
                                <span className="text-[9px] font-black">RUPAY</span>
                            </div>
                        </div>
                    )}
                </div>

                {/* NAVIGATION BUTTONS */}
                <div className="flex justify-center gap-8">
                    {[1, 2, 3].map((num) => (
                        <button 
                            key={num}
                            onClick={() => handleSwitchPage(num)}
                            className={`w-14 h-14 rounded-2xl font-black text-sm transition-all flex items-center justify-center relative ${
                                activePage === num 
                                    ? 'bg-slate-900 text-white shadow-xl scale-110' 
                                    : 'bg-white text-slate-400 border border-slate-100 hover:bg-slate-50'
                            }`}
                        >
                            {num}
                            {num === 1 && (
                                <div className="absolute -top-1 -right-1 w-3 h-3 rounded-full bg-emerald-500 border-2 border-white" />
                            )}
                        </button>
                    ))}
                </div>

                <div className="text-center pt-2">
                    <p className="text-[9px] font-black text-slate-300 uppercase tracking-[0.4em]">Asset Page 0{activePage} of 03</p>
                </div>

            </main>

            {/* OVERLAY */}
            <AnimatePresence>
                {showComingSoon && (
                    <motion.div
                        initial={{ opacity: 0 }}
                        animate={{ opacity: 1 }}
                        exit={{ opacity: 0 }}
                        className="fixed inset-0 z-[200] flex items-center justify-center p-6 bg-black/70 backdrop-blur-sm"
                    >
                        <motion.div
                            initial={{ scale: 0.9, y: 20 }}
                            animate={{ scale: 1, y: 0 }}
                            exit={{ scale: 0.9, y: 20 }}
                            className="bg-white rounded-[2.5rem] p-8 max-w-sm w-full text-center shadow-2xl"
                        >
                            <div className="w-16 h-16 rounded-full bg-amber-50 flex items-center justify-center mx-auto mb-6">
                                <BoltIcon className="w-8 h-8 text-amber-500" />
                            </div>
                            <h2 className="text-xl font-black text-slate-900 tracking-tight mb-2">Gateways Offline</h2>
                            <p className="text-slate-500 text-xs leading-relaxed mb-8">
                                Payment integrations for this tier are currently in development. This feature will be available in the next core update.
                            </p>
                            <button 
                                onClick={() => setShowComingSoon(false)}
                                className="w-full py-4 bg-slate-900 text-white rounded-2xl font-bold transition-all active:scale-95"
                            >
                                Acknowledged
                            </button>
                        </motion.div>
                    </motion.div>
                )}
            </AnimatePresence>

            <style>{`
                .perspective-1000 { perspective: 1000px; }
                .preserve-3d { transform-style: preserve-3d; }
                .backface-hidden { backface-visibility: hidden; }
                .rotate-y-180 { transform: rotateY(180deg); }
            `}</style>
        </div>
    );
};

