import React, { useState } from 'react';
import { useLocalStorage } from '../hooks/useLocalStorage';
import { UserProfile } from '../types';

interface LoginViewProps {
    onLoginSuccess: (user: UserProfile) => void;
}

const LoginView: React.FC<LoginViewProps> = ({ onLoginSuccess }) => {
    const [view, setView] = useState<'login' | 'register'>('login');
    const [name, setName] = useState('');
    const [email, setEmail] = useState('');
    const [info, setInfo] = useState<{ type: 'success' | 'error' | 'info'; message: string } | null>(null);
    const [allUsers, setAllUsers] = useLocalStorage<UserProfile[]>('sifra_all_users', []);

    // New 5-character ID pattern: 4 numbers, 1 letter in middle (e.g. 12A34)
    const generateSifraId = (): string => {
        const digits = '0123456789';
        const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
        const n1 = digits[Math.floor(Math.random() * 10)];
        const n2 = digits[Math.floor(Math.random() * 10)];
        const l = letters[Math.floor(Math.random() * 26)];
        const n3 = digits[Math.floor(Math.random() * 10)];
        const n4 = digits[Math.floor(Math.random() * 10)];
        return `${n1}${n2}${l}${n3}${n4}`;
    };

    const handleLogin = (e: React.FormEvent) => {
        e.preventDefault();
        const foundUser = allUsers.find(u => u.email?.toLowerCase() === email.toLowerCase() && u.name === name);
        if (foundUser) {
            setInfo({ type: 'success', message: `Welcome back!` });
            onLoginSuccess(foundUser);
        } else {
            setInfo({ type: 'error', message: 'No account found. Check details or register.' });
        }
    };

    const handleRegister = (e: React.FormEvent) => {
        e.preventDefault();
        const userExists = allUsers.some(u => u.email?.toLowerCase() === email.toLowerCase());
        if (userExists) {
            setInfo({ type: 'error', message: 'Email already registered.' });
            return;
        }

        const newUser: UserProfile = {
            name: name.trim(),
            nickname: null,
            email: email.trim().toLowerCase(),
            avatar: null,
            themeId: 'default',
            sifraAvatarId: 'classic',
            saveHistory: true,
            userId: generateSifraId(),
            joinDate: new Date().toISOString(),
            status: 'active',
            lastLogin: new Date().toISOString(),
            moodAmbienceEnabled: false,
        };

        setAllUsers([...allUsers, newUser]);
        setInfo({ type: 'success', message: `Registered!` });
        onLoginSuccess(newUser);
    };

    const skipLogin = () => {
         const guestUser: UserProfile = {
            name: 'Guest',
            nickname: null,
            email: null,
            avatar: null,
            themeId: 'default',
            sifraAvatarId: 'classic',
            saveHistory: false, 
            userId: generateSifraId(),
            joinDate: new Date().toISOString(),
            status: 'active',
            lastLogin: new Date().toISOString(),
            moodAmbienceEnabled: false,
        };
        onLoginSuccess(guestUser);
    };

    return (
        <div className="w-screen h-screen bg-gradient-to-br from-pink-200 via-purple-200 to-indigo-300 flex items-center justify-center p-4 font-sans">
            <div className="w-full max-w-md bg-white/60 backdrop-blur-lg p-8 rounded-2xl shadow-xl transition-all duration-500 animate-fade-in-up">
                <div className="text-center mb-8">
                    <h1 className="text-4xl font-bold text-gray-800 mb-2">Sifra AI</h1>
                    <p className="text-gray-600">Your Intelligent Companion</p>
                </div>

                {view === 'login' ? (
                    <form onSubmit={handleLogin} className="space-y-4">
                        <input 
                            type="text" 
                            value={name} 
                            onChange={e => setName(e.target.value)}
                            placeholder="Enter your name"
                            className="w-full p-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-pink-400 bg-white/80"
                            required
                        />
                        <input 
                            type="email" 
                            value={email} 
                            onChange={e => setEmail(e.target.value)}
                            placeholder="Enter your email"
                            className="w-full p-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-pink-400 bg-white/80"
                            required
                        />
                        {info && <p className={`text-xs text-center ${info.type === 'error' ? 'text-red-500' : 'text-green-600'}`}>{info.message}</p>}

                        <button type="submit" className="w-full py-3 bg-pink-500 text-white font-bold rounded-xl shadow-lg hover:bg-pink-600 transition-transform transform hover:scale-105">
                            Login
                        </button>

                         <div className="flex justify-between items-center text-sm text-gray-600 mt-4">
                             <button type="button" onClick={() => setView('register')} className="hover:text-pink-600 underline">Create Account</button>
                             <button type="button" onClick={skipLogin} className="hover:text-pink-600 underline">Guest Mode</button>
                        </div>
                    </form>
                ) : (
                     <form onSubmit={handleRegister} className="space-y-4">
                        <input 
                            type="text" 
                            value={name} 
                            onChange={e => setName(e.target.value)}
                            placeholder="Choose a name"
                            className="w-full p-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-pink-400 bg-white/80"
                            required
                        />
                        <input 
                            type="email" 
                            value={email} 
                            onChange={e => setEmail(e.target.value)}
                            placeholder="Enter your email"
                            className="w-full p-3 border border-gray-300 rounded-xl focus:outline-none focus:ring-2 focus:ring-pink-400 bg-white/80"
                            required
                        />
                        {info && <p className={`text-xs text-center ${info.type === 'error' ? 'text-red-500' : 'text-green-600'}`}>{info.message}</p>}

                        <button type="submit" className="w-full py-3 bg-purple-500 text-white font-bold rounded-xl shadow-lg hover:bg-purple-600 transition-transform transform hover:scale-105">
                            Register
                        </button>
                         <div className="text-center text-sm text-gray-600 mt-4">
                             <button type="button" onClick={() => setView('login')} className="hover:text-pink-600 underline">Back to Login</button>
                        </div>
                    </form>
                )}
            </div>
        </div>
    );
};

export default LoginView;

import React, { useState } from 'react';
import { UserProfile } from '../types';

interface OnboardingViewProps {
  onOnboardingComplete: (newUser: UserProfile) => void;
}

const OnboardingView: React.FC<OnboardingViewProps> = ({ onOnboardingComplete }) => {
  const [name, setName] = useState('');
  const [showInput, setShowInput] = useState(false);

  const generateSifraId = (): string => {
    const digits = '0123456789';
    const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
    const n1 = digits[Math.floor(Math.random() * 10)];
    const n2 = digits[Math.floor(Math.random() * 10)];
    const l = letters[Math.floor(Math.random() * 26)];
    const n3 = digits[Math.floor(Math.random() * 10)];
    const n4 = digits[Math.floor(Math.random() * 10)];
    return `${n1}${n2}${l}${n3}${n4}`;
  };

  const handleConfirm = () => {
    const trimmedName = name.trim();
    if (!trimmedName) {
      alert("Please enter your name.");
      return;
    }

    const newUser: UserProfile = {
      name: trimmedName,
      nickname: null,
      avatar: null,
      themeId: 'default',
      sifraAvatarId: 'classic',
      saveHistory: true,
      userId: generateSifraId(),
      joinDate: new Date().toISOString(),
      status: 'active',
      lastLogin: new Date().toISOString(),
      moodAmbienceEnabled: false,
    };

    onOnboardingComplete(newUser);
  };

  return (
    <div className="w-screen h-screen bg-gradient-to-br from-pink-200 via-purple-200 to-indigo-300 flex items-center justify-center p-4 font-sans">
      <div className="w-full max-w-md text-center bg-white/50 backdrop-blur-lg p-8 rounded-2xl shadow-xl transition-all duration-500">
        {!showInput ? (
          <div className="animate-fade-in">
            <h1 className="text-4xl font-bold text-gray-800 mb-2">Welcome to Sifra</h1>
            <p className="text-gray-600 mb-8">Your personal AI friend is ready to chat. Let's get started!</p>
            <button
              onClick={() => setShowInput(true)}
              className="px-8 py-3 bg-pink-500 text-white font-bold rounded-full shadow-lg hover:bg-pink-600 transition-transform transform hover:scale-105"
            >
              Start
            </button>
          </div>
        ) : (
          <div className="animate-fade-in">
            <h2 className="text-2xl font-bold text-gray-800 mb-4">What should I call you?</h2>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleConfirm()}
              placeholder="Enter your name here..."
              className="w-full p-3 border border-gray-300 rounded-xl text-center shadow-sm focus:outline-none focus:ring-2 focus:ring-pink-400"
              autoFocus
            />
            <button
              onClick={handleConfirm}
              disabled={!name.trim()}
              className="mt-4 w-full px-8 py-3 bg-pink-500 text-white font-bold rounded-xl shadow-lg hover:bg-pink-600 transition-colors disabled:bg-pink-300 disabled:cursor-not-allowed"
            >
              Confirm
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

