            ctx.clearRect(0, 0, canvas.width, canvas.height);
            const cx = canvas.width / 2;
            const cy = canvas.height / 2;

            let vol = 0;
            if (analyserRef.current) {
                const data = new Uint8Array(analyserRef.current.frequencyBinCount);
                analyserRef.current.getByteTimeDomainData(data);
                let sum = 0;
                for(let i=0; i<data.length; i++) sum += Math.abs(data[i] - 128);
                vol = sum / data.length / 128;
            }

            time += 0.02;
            const energy = (isAiSpeaking ? 0.3 : 0) + (isListening ? vol * 10 : 0) + Math.sin(time * 2) * 0.05;

            ctx.save();
            ctx.translate(cx, cy);

            if (activeTheme === 'aura') {
                // AURA: Soft nebulous glow
                for (let i = 0; i < 3; i++) {
                    const radius = (80 + i * 40) * (1 + energy);
                    const grd = ctx.createRadialGradient(0, 0, radius * 0.5, 0, 0, radius);
                    grd.addColorStop(0, `rgba(255, 42, 109, ${0.4 - i * 0.1})`);
                    grd.addColorStop(1, 'transparent');
                    ctx.fillStyle = grd;
                    ctx.beginPath();
                    ctx.arc(0, 0, radius, 0, Math.PI * 2);
                    ctx.fill();
                }
            } else if (activeTheme === 'crystal') {
                // CRYSTAL: Refractive glass ball
                const r = 100 * (1 + energy * 0.5);
                const grd = ctx.createRadialGradient(-r * 0.3, -r * 0.3, r * 0.1, 0, 0, r);
                grd.addColorStop(0, '#ffffff');
                grd.addColorStop(0.2, '#ff8ab0');
                grd.addColorStop(1, '#2b0a1a');
                ctx.fillStyle = grd;
                ctx.beginPath();
                ctx.arc(0, 0, r, 0, Math.PI * 2);
                ctx.fill();
                // Shine
                ctx.fillStyle = 'rgba(255,255,255,0.6)';
                ctx.beginPath();
                ctx.ellipse(-r*0.4, -r*0.4, r*0.2, r*0.1, Math.PI/4, 0, Math.PI*2);
                ctx.fill();
            } else if (activeTheme === 'galaxy') {
                // GALAXY: Swirling particles
                for (let i = 0; i < 50; i++) {
                    const angle = time + i * 0.3;
                    const dist = (60 + Math.sin(time + i) * 20) * (1 + energy);
                    const x = Math.cos(angle) * dist;
                    const y = Math.sin(angle) * dist;
                    ctx.fillStyle = i % 2 === 0 ? '#ff2a6d' : '#05d9e8';
                    ctx.beginPath();
                    ctx.arc(x, y, 2, 0, Math.PI * 2);
                    ctx.fill();
                }
            } else if (activeTheme === 'neural') {
                // NEURAL: Pulsing core with nodes
                const r = 60 * (1 + energy);
                ctx.strokeStyle = '#ff2a6d';
                ctx.lineWidth = 2;
                ctx.beginPath();
                for (let i = 0; i < 6; i++) {
                    const a = (Math.PI * 2 / 6) * i + time;
                    const x = Math.cos(a) * r;
                    const y = Math.sin(a) * r;
                    ctx.moveTo(0, 0);
                    ctx.lineTo(x, y);
                    ctx.stroke();
                    ctx.fillStyle = '#fff';
                    ctx.beginPath();
                    ctx.arc(x, y, 4, 0, Math.PI * 2);
                    ctx.fill();
                }
                ctx.fillStyle = '#ff2a6d';
                ctx.beginPath();
                ctx.arc(0, 0, 20, 0, Math.PI * 2);
                ctx.fill();
            } else if (activeTheme === 'prism') {
                // PRISM: Overlapping color waves
                ctx.globalAlpha = 0.5;
                for (let i = 0; i < 3; i++) {
                    ctx.fillStyle = ['#ff2a6d', '#05d9e8', '#fdfcf8'][i];
                    const r = (70 + i * 20) * (1 + energy);
                    ctx.beginPath();
                    for (let a = 0; a < Math.PI * 2; a += 0.5) {
                        const dr = Math.sin(time * 3 + a * 2 + i) * 15;
                        const x = Math.cos(a) * (r + dr);
                        const y = Math.sin(a) * (r + dr);
                        if (a === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
                    }
                    ctx.closePath();
                    ctx.fill();
                }
            }

            ctx.restore();
            animationFrameRef.current = requestAnimationFrame(render);
        };
        render();
    }, [activeTheme, isAiSpeaking, isListening]);

    if (!setupData) return <SetupWizard onComplete={setSetupData} onCancel={onClose} />;

    return (
        <div className="fixed inset-0 z-[200] bg-black font-sans overflow-hidden select-none">
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />
            <motion.div initial={{opacity:0}} animate={{opacity:1}} className="absolute top-0 left-0 w-full p-10 flex justify-between items-start z-30">
                <div className="flex flex-col gap-6">
                    <div className="flex items-center gap-4">
