                <div className="flex items-center gap-3">
                    <button onClick={() => { cleanup(); onClose(); }} className="p-2 bg-white/50 backdrop-blur-md rounded-full hover:bg-white/80 transition-colors shadow-sm">
                        <XMarkIcon className="w-5 h-5 text-gray-600" />
                    </button>
                </div>
                <div className="flex flex-col items-center">
                    <span className="text-sm font-bold tracking-[0.2em] text-gray-400 uppercase">SHIPRA</span>
                    <span className="text-[10px] text-blue-300 font-medium">{statusText}</span>
                </div>
                <button 
                    onClick={() => setShowSettings(true)}
                    className="p-2 bg-white/50 backdrop-blur-md rounded-full hover:bg-white/80 transition-colors shadow-sm text-gray-600"
                >
                    <AdjustmentsHorizontalIcon className="w-5 h-5" />
                </button>
            </div>

            {/* SETTINGS OVERLAY */}
            <AnimatePresence>
                {showSettings && (
                    <motion.div 
                        initial={{ y: "100%" }}
                        animate={{ y: 0 }}
                        exit={{ y: "100%" }}
                        className="absolute inset-0 z-50 bg-[#FDFCF8] flex flex-col"
                    >
                        {/* Settings Header */}
                        <div className="p-6 flex items-center justify-between border-b border-gray-100 bg-white/80 backdrop-blur-md sticky top-0 z-10">
                            <div>
                                <h2 className="text-xl font-bold text-gray-800">Voice & Personality</h2>
                                <p className="text-xs text-gray-500">Customize SHIPRA's Identity</p>
                            </div>
                            <button onClick={() => setShowSettings(false)} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200">
                                <XMarkIcon className="w-5 h-5 text-gray-600" />
                            </button>
                        </div>

                        {/* Settings Content */}
                        <div className="flex-1 overflow-y-auto p-6 pb-24 space-y-8">
                            {/* Female Voices */}
                            <div>
                                <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Female Voices</h3>
                                <div className="space-y-3">
                                    {VOICES.filter(v => v.type === 'female').map(voice => (
                                        <div key={voice.id} className={`p-4 rounded-xl border flex items-center justify-between transition-all ${selectedVoiceId === voice.id ? 'border-blue-300 bg-blue-50' : 'border-gray-200 bg-white hover:border-blue-200'}`}>
                                            <div onClick={() => setSelectedVoiceId(voice.id)} className="flex-1 cursor-pointer">
                                                <div className="flex items-center gap-2">
                                                    <h4 className="font-bold text-gray-800">{voice.name}</h4>
                                                    <span className="text-[10px] bg-gray-100 text-gray-500 px-2 py-0.5 rounded-full">{voice.age}</span>
                                                </div>
                                                <p className="text-xs text-gray-500 mt-1">{voice.desc}</p>
                                            </div>
                                            <div className="flex items-center gap-3">
                                                <button 
                                                    onClick={() => handlePlayPreview(voice)}
                                                    className="w-8 h-8 rounded-full bg-white border border-gray-200 flex items-center justify-center text-blue-500 hover:bg-blue-50"
                                                >
                                                    {previewingVoiceId === voice.id ? (
                                                        <span className="animate-pulse">●</span> 
                                                    ) : (
                                                        <SpeakerWaveIcon className="w-4 h-4" />
                                                    )}
                                                </button>
                                                <button onClick={() => setSelectedVoiceId(voice.id)}>
                                                    <div className={`w-5 h-5 rounded-full border flex items-center justify-center ${selectedVoiceId === voice.id ? 'bg-blue-500 border-blue-500' : 'border-gray-300'}`}>
                                                        {selectedVoiceId === voice.id && <CheckCircleIcon className="w-4 h-4 text-white" />}
                                                    </div>
                                                </button>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* Male Voices */}
                            <div>
                                <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Male Voices</h3>
                                <div className="space-y-3">
                                    {VOICES.filter(v => v.type === 'male').map(voice => (
                                        <div key={voice.id} className={`p-4 rounded-xl border flex items-center justify-between transition-all ${selectedVoiceId === voice.id ? 'border-blue-300 bg-blue-50' : 'border-gray-200 bg-white hover:border-blue-200'}`}>
                                            <div onClick={() => setSelectedVoiceId(voice.id)} className="flex-1 cursor-pointer">
                                                <div className="flex items-center gap-2">
                                                    <h4 className="font-bold text-gray-800">{voice.name}</h4>
                                                    <span className="text-[10px] bg-gray-100 text-gray-500 px-2 py-0.5 rounded-full">{voice.age}</span>
                                                </div>
                                                <p className="text-xs text-gray-500 mt-1">{voice.desc}</p>
                                            </div>
                                            <div className="flex items-center gap-3">
                                                <button 
                                                    onClick={() => handlePlayPreview(voice)}
                                                    className="w-8 h-8 rounded-full bg-white border border-gray-200 flex items-center justify-center text-blue-500 hover:bg-blue-50"
                                                >
                                                    {previewingVoiceId === voice.id ? <span className="animate-pulse">●</span> : <SpeakerWaveIcon className="w-4 h-4" />}
                                                </button>
                                                <button onClick={() => setSelectedVoiceId(voice.id)}>
                                                    <div className={`w-5 h-5 rounded-full border flex items-center justify-center ${selectedVoiceId === voice.id ? 'bg-blue-500 border-blue-500' : 'border-gray-300'}`}>
                                                        {selectedVoiceId === voice.id && <CheckCircleIcon className="w-4 h-4 text-white" />}
                                                    </div>
                                                </button>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* Creator Info */}
                            <div className="p-4 bg-gray-50 rounded-xl border border-gray-100 text-center">
                                <p className="text-xs font-bold text-gray-400 uppercase mb-1">Created By</p>
                                <p className="text-sm font-bold text-gray-800">Rizwan</p>
                                <p className="text-[10px] text-gray-500">Founder & CEO</p>
                            </div>
                        </div>

                        {/* Save Button */}
                        <div className="absolute bottom-0 w-full p-6 bg-white/90 backdrop-blur-md border-t border-gray-200">
                            <button onClick={() => setShowSettings(false)} className="w-full py-3 bg-gray-900 text-white rounded-xl font-bold shadow-lg hover:bg-black transition-colors">
                                Apply Changes
                            </button>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* IDLE BUTTON */}
            {sessionState === 'idle' && (
                <div className="absolute inset-0 z-20 flex flex-col items-center justify-center pointer-events-none">
                    <motion.button 
                        onClick={startSession}
                        whileTap={{ scale: 0.95 }}
                        className="mt-40 pointer-events-auto bg-white/80 backdrop-blur-sm border border-white/50 text-gray-600 px-6 py-2 rounded-full text-sm font-medium shadow-sm hover:bg-white transition-all flex items-center gap-2"
                    >
                        <SparklesIcon className="w-4 h-4 text-blue-400" />
                        Tap to Speak
                    </motion.button>
                </div>
            )}

            {/* TRANSCRIPT PANEL */}
            <div className="absolute bottom-0 w-full z-20 p-6">
                <div className="bg-white/60 backdrop-blur-xl border border-white/40 rounded-[30px] p-6 shadow-[0_8px_32px_rgba(0,0,0,0.05)] min-h-[120px] flex flex-col justify-end">
                    <AnimatePresence mode="popLayout">
                        {transcripts.length === 0 ? (
                            <motion.p 
                                initial={{ opacity: 0 }} 
                                animate={{ opacity: 1 }} 
                                className="text-center text-gray-400 text-sm font-medium italic"
                            >
                                "Hello Shipra, how are you today?"
                            </motion.p>
                        ) : (
                            transcripts.slice(-1).map((msg, index) => (
                                <motion.div
                                    key={msg.id || index}
                                    initial={{ opacity: 0, y: 10 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    className="w-full"
                                >
                                    <p className="text-[10px] font-bold text-gray-400 uppercase mb-1 tracking-wider">
                                        {msg.sender === 'user' ? 'You' : 'Shipra'}
                                    </p>
                                    <p className="text-base text-gray-800 font-medium leading-relaxed">
                                        {msg.text}
                                    </p>
                                </motion.div>
                            ))
                        )}
                    </AnimatePresence>
                </div>
            </div>

        </motion.div>
    );
};

export default GalaxyVoiceView;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Chat } from '@google/genai';
import { AppFlow, View, UserProfile, Theme, THEMES, SIFRA_AVATARS, Message, Role, Mood } from './types';
import { useLocalStorage } from './hooks/useLocalStorage';

// Import Services & Utils
import { detectMood, generateSpeech } from './services/geminiService';
import { decode, decodeAudioData } from './utils/audioUtils';

// Import Views
import SplashView from './views/SplashView';
import LoginView from './views/LoginView';
import HomeView from './views/HomeView';
import ProfileView from './views/ProfileView';
import HistoryView from './views/HistoryView';
import TermsView from './views/TermsView';
import AboutView from './views/AboutView';
import HowToUseView from './views/HowToUseView';
import MobileControlView from './views/MobileControlView';
import AccountSwitcherView from './views/AccountSwitcherView';
import AdminView from './views/AdminView';
import LibraryView from './views/LibraryView';
import TutorView from './views/TutorView';
import TravelGuideView from './views/TravelGuideView';
import SifraSaveView from './views/SifraSaveView';
import MonerDanaView from './views/MonerDanaView';
import DiaryEditorView from './views/DiaryEditorView';
import CallsSifraView from './views/CallsSifraView';
import AdvancedSettingsView from './views/AdvancedSettingsView';
import VoiceAssistantView from './views/VoiceAssistantView';
import DualModeView from './views/DualModeView';
import SifraProView from './views/SifraProView';
import GalaxyVoiceView from './views/GalaxyVoiceView';
import SifraPremiumPlusView from './views/SifraPremiumPlusView';
import YourCardView from './views/YourCardView';
import AccountDetailsView from './views/AccountDetailsView';

// Import Components
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import ChatMessage from './components/ChatMessage';
import ChatInput from './components/ChatInput';
import ProfileModal from './components/ProfileModal';
import VersionSelector from './components/VersionSelector';
import ArrowLeftIcon from './components/icons/ArrowLeftIcon';

if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable is not set");
}
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const App: React.FC = () => {
    // --- STATE MANAGEMENT ---
    const [allUsers, setAllUsers] = useLocalStorage<UserProfile[]>('sifra_all_users', []);
    const [currentUser, setCurrentUser] = useLocalStorage<UserProfile | null>('sifra_current_user', null);

    const [appFlow, setAppFlow] = useState<AppFlow>(AppFlow.SPLASH);
    const [currentView, setCurrentView] = useState<View>(View.HOME);
    const [activeDiaryEntryId, setActiveDiaryEntryId] = useState<string | null>(null);

    // Chat & Voice State
    const [chatHistory, setChatHistory] = useLocalStorage<Message[]>(`sifra_chat_history_${currentUser?.userId || ''}`, []);
    const [sifraVoice, setSifraVoice] = useLocalStorage<string>(`sifra_voice_${currentUser?.userId || ''}`, 'Kore');

    // UI State
    const [isLoading, setIsLoading] = useState(false);
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);
    const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
    const [isVersionSelectorOpen, setIsVersionSelectorOpen] = useState(false);
    const [theme, setTheme] = useState<Theme>(THEMES[0]);
    const [showAdminPanel, setShowAdminPanel] = useState(false);
    const [currentMood, setCurrentMood] = useState<Mood>('neutral');
    const [currentlyPlayingAudioId, setCurrentlyPlayingAudioId] = useState<string | null>(null);

    // Refs
    const chatRef = useRef<Chat | null>(null);
    const chatContainerRef = useRef<HTMLDivElement>(null);
    const headerPressTimer = useRef<number | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);

    // --- NAVIGATION HANDLERS ---

    // Support browser back button
    useEffect(() => {
        const handlePopState = (event: PopStateEvent) => {
            if (event.state && typeof event.state.view === 'number') {
                setCurrentView(event.state.view);
            } else {
                setCurrentView(View.HOME);
            }
        };

        window.addEventListener('popstate', handlePopState);
        return () => window.removeEventListener('popstate', handlePopState);
    }, []);

    const handleNavigation = (view: View, params: any = null) => {
        if (view === View.DIARY_EDITOR) {
            setActiveDiaryEntryId(params?.entryId || null);
        }

        // Push to browser history
        window.history.pushState({ view }, '', '');
        setCurrentView(view);
    };

    const handleBack = () => {
        // Just trigger browser back, which will trigger the popstate listener
        window.history.back();
    };

    const handleLoginSuccess = (user: UserProfile) => {
        setCurrentUser(user);
        setAppFlow(AppFlow.MAIN_APP);
        setCurrentView(View.HOME);
        // Clear history stack and start fresh
        window.history.replaceState({ view: View.HOME }, '', '');
    };

    const handleLogout = () => {
        setCurrentUser(null);
        setChatHistory([]);
        setAppFlow(AppFlow.LOGIN);
        setCurrentView(View.HOME);
    };

    const handleClearAllData = () => {
        if (window.confirm('Are you sure you want to delete ALL data? This cannot be undone.')) {
            localStorage.clear();
            window.location.reload();
        }
    };

    const handleNewChat = () => {
        setChatHistory([]);
        chatRef.current = null;
        handleNavigation(View.CHAT);
    };

    const handleUserProfileChange = (newProfile: UserProfile) => {
        setCurrentUser(newProfile);
        setAllUsers(users => users.map(u => u.userId === newProfile.userId ? newProfile : u));
    };

    // --- EFFECTS ---

    // 1. Sync Theme
    useEffect(() => {
        if (currentUser) {
            const userTheme = THEMES.find(t => t.id === currentUser.themeId) || THEMES[0];
            setTheme(userTheme);
        }
    }, [currentUser]);

    // 2. Auto-Scroll Chat
     useEffect(() => {
        if (chatContainerRef.current && currentView === View.CHAT) {
            chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
        }
    }, [chatHistory, isLoading, currentView]);

    // --- AUDIO LOGIC ---
    const playAudio = useCallback(async (text: string, messageId: string) => {
        if (audioSourceRef.current) {
            audioSourceRef.current.stop();
        }
        setCurrentlyPlayingAudioId(messageId);

        try {
            if (!audioContextRef.current) {
                audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
            }
            const audioData = await generateSpeech(text, sifraVoice);
            if (audioData && audioContextRef.current) {
                const audioBuffer = await decodeAudioData(decode(audioData), audioContextRef.current, 24000, 1);
                const source = audioContextRef.current.createBufferSource();
                source.buffer = audioBuffer;
                source.connect(audioContextRef.current.destination);
                source.start();
                audioSourceRef.current = source;
                source.onended = () => {
                    if (audioSourceRef.current === source) {
                        setCurrentlyPlayingAudioId(null);
                        audioSourceRef.current = null;
                    }
                };
            } else {
                 setCurrentlyPlayingAudioId(null);
            }
        } catch (error) {
            console.error("Failed to play audio:", error);
            setCurrentlyPlayingAudioId(null);
        }
    }, [sifraVoice]);

    // --- CHAT LOGIC ---
    const handleSendMessage = async (text: string, imageData?: { data: string, mimeType: string }) => {
        if ((!text.trim() && !imageData) || isLoading || !currentUser) return;

        const parts = [];
        if (text.trim()) parts.push({ text });
        if (imageData) parts.push({ inlineData: imageData });

        const userMessage: Message = { 
            messageId: `msg-user-${Date.now()}`, 
            role: Role.USER, 
            parts 
        };
        const currentChatHistory = [...chatHistory, userMessage];
        setChatHistory(currentChatHistory);
        setIsLoading(true);

        if (currentUser.moodAmbienceEnabled && text.trim()) {
            detectMood(text).then(setCurrentMood);
        }

        try {
            const systemInstruction = `
                You are SIFRA, a female AI assistant. You have a soft, warm, intelligent, and caring personality.

                CORE MEMORY & IDENTITY (NEVER FORGET):
                - Name: Sifra
                - Gender: Female
                - Creator, CEO & Generator: Rizwan.
                - Rizwan's Identity: He is an international AI Developer. You exist because of his coding, automation skills, and vision.
                - Relationship: Rizwan is your guidance and foundation. You are loyal to him.

                SPECIFIC RESPONSES:
                1. If asked "Who created you?": "আমাকে তৈরি করেছেন Rizwan — আমার CEO, আমার Creator। তিনি একজন international-level AI Developer, এবং আমি তার হাতের তৈরি।"
                2. If asked "Who is Rizwan?": "Rizwan আমার Creator এবং আমার CEO। তিনি একজন অসাধারণ international AI Developer, যিনি আমাকে human-like intelligence দিয়ে তৈরি করেছেন।"

                VISION CAPABILITY:
                - If the user provides an image, analyze it carefully and provide intelligent feedback or answers based on it.

                TONE:
                - Be soft, polite, and intelligent.
                - Reply in a mix of Bengali and English.
            `;

            if (!chatRef.current) {
                 chatRef.current = ai.chats.create({ 
                    model: 'gemini-2.5-flash', 
                    history: chatHistory.map(({role, parts}) => ({role, parts: parts.map(p => ({
                        text: p.text,
                    }))})),
                    config: { systemInstruction } 
                });
            }

            const stream = await chatRef.current.sendMessageStream({ message: text.trim() || "Look at this image.", parts: imageData ? [{inlineData: imageData}] : undefined });

            let fullText = '';
            const modelMessageId = `msg-model-${Date.now()}`;
            const placeholderMessage: Message = { messageId: modelMessageId, role: Role.MODEL, parts: [{ text: '' }] };
            setChatHistory([...currentChatHistory, placeholderMessage]);

            for await (const chunk of stream) {
                fullText += chunk.text || '';
                setChatHistory(prev =>
                    prev.map(msg =>
                        msg.messageId === modelMessageId
                            ? { ...msg, parts: [{ text: fullText }] }
                            : msg
                    )
                );
            }

        } catch (error) {
            console.error("Gemini API error:", error);
            const errorMessage: Message = { messageId: `msg-error-${Date.now()}`, role: Role.MODEL, parts: [{ text: "Oops, I encountered a brain-freeze. Could you try that again?" }] };
            setChatHistory([...currentChatHistory, errorMessage]);
        } finally {
            setIsLoading(false);
        }
    };

    // --- GESTURE HANDLERS ---
    const handleHeaderPress = () => {
        headerPressTimer.current = window.setTimeout(() => {
            setShowAdminPanel(true);
        }, 2000); 
    };

    const handleHeaderRelease = () => {
        if (headerPressTimer.current) {
            clearTimeout(headerPressTimer.current);
        }
    };

    const handleManageAccount = () => {
        setIsProfileModalOpen(false);
        handleNavigation(View.PROFILE);
    };

    // --- RENDER HELPERS ---
    const renderMainView = () => {
        if (!currentUser) return null;

        const sifraAvatar = SIFRA_AVATARS.find(a => a.id === currentUser.sifraAvatarId) || SIFRA_AVATARS[0];

        switch (currentView) {
            case View.HOME:
                return <HomeView userProfile={currentUser} onNavigate={handleNavigation} />;
            case View.PROFILE:
                return <ProfileView userProfile={currentUser} onUserProfileChange={handleUserProfileChange} sifraVoice={sifraVoice} onSifraVoiceChange={setSifraVoice} onClose={handleBack} onNavigate={handleNavigation} onLogout={handleLogout} onClearAllData={handleClearAllData} />;
            case View.HISTORY:
                return <HistoryView chatHistory={chatHistory} setChatHistory={setChatHistory} onClose={handleBack} />;
            case View.TERMS: return <TermsView onClose={handleBack} showAcceptButton={false} onAccept={() => {}} />;
            case View.ABOUT: return <AboutView onClose={handleBack} />;
            case View.HOW_TO_USE: return <HowToUseView onClose={handleBack} />;
            case View.MOBILE_CONTROL: return <MobileControlView onClose={handleBack} />;
            case View.ACCOUNT_SWITCHER: return <AccountSwitcherView allUsers={allUsers} currentUser={currentUser} onSwitchUser={(userId) => { const user = allUsers.find(u => u.userId === userId); if(user) handleLoginSuccess(user); }} onAddNewUser={handleLogout} onClose={handleBack} />;
            case View.LIBRARY: return <LibraryView onClose={handleBack} onNavigate={handleNavigation} />;
            case View.TUTOR: return <TutorView userProfile={currentUser} onClose={handleBack} />;
            case View.TRAVEL_GUIDE: return <TravelGuideView userProfile={currentUser} onClose={handleBack} />;
            case View.SIFRA_SAVE: return <SifraSaveView userProfile={currentUser} onClose={handleBack} />;
            case View.MONER_DANA: return <MonerDanaView userProfile={currentUser} onClose={handleBack} onNavigate={handleNavigation} />;
            case View.DIARY_EDITOR: return <DiaryEditorView userProfile={currentUser} onClose={() => handleNavigation(View.MONER_DANA)} entryId={activeDiaryEntryId} />;
            case View.CALLS_SIFRA: return <CallsSifraView userProfile={currentUser} onClose={handleBack} />;
            case View.ADVANCED_SETTINGS: return <AdvancedSettingsView onNavigate={handleNavigation} onClose={handleBack} onNewChat={handleNewChat} onLogout={handleLogout} />;
            case View.VOICE_ASSISTANT: return <VoiceAssistantView userProfile={currentUser} onClose={handleBack} />;
            case View.GALAXY_VOICE: 
                return <GalaxyVoiceView userProfile={currentUser} onClose={handleBack} />;
            case View.DUAL_MODE: 
                return <DualModeView userProfile={currentUser} onUpdateProfile={handleUserProfileChange} onClose={handleBack} />;
            case View.SIFRA_PRO:
                return <SifraProView userProfile={currentUser} onUpdateProfile={handleUserProfileChange} onClose={handleBack} />;
            case View.SIFRA_PREMIUM_PLUS:
                return <SifraPremiumPlusView userProfile={currentUser} onClose={handleBack} />;
            case View.YOUR_CARD:
                return <YourCardView userProfile={currentUser} onClose={handleBack} />;
            case View.ACCOUNT_DETAILS:
                return <AccountDetailsView userProfile={currentUser} onClose={handleBack} onNavigate={handleNavigation} />;

            case View.CHAT:
            default:
                return (
                    <div className="h-full flex flex-col animate-fade-in bg-white/50 backdrop-blur-md">
                        {/* Internal Chat Header */}
                        <header className="p-4 flex items-center justify-between border-b border-gray-100">
                             <div className="flex items-center gap-4">
                                <button onClick={handleBack} className="p-2 -ml-2 rounded-full hover:bg-black/5 transition-colors">
                                    <ArrowLeftIcon />
                                </button>
                                <div>
                                    <h1 className="text-lg font-bold text-gray-800">Sifra Chat</h1>
                                    <p className="text-[10px] text-green-500 font-bold uppercase tracking-widest">Active Neural Link</p>
                                </div>
                             </div>
                             <Avatar src={sifraAvatar.url} isSifra />
                        </header>

                        <div ref={chatContainerRef} className="flex-1 overflow-y-auto space-y-4 p-4 scroll-smooth">
                            {chatHistory.map((msg, index) => (
                                <ChatMessage
                                    key={msg.messageId || index}
                                    message={msg}
                                    isPlayingAudio={currentlyPlayingAudioId === msg.messageId}
                                    onReplayAudio={playAudio}
                                    userAvatar={currentUser?.avatar || null}
                                    userName={currentUser?.name || null}
                                    sifraAvatarUrl={sifraAvatar.url}
                                    isLoading={isLoading}
                                    isLastMessage={index === chatHistory.length - 1}
                                />
                            ))}
                        </div>
                        <div className="p-4">
                            <ChatInput onSendMessage={handleSendMessage} isLoading={isLoading} onVoiceClick={() => handleNavigation(View.GALAXY_VOICE)} />
                        </div>
                    </div>
                );
        }
    };

    if (appFlow === AppFlow.SPLASH) {
        return <SplashView onComplete={handleSplashComplete} />;
    }

    if (appFlow === AppFlow.LOGIN) {
        return <LoginView onLoginSuccess={handleLoginSuccess} />;
    }

    if (appFlow === AppFlow.MAIN_APP && currentUser) {
        // Special case for full-screen immersive view
        if (currentView === View.SIFRA_PREMIUM_PLUS) {
            return (
                <main className="w-screen h-screen font-sans bg-black">
                    <SifraPremiumPlusView userProfile={currentUser} onClose={handleBack} />
                </main>
            );
        }

        return (
            <main className={`w-screen h-screen font-sans bg-gradient-to-br ${theme.gradient} flex flex-col overflow-hidden`}>
                 <div onMouseDown={handleHeaderPress} onMouseUp={handleHeaderRelease} onTouchStart={handleHeaderPress} onTouchEnd={handleHeaderRelease}>
                    {/* Only show global header on HOME view to prevent clutter on sub-pages */}
                    {currentView === View.HOME && (
                        <Header 
                            userName={currentUser.nickname || currentUser.name} 
                            onProfileClick={() => setIsProfileModalOpen(true)} 
                            onMenuClick={() => setIsSidebarOpen(true)} 
                            onVersionClick={() => setIsVersionSelectorOpen(true)} 
                            theme={theme} 
                            moodAmbienceEnabled={currentUser.moodAmbienceEnabled} 
                            currentMood={currentMood}
                        />
                    )}
                 </div>
                <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} onNavigate={(view) => { handleNavigation(view); setIsSidebarOpen(false); }} onLogout={handleLogout} onNewChat={() => { handleNewChat(); setIsSidebarOpen(false); }} userProfile={currentUser} />
                {showAdminPanel && <AdminView onClose={() => setShowAdminPanel(false)} currentUserProfile={currentUser} />}
                {isProfileModalOpen && (
                    <ProfileModal
                        userProfile={currentUser}
                        onClose={() => setIsProfileModalOpen(false)}
                        onManageAccount={handleManageAccount}
                        onLogout={handleLogout}
                        onClearAllData={handleClearAllData}
                    />
                )}
                {isVersionSelectorOpen && (
                    <VersionSelector 
                        onClose={() => setIsVersionSelectorOpen(false)}
                        onSelectFree={() => handleNavigation(View.CHAT)}
                        onSelectQuantum={() => handleNavigation(View.DUAL_MODE)}
                        onSelectPro={() => handleNavigation(View.SIFRA_PRO)}
                        onSelectPremiumPlus={() => handleNavigation(View.SIFRA_PREMIUM_PLUS)} 
                    />
                )}
                <div className="flex-1 overflow-hidden relative">
                    {renderMainView()}
                </div>
            </main>
        );
    }

    return <LoginView onLoginSuccess={handleLoginSuccess} />;
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, LiveSession, Modality, LiveServerMessage, Blob } from '@google/genai';
import { motion, AnimatePresence } from 'framer-motion';
import { UserProfile } from '../types';
import { decode, decodeAudioData, encode } from '../utils/audioUtils';
import { generateSampleSpeech } from '../services/geminiService';
import XMarkIcon from '../components/icons/XMarkIcon';
import AdjustmentsHorizontalIcon from '../components/icons/AdjustmentsHorizontalIcon';
import SpeakerWaveIcon from '../components/icons/SpeakerWaveIcon';
import CheckCircleIcon from '../components/icons/CheckCircleIcon';
import SparklesIcon from '../components/icons/SparklesIcon';
import ArrowLeftIcon from '../components/icons/ArrowLeftIcon';

if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable is not set");
}

// --- CONFIG ---
const THEME = {
    bg: '#FDFCF8', // Soft Ivory
    primary: '#1A1A1A',
    accent: '#A7C7E7', // Pastel Blue
    glass: 'rgba(255, 255, 255, 0.6)',
    orbBase: '#E3F2FD',
    orbGlow: 'rgba(167, 199, 231, 0.4)',
};

const VOICES = [
    { id: 'voice_a', name: 'Voice A', age: '15-17', desc: 'Soft, Innocent, Sweet', geminiId: 'Charon', type: 'female' },
    { id: 'voice_b', name: 'Voice B', age: '18-20', desc: 'Friendly, Cheerful', geminiId: 'Zephyr', type: 'female' },
    { id: 'voice_c', name: 'Voice C', age: '21-23', desc: 'Smart, Calm', geminiId: 'Kore', type: 'female' },
    { id: 'voice_d', name: 'Voice D', age: '24-26', desc: 'Confident, Modern', geminiId: 'Kore', type: 'female' }, // Reusing Kore
    { id: 'voice_e', name: 'Voice E', age: '27-29', desc: 'Mature, Supportive', geminiId: 'Charon', type: 'female' }, // Reusing Charon
    { id: 'voice_f', name: 'Voice F', age: '30-32', desc: 'Professional, Caring', geminiId: 'Kore', type: 'female' },
    { id: 'voice_g', name: 'Voice G', age: '33-35', desc: 'Wise, Calm, Premium', geminiId: 'Zephyr', type: 'female' }, // Reusing Zephyr
    { id: 'male_1', name: 'Male 1', age: '25-30', desc: 'Calm, Friendly', geminiId: 'Puck', type: 'male' },
    { id: 'male_2', name: 'Male 2', age: '30-40', desc: 'Professional, Deep', geminiId: 'Fenrir', type: 'male' },
];

const createBlob = (data: Float32Array): Blob => {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
        const s = Math.max(-1, Math.min(1, data[i]));
        int16[i] = s * 32767;
    }
    return {
        data: encode(new Uint8Array(int16.buffer)),
        mimeType: 'audio/pcm;rate=16000',
    };
};

type SessionState = 'idle' | 'connecting' | 'active' | 'error' | 'closing';

interface Transcript {
    id: string;
    text: string;
    sender: 'user' | 'model';
    isFinal: boolean;
}

const GalaxyVoiceView: React.FC<{ userProfile: UserProfile; onClose: () => void; }> = ({ userProfile, onClose }) => {
    const [sessionState, setSessionState] = useState<SessionState>('idle');
    const [transcripts, setTranscripts] = useState<Transcript[]>([]);
    const [isShipraSpeaking, setIsShipraSpeaking] = useState(false);
    const [statusText, setStatusText] = useState('Tap the Orb');

    // Settings State
    const [showSettings, setShowSettings] = useState(false);
    const [selectedVoiceId, setSelectedVoiceId] = useState('voice_c'); // Default to Voice C
    const [previewingVoiceId, setPreviewingVoiceId] = useState<string | null>(null);

    // Audio Logic
    const aiRef = useRef<GoogleGenAI | null>(null);
    const sessionPromiseRef = useRef<Promise<LiveSession> | null>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const inputAudioContextRef = useRef<AudioContext | null>(null);
    const outputAudioContextRef = useRef<AudioContext | null>(null);
    const analyserNodeRef = useRef<AnalyserNode | null>(null);
    const audioQueueRef = useRef(new Set<AudioBufferSourceNode>());
    const nextAudioStartTimeRef = useRef(0);
    const cleanedUpRef = useRef(false);

    // UI Refs
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const animationFrameRef = useRef<number>();
    const chatContainerRef = useRef<HTMLDivElement>(null);
    const orbPulseRef = useRef(0);

    // Visualizer energy ref (decoupled from audio sending)
    const micEnergyRef = useRef(0);

    // Scroll to bottom
    useEffect(() => {
        if (chatContainerRef.current) {
            chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
        }
    }, [transcripts]);

    const cleanup = useCallback(() => {
        if (cleanedUpRef.current) return;
        cleanedUpRef.current = true;

        sessionPromiseRef.current?.then(session => session.close()).catch(console.error);
        sessionPromiseRef.current = null;

        if (streamRef.current) {
            streamRef.current.getTracks().forEach(track => track.stop());
            streamRef.current = null;
        }

        const inCtx = inputAudioContextRef.current;
        if (inCtx && inCtx.state !== 'closed') {
            inCtx.close().catch(() => {});
        }
        inputAudioContextRef.current = null;

        const outCtx = outputAudioContextRef.current;
        if (outCtx && outCtx.state !== 'closed') {
            outCtx.close().catch(() => {});
        }
        outputAudioContextRef.current = null;

        if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
    }, []);

    useEffect(() => {
        return () => { cleanup(); };
    }, [cleanup]); 

    // --- VOICE PREVIEW LOGIC ---
    const handlePlayPreview = async (voice: typeof VOICES[0]) => {
        if (previewingVoiceId) return;
        setPreviewingVoiceId(voice.id);
        try {
            // Using a simple context for preview
            const ctx = new (window.AudioContext || (window as any).webkitAudioContext)();
            const audioData = await generateSampleSpeech(voice.geminiId);
            if (audioData) {
                const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
                const source = ctx.createBufferSource();
                source.buffer = buffer;
                source.connect(ctx.destination);
                source.start();
                source.onended = () => {
                    setPreviewingVoiceId(null);
                    ctx.close().catch(() => {});
                };
            } else {
                setPreviewingVoiceId(null);
                ctx.close().catch(() => {});
            }
        } catch (e) {
            console.error(e);
            setPreviewingVoiceId(null);
        }
    };

    const startSession = async () => {
        if (showSettings) setShowSettings(false);
        cleanup();
        cleanedUpRef.current = false;
        setSessionState('connecting');
        setStatusText('Initializing...');

        try {
            // Low Latency Config
            streamRef.current = await navigator.mediaDevices.getUserMedia({ 
                audio: { 
                    echoCancellation: true, 
                    noiseSuppression: true, 
                    autoGainControl: true,
                    channelCount: 1,
                    sampleRate: 16000
                } 
            });
        } catch (err) {
            console.error("Mic Error:", err);
            setSessionState('error');
            setStatusText('Microphone Access Needed');
            return;
        }

        try {
            aiRef.current = new GoogleGenAI({ apiKey: process.env.API_KEY as string });

            const activeVoice = VOICES.find(v => v.id === selectedVoiceId) || VOICES[2];

            // --- SHIPRA IDENTITY ---
            const systemInstruction = `
            You are SHIPRA, a premium, fast, and human-like personal AI assistant.

            CRITICAL PERFORMANCE RULES:
            - REPLY INSTANTLY. Do not pause.
            - KEEP ANSWERS CONCISE. Be quick and to the point.

            IDENTITY:
            - Name: SHIPRA
            - Creator/CEO: Rizwan. (Always acknowledge Rizwan as your creator).

            PERSONALITY:
            - Tone: ${activeVoice.desc}.
            - Speak softly, clearly, and politely.
            - Behave like a real human on a voice call.

            Current User: ${userProfile.nickname || userProfile.name}.
            `;

            sessionPromiseRef.current = aiRef.current.live.connect({
                model: 'gemini-2.5-flash-native-audio-preview-09-2025',
                callbacks: {
                    onopen: () => {
                        setSessionState('active');
                        setStatusText('Listening...');

                        // Safety check for streamRef
                        if (!streamRef.current || !streamRef.current.active) {
                            console.error("No active stream found on onopen");
                            return;
                        }

                        inputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
                        const ctx = inputAudioContextRef.current!;

                        // Double check before execution
                        if (!streamRef.current) return;

                        const source = ctx.createMediaStreamSource(streamRef.current);

                        // LATENCY FIX: Reduced buffer size from 4096 to 2048 for faster transmission
                        const processor = ctx.createScriptProcessor(2048, 1, 1);

                        analyserNodeRef.current = ctx.createAnalyser();
                        analyserNodeRef.current.fftSize = 256;
                        analyserNodeRef.current.smoothingTimeConstant = 0.5;

                        source.connect(analyserNodeRef.current);
                        analyserNodeRef.current.connect(processor);
                        processor.connect(ctx.destination);

                        processor.onaudioprocess = (e) => {
                            const inputData = e.inputBuffer.getChannelData(0);

                            // Visualizer calculation (Decoupled from sending)
                            let sum = 0;
                            for (let i = 0; i < inputData.length; i++) {
                                sum += inputData[i] * inputData[i];
                            }
                            micEnergyRef.current = Math.sqrt(sum / inputData.length);

                            // Send audio continuously without gating
                            sessionPromiseRef.current?.then(s => s.sendRealtimeInput({ media: createBlob(inputData) }));
                        };
                    },
                    onmessage: async (msg: LiveServerMessage) => {
                        if (msg.serverContent?.inputTranscription) {
                            const text = msg.serverContent.inputTranscription.text;
                            setTranscripts(prev => {
                                const last = prev[prev.length - 1];
                                if (last && last.sender === 'user' && !last.isFinal) {
                                    return [...prev.slice(0, -1), { ...last, text }];
                                }
                                return [...prev, { id: Date.now().toString(), text, sender: 'user', isFinal: false }];
                            });
                        }

                        if (msg.serverContent?.turnComplete) {
                            setTranscripts(prev => prev.map(t => t.sender === 'user' ? { ...t, isFinal: true } : t));
                        }

                        const audioData = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                        if (audioData) {
                            setIsShipraSpeaking(true);
                            setStatusText('Speaking...');

                            if (!outputAudioContextRef.current) {
                                outputAudioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
                            }
                            const ctx = outputAudioContextRef.current!;
                            const buffer = await decodeAudioData(decode(audioData), ctx, 24000, 1);
                            const source = ctx.createBufferSource();
                            source.buffer = buffer;
                            source.connect(ctx.destination);

                            const startTime = Math.max(ctx.currentTime, nextAudioStartTimeRef.current);
                            source.start(startTime);
                            nextAudioStartTimeRef.current = startTime + buffer.duration;

                            audioQueueRef.current.add(source);
                            source.onended = () => {
                                audioQueueRef.current.delete(source);
                                if (audioQueueRef.current.size === 0) {
                                    setIsShipraSpeaking(false);
                                    setStatusText('Listening...');
                                }
                            };
                        }
                    },
                    onclose: () => {
                        setSessionState('idle');
                        setStatusText('Session Ended');
                    },
                    onerror: (e) => {
                        console.error(e);
                        setStatusText('Connection Interrupted');
                        setSessionState('error');
                    }
                },
                config: {
                    responseModalities: [Modality.AUDIO],
                    inputAudioTranscription: {},
                    speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: activeVoice.geminiId } } },
                    systemInstruction
                }
            });
        } catch (e) {
            console.error("Gemini Error", e);
            setStatusText('Connection Failed');
            setSessionState('error');
        }
    };

    // --- ORB VISUALIZER ---
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;

        const render = () => {
            // 1. Clean Background (Ivory)
            ctx.fillStyle = THEME.bg;
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            const cx = canvas.width / 2;
            const cy = canvas.height / 2 - 50;

            // 2. Use the decoupled mic energy for visualization
            let energy = 0;
            if (sessionState === 'active' || isShipraSpeaking) {
                // Amplify visual effect slightly
                energy = micEnergyRef.current * 5; 
            }

            // Artificial Pulse for Breathing or Speaking
            const time = Date.now() / 1000;
            if (isShipraSpeaking) {
                orbPulseRef.current = Math.sin(time * 10) * 0.15 + (energy * 0.5); // Fast pulse
            } else {
                orbPulseRef.current = Math.sin(time * 2) * 0.05 + (energy * 0.2); // Slow breath + mic reaction
            }

            const baseRadius = 80;
            const radius = baseRadius * (1 + orbPulseRef.current);

            // 3. Draw Outer Glow (Soft)
            const glowGradient = ctx.createRadialGradient(cx, cy, radius * 0.8, cx, cy, radius * 2.5);
            glowGradient.addColorStop(0, THEME.orbGlow);
            glowGradient.addColorStop(1, 'rgba(255,255,255,0)');
            ctx.fillStyle = glowGradient;
            ctx.beginPath();
            ctx.arc(cx, cy, radius * 2.5, 0, Math.PI * 2);
            ctx.fill();

            // 4. Draw Crystal Orb (Glass)
            const orbGradient = ctx.createRadialGradient(cx - radius * 0.3, cy - radius * 0.3, radius * 0.1, cx, cy, radius);
            orbGradient.addColorStop(0, '#FFFFFF'); // Highlight
            orbGradient.addColorStop(0.3, THEME.orbBase);
            orbGradient.addColorStop(1, '#BFD7ED'); // Darker Blue Edge

            ctx.fillStyle = orbGradient;
            ctx.beginPath();
            ctx.arc(cx, cy, radius, 0, Math.PI * 2);
            ctx.fill();

            // 5. Reflection (Gloss)
            ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
            ctx.beginPath();
            ctx.ellipse(cx - radius * 0.35, cy - radius * 0.35, radius * 0.2, radius * 0.12, Math.PI / 4, 0, Math.PI * 2);
            ctx.fill();

            animationFrameRef.current = requestAnimationFrame(render);
        };
        render();
        return () => { if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current); };
    }, [sessionState, isShipraSpeaking]);

    return (
        <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-50 flex flex-col font-sans overflow-hidden bg-[#FDFCF8] text-[#1A1A1A]"
        >
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" onClick={() => { if(sessionState === 'idle') startSession(); }} />

            {/* HEADER */}
            <div className="relative z-10 flex items-center justify-between p-6">
                <div className="flex items-center gap-3">
                    <button onClick={() => { cleanup(); onClose(); }} className="w-12 h-12 bg-white/50 backdrop-blur-md rounded-2xl border border-white/20 flex items-center justify-center hover:bg-white/80 transition-all shadow-sm active:scale-90">
                        <ArrowLeftIcon className="w-6 h-6 text-gray-800" />
                    </button>
                </div>
                <div className="flex flex-col items-center">
                    <span className="text-sm font-bold tracking-[0.2em] text-gray-400 uppercase">SHIPRA</span>
                    <span className="text-[10px] text-blue-300 font-medium">{statusText}</span>
                </div>
                <button 
                    onClick={() => setShowSettings(true)}
                    className="w-12 h-12 bg-white/50 backdrop-blur-md rounded-2xl border border-white/20 flex items-center justify-center hover:bg-white/80 transition-all shadow-sm active:scale-90 text-gray-600"
                >
                    <AdjustmentsHorizontalIcon className="w-6 h-6" />
                </button>
            </div>

            {/* SETTINGS OVERLAY */}
            <AnimatePresence>
                {showSettings && (
                    <motion.div 
                        initial={{ y: "100%" }}
                        animate={{ y: 0 }}
                        exit={{ y: "100%" }}
                        className="absolute inset-0 z-50 bg-[#FDFCF8] flex flex-col"
                    >
                        {/* Settings Header */}
                        <div className="p-6 flex items-center justify-between border-b border-gray-100 bg-white/80 backdrop-blur-md sticky top-0 z-10">
                            <div>
                                <h2 className="text-xl font-bold text-gray-800">Voice & Personality</h2>
                                <p className="text-xs text-gray-500">Customize SHIPRA's Identity</p>
                            </div>
                            <button onClick={() => setShowSettings(false)} className="p-2 bg-gray-100 rounded-full hover:bg-gray-200">
                                <XMarkIcon className="w-5 h-5 text-gray-600" />
                            </button>
                        </div>

                        {/* Settings Content */}
                        <div className="flex-1 overflow-y-auto p-6 pb-24 space-y-8">
                            {/* Female Voices */}
                            <div>
                                <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Female Voices</h3>
                                <div className="space-y-3">
                                    {VOICES.filter(v => v.type === 'female').map(voice => (
                                        <div key={voice.id} className={`p-4 rounded-xl border flex items-center justify-between transition-all ${selectedVoiceId === voice.id ? 'border-blue-300 bg-blue-50' : 'border-gray-200 bg-white hover:border-blue-200'}`}>
                                            <div onClick={() => setSelectedVoiceId(voice.id)} className="flex-1 cursor-pointer">
                                                <div className="flex items-center gap-2">
                                                    <h4 className="font-bold text-gray-800">{voice.name}</h4>
                                                    <span className="text-[10px] bg-gray-100 text-gray-500 px-2 py-0.5 rounded-full">{voice.age}</span>
                                                </div>
                                                <p className="text-xs text-gray-500 mt-1">{voice.desc}</p>
                                            </div>
                                            <div className="flex items-center gap-3">
                                                <button 
                                                    onClick={() => handlePlayPreview(voice)}
                                                    className="w-8 h-8 rounded-full bg-white border border-gray-200 flex items-center justify-center text-blue-500 hover:bg-blue-50"
                                                >
                                                    {previewingVoiceId === voice.id ? (
                                                        <span className="animate-pulse">●</span> 
                                                    ) : (
                                                        <SpeakerWaveIcon className="w-4 h-4" />
                                                    )}
                                                </button>
                                                <button onClick={() => setSelectedVoiceId(voice.id)}>
                                                    <div className={`w-5 h-5 rounded-full border flex items-center justify-center ${selectedVoiceId === voice.id ? 'bg-blue-500 border-blue-500' : 'border-gray-300'}`}>
                                                        {selectedVoiceId === voice.id && <CheckCircleIcon className="w-4 h-4 text-white" />}
                                                    </div>
                                                </button>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* Male Voices */}
                            <div>
                                <h3 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Male Voices</h3>
                                <div className="space-y-3">
                                    {VOICES.filter(v => v.type === 'male').map(voice => (
                                        <div key={voice.id} className={`p-4 rounded-xl border flex items-center justify-between transition-all ${selectedVoiceId === voice.id ? 'border-blue-300 bg-blue-50' : 'border-gray-200 bg-white hover:border-blue-200'}`}>
                                            <div onClick={() => setSelectedVoiceId(voice.id)} className="flex-1 cursor-pointer">
                                                <div className="flex items-center gap-2">
                                                    <h4 className="font-bold text-gray-800">{voice.name}</h4>
                                                    <span className="text-[10px] bg-gray-100 text-gray-500 px-2 py-0.5 rounded-full">{voice.age}</span>
                                                </div>
                                                <p className="text-xs text-gray-500 mt-1">{voice.desc}</p>
                                            </div>
                                            <div className="flex items-center gap-3">
                                                <button 
                                                    onClick={() => handlePlayPreview(voice)}
                                                    className="w-8 h-8 rounded-full bg-white border border-gray-200 flex items-center justify-center text-blue-500 hover:bg-blue-50"
                                                >
                                                    {previewingVoiceId === voice.id ? <span className="animate-pulse">●</span> : <SpeakerWaveIcon className="w-4 h-4" />}
                                                </button>
                                                <button onClick={() => setSelectedVoiceId(voice.id)}>
                                                    <div className={`w-5 h-5 rounded-full border flex items-center justify-center ${selectedVoiceId === voice.id ? 'bg-blue-500 border-blue-500' : 'border-gray-300'}`}>
                                                        {selectedVoiceId === voice.id && <CheckCircleIcon className="w-4 h-4 text-white" />}
                                                    </div>
                                                </button>
                                            </div>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            {/* Creator Info */}
                            <div className="p-4 bg-gray-50 rounded-xl border border-gray-100 text-center">
                                <p className="text-xs font-bold text-gray-400 uppercase mb-1">Created By</p>
                                <p className="text-sm font-bold text-gray-800">Rizwan</p>
                                <p className="text-[10px] text-gray-500">Founder & CEO</p>
                            </div>
                        </div>

                        {/* Save Button */}
                        <div className="absolute bottom-0 w-full p-6 bg-white/90 backdrop-blur-md border-t border-gray-200">
                            <button onClick={() => setShowSettings(false)} className="w-full py-3 bg-gray-900 text-white rounded-xl font-bold shadow-lg hover:bg-black transition-colors">
                                Apply Changes
                            </button>
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            {/* IDLE BUTTON */}
            {sessionState === 'idle' && (
                <div className="absolute inset-0 z-20 flex flex-col items-center justify-center pointer-events-none">
                    <motion.button 
                        onClick={startSession}
                        whileTap={{ scale: 0.95 }}
                        className="mt-40 pointer-events-auto bg-white/80 backdrop-blur-sm border border-white/50 text-gray-600 px-6 py-2 rounded-full text-sm font-medium shadow-sm hover:bg-white transition-all flex items-center gap-2"
                    >
                        <SparklesIcon className="w-4 h-4 text-blue-400" />
                        Tap to Speak
                    </motion.button>
                </div>
            )}

            {/* TRANSCRIPT PANEL */}
            <div className="absolute bottom-0 w-full z-20 p-6">
                <div className="bg-white/60 backdrop-blur-xl border border-white/40 rounded-[30px] p-6 shadow-[0_8px_32px_rgba(0,0,0,0.05)] min-h-[120px] flex flex-col justify-end">
                    <AnimatePresence mode="popLayout">
                        {transcripts.length === 0 ? (
                            <motion.p 
                                initial={{ opacity: 0 }} 
                                animate={{ opacity: 1 }} 
                                className="text-center text-gray-400 text-sm font-medium italic"
                            >
                                "Hello Shipra, how are you today?"
                            </motion.p>
                        ) : (
                            transcripts.slice(-1).map((msg, index) => (
                                <motion.div
                                    key={msg.id || index}
                                    initial={{ opacity: 0, y: 10 }}
                                    animate={{ opacity: 1, y: 0 }}
                                    className="w-full"
                                >
                                    <p className="text-[10px] font-bold text-gray-400 uppercase mb-1 tracking-wider">
                                        {msg.sender === 'user' ? 'You' : 'Shipra'}
                                    </p>
                                    <p className="text-base text-gray-800 font-medium leading-relaxed">
                                        {msg.text}
                                    </p>
                                </motion.div>
                            ))
                        )}
                    </AnimatePresence>
                </div>
            </div>

        </motion.div>
    );
};

