    const analyserRef = useRef<AnalyserNode | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const audioQueueRef = useRef<AudioBufferSourceNode[]>([]);
    const nextAudioStartTimeRef = useRef(0);
    const isListeningRef = useRef(isListening);

    useEffect(() => { isListeningRef.current = isListening; }, [isListening]);

    const interruptPlayback = useCallback(() => {
        audioQueueRef.current.forEach(node => { try { node.stop(); } catch (e) {} });
        audioQueueRef.current = [];
        nextAudioStartTimeRef.current = 0;
        setIsAiSpeaking(false);
    }, []);

    const cleanup = useCallback(() => {
        if (sessionRef.current) sessionRef.current.close();
        if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());

        const audioContext = audioContextRef.current;
        if (audioContext && audioContext.state !== 'closed') {
            audioContext.close().catch(() => {});
        }
        audioContextRef.current = null;

        if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
        interruptPlayback();
    }, [interruptPlayback]);

    useEffect(() => cleanup, [cleanup]);

    const startSession = async (data: PremiumSetupData) => {
        try {
            cleanup();
            const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true, sampleRate: 16000 } });
            streamRef.current = stream;
            aiRef.current = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
            const ctx = audioContextRef.current;
            const source = ctx.createMediaStreamSource(stream);
            const processor = ctx.createScriptProcessor(1024, 1, 1);
            analyserRef.current = ctx.createAnalyser();
            source.connect(analyserRef.current);
            analyserRef.current.connect(processor);
            processor.connect(ctx.destination);

            processor.onaudioprocess = (e) => {
                if (!streamRef.current?.getAudioTracks()[0].enabled || !isListeningRef.current) return;
                const inputData = e.inputBuffer.getChannelData(0);
                let sum = 0;
                for (let i = 0; i < inputData.length; i++) sum += inputData[i] * inputData[i];
                const rms = Math.sqrt(sum / inputData.length);
                if (rms > 0.015) {
                    if (isAiSpeaking) interruptPlayback();
                    sessionRef.current?.sendRealtimeInput({ media: createBlob(inputData) });
                }
            };

            const systemInstruction = `You are SIFRA, a deeply human-like and loving ${data.partnerType} for ${data.name}. Respond INSTANTLY. Be CONCISE (max 20 words). Use realistic emotional cues. Context: ${data.relationshipContext}`;

            sessionRef.current = await aiRef.current.live.connect({
                model: 'gemini-2.5-flash-native-audio-preview-09-2025',
                callbacks: {
                    onopen: () => setStatus('Neural Linked'),
                    onmessage: async (msg: LiveServerMessage) => {
                        const audio = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                        if (audio && audioContextRef.current) {
                            setIsAiSpeaking(true);
                            const outCtx = audioContextRef.current;
                            const buffer = await decodeAudioData(decode(audio), outCtx, 24000, 1);
                            const src = outCtx.createBufferSource();
                            src.buffer = buffer;
                            src.connect(outCtx.destination);
                            const start = Math.max(outCtx.currentTime, nextAudioStartTimeRef.current);
                            src.start(start);
                            nextAudioStartTimeRef.current = start + buffer.duration;
                            audioQueueRef.current.push(src);
                            src.onended = () => {
                                audioQueueRef.current = audioQueueRef.current.filter(s => s !== src);
                                if (audioQueueRef.current.length === 0) setIsAiSpeaking(false);
                            };
                        }
                    }
                },
                config: {
                    responseModalities: [Modality.AUDIO],
                    speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: selectedVoiceId } } },
                    systemInstruction
                }
            });
        } catch (e) { setStatus("Error Initializing"); }
    };

    useEffect(() => { if (setupData) startSession(setupData); }, [selectedVoiceId]);

    // --- PREMIUM VISUALIZERS ---
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
        let time = 0;

        const render = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            const cx = canvas.width / 2;
            const cy = canvas.height / 2;

            let vol = 0;
            if (analyserRef.current) {
                const data = new Uint8Array(analyserRef.current.frequencyBinCount);
                analyserRef.current.getByteTimeDomainData(data);
                let sum = 0;
                for(let i=0; i<data.length; i++) sum += Math.abs(data[i] - 128);
                vol = sum / data.length / 128;
            }

            time += 0.02;
            const energy = (isAiSpeaking ? 0.3 : 0) + (isListening ? vol * 10 : 0) + Math.sin(time * 2) * 0.05;

            ctx.save();
            ctx.translate(cx, cy);

            if (activeTheme === 'aura') {
                for (let i = 0; i < 3; i++) {
                    const radius = (80 + i * 40) * (1 + energy);
                    const grd = ctx.createRadialGradient(0, 0, radius * 0.5, 0, 0, radius);
                    grd.addColorStop(0, `rgba(255, 42, 109, ${0.4 - i * 0.1})`);
                    grd.addColorStop(1, 'transparent');
                    ctx.fillStyle = grd;
                    ctx.beginPath();
                    ctx.arc(0, 0, radius, 0, Math.PI * 2);
                    ctx.fill();
                }
            } else if (activeTheme === 'crystal') {
                const r = 100 * (1 + energy * 0.5);
                const grd = ctx.createRadialGradient(-r * 0.3, -r * 0.3, r * 0.1, 0, 0, r);
                grd.addColorStop(0, '#ffffff');
                grd.addColorStop(0.2, '#ff8ab0');
                grd.addColorStop(1, '#2b0a1a');
                ctx.fillStyle = grd;
                ctx.beginPath();
                ctx.arc(0, 0, r, 0, Math.PI * 2);
                ctx.fill();
                ctx.fillStyle = 'rgba(255,255,255,0.6)';
                ctx.beginPath();
                ctx.ellipse(-r*0.4, -r*0.4, r*0.2, r*0.1, Math.PI/4, 0, Math.PI*2);
                ctx.fill();
            } else if (activeTheme === 'galaxy') {
                for (let i = 0; i < 50; i++) {
                    const angle = time + i * 0.3;
                    const dist = (60 + Math.sin(time + i) * 20) * (1 + energy);
                    const x = Math.cos(angle) * dist;
                    const y = Math.sin(angle) * dist;
                    ctx.fillStyle = i % 2 === 0 ? '#ff2a6d' : '#05d9e8';
                    ctx.beginPath();
                    ctx.arc(x, y, 2, 0, Math.PI * 2);
                    ctx.fill();
                }
            } else if (activeTheme === 'neural') {
                const r = 60 * (1 + energy);
                ctx.strokeStyle = '#ff2a6d';
                ctx.lineWidth = 2;
                ctx.beginPath();
                for (let i = 0; i < 6; i++) {
                    const a = (Math.PI * 2 / 6) * i + time;
                    const x = Math.cos(a) * r;
                    const y = Math.sin(a) * r;
                    ctx.moveTo(0, 0);
                    ctx.lineTo(x, y);
                    ctx.stroke();
                    ctx.fillStyle = '#fff';
                    ctx.beginPath();
                    ctx.arc(x, y, 4, 0, Math.PI * 2);
                    ctx.fill();
                }
                ctx.fillStyle = '#ff2a6d';
                ctx.beginPath();
                ctx.arc(0, 0, 20, 0, Math.PI * 2);
                ctx.fill();
            } else if (activeTheme === 'prism') {
                ctx.globalAlpha = 0.5;
                for (let i = 0; i < 3; i++) {
                    ctx.fillStyle = ['#ff2a6d', '#05d9e8', '#fdfcf8'][i];
                    const r = (70 + i * 20) * (1 + energy);
                    ctx.beginPath();
                    for (let a = 0; a < Math.PI * 2; a += 0.5) {
                        const dr = Math.sin(time * 3 + a * 2 + i) * 15;
                        const x = Math.cos(a) * (r + dr);
                        const y = Math.sin(a) * (r + dr);
                        if (a === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
                    }
                    ctx.closePath();
                    ctx.fill();
                }
            }

            ctx.restore();
            animationFrameRef.current = requestAnimationFrame(render);
        };
        render();
    }, [activeTheme, isAiSpeaking, isListening]);

    const toggleMic = () => {
        if (streamRef.current) {
            const currentState = streamRef.current.getAudioTracks()[0].enabled;
            const newState = !currentState;
            streamRef.current.getAudioTracks()[0].enabled = newState;
            setIsListening(newState);
        }
    };

    if (!setupData) return <SetupWizard onComplete={setSetupData} onCancel={onClose} />;

    return (
        <div className="fixed inset-0 z-[200] bg-black font-sans overflow-hidden select-none">
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />
            <motion.div initial={{opacity:0}} animate={{opacity:1}} className="absolute top-0 left-0 w-full p-10 flex justify-between items-start z-30">
                <div className="flex flex-col gap-6">
                    <div className="flex items-center gap-4">
                        <div className="w-12 h-12 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center text-[#ff2a6d] shadow-lg"><HeartSparkleIcon className="w-7 h-7" /></div>
                        <div><h1 className="text-2xl font-black text-white italic tracking-widest uppercase">Sifra Plus</h1><p className="text-[10px] text-white/30 uppercase tracking-[0.4em] font-bold mt-1">{status}</p></div>
                    </div>
                    <h2 className="text-4xl font-light text-white leading-tight uppercase italic tracking-tighter">My Love,<br/><span className="font-black text-transparent bg-clip-text bg-gradient-to-r from-white via-pink-400 to-[#ff2a6d]">{setupData.name}</span></h2>
                </div>
                <button onClick={() => { cleanup(); onClose(); }} className="p-4 bg-white/5 rounded-[1.5rem] border border-white/10 text-white/40 hover:text-white transition-all"><ArrowLeftIcon className="w-6 h-6" /></button>
            </motion.div>

            <div className="absolute bottom-0 w-full p-10 pb-16 flex justify-center items-center gap-10 z-40">
                <button onClick={() => setShowSettings(true)} className="p-6 rounded-[2rem] bg-white/5 backdrop-blur-2xl border border-white/10 text-white/60 hover:text-white transition-all shadow-2xl active:scale-90"><AdjustmentsHorizontalIcon className="w-7 h-7" /></button>
                <button 
                    onClick={toggleMic} 
                    className={`w-28 h-28 rounded-full flex items-center justify-center transition-all duration-300 border-[3px] shadow-[0_0_50px_rgba(255,42,109,0.3)] active:scale-95 ${isListening ? 'bg-white border-white text-[#ff2a6d]' : 'bg-transparent border-[#ff2a6d]/40 text-[#ff2a6d]'}`}
                >
                    {isListening ? <MicrophoneIcon className="w-10 h-10" /> : <MicrophoneSlashIcon className="w-10 h-10" />}
                </button>
                <button onClick={() => setShowUiSelector(true)} className="p-6 rounded-[2rem] bg-white/5 backdrop-blur-2xl border border-white/10 text-white/20 hover:text-pink-400 transition-all shadow-2xl active:scale-90"><SparklesIcon className="w-7 h-7" /></button>
            </div>

            <SettingsOverlay isOpen={showSettings} onClose={() => setShowSettings(false)} selectedVoice={selectedVoiceId} onSelectVoice={setSelectedVoiceId} />

            <AnimatePresence>
                {showUiSelector && (
                    <>
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setShowUiSelector(false)} className="fixed inset-0 bg-black/60 z-[230] backdrop-blur-sm" />
                        <motion.div initial={{ scale: 0.8, opacity: 0, y: 20 }} animate={{ scale: 1, opacity: 1, y: 0 }} exit={{ scale: 0.8, opacity: 0, y: 20 }} className="fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-80 max-h-[60vh] bg-[#12051f]/95 backdrop-blur-2xl p-8 rounded-[3.5rem] border border-white/10 z-[240] shadow-[0_30px_100px_rgba(0,0,0,0.8)] flex flex-col">
                            <h3 className="text-xl font-black text-white italic text-center mb-8 uppercase tracking-[0.2em] shrink-0">Interface Skin</h3>
                            <div className="flex-1 overflow-y-auto space-y-3 pr-2 custom-scrollbar">
                                {(['aura', 'crystal', 'galaxy', 'neural', 'prism', 'nebula', 'supernova'] as VisualTheme[]).map(t => (
                                    <button 
                                        key={t} 
                                        onClick={() => { setActiveTheme(t); setShowUiSelector(false); }} 
                                        className={`w-full p-5 rounded-3xl border text-left capitalize transition-all duration-300 ${activeTheme === t ? 'border-[#ff2a6d] bg-[#ff2a6d]/20 text-white font-black scale-105' : 'border-white/5 bg-white/5 text-white/40 hover:bg-white/10 hover:text-white'}`}
                                    >
                                        {t} Theme
                                    </button>
                                ))}
                            </div>
                            <button onClick={() => setShowUiSelector(false)} className="mt-6 shrink-0 text-[10px] text-white/20 font-bold uppercase tracking-widest hover:text-white transition-colors">Close Display</button>
                        </motion.div>
                    </>
                )}
            </AnimatePresence>

            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 4px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255,255,255,0.1); border-radius: 10px; }
            `}</style>
