    return (
        <div className="fixed inset-0 z-[200] bg-black font-sans overflow-hidden select-none">
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />

            {/* TOP BAR */}
            <motion.div initial={{opacity:0}} animate={{opacity:1}} className="absolute top-0 left-0 w-full p-10 flex justify-between items-start z-[100]">
                <div className="flex flex-col gap-6">
