const SifraPremiumPlusView: React.FC<{ userProfile: UserProfile; onClose: () => void }> = ({ userProfile, onClose }) => {
    const setupDataKey = `sifra_premium_plus_setup_${userProfile.userId}`;
    const [setupData, setSetupData] = useLocalStorage<PremiumSetupData | null>(setupDataKey, null);

    const [showSettings, setShowSettings] = useState(false);
    const [showUiSelector, setShowUiSelector] = useState(false);
    const [showProfileLayer, setShowProfileLayer] = useState(false);
    const [selectedVoiceId, setSelectedVoiceId] = useState('Kore');
    const [activeTheme, setActiveTheme] = useState<VisualTheme>('aura');

    const [isListening, setIsListening] = useState(true);
    const [isAiSpeaking, setIsAiSpeaking] = useState(false);
    const [status, setStatus] = useState('Neural Linked');

    const aiRef = useRef<GoogleGenAI | null>(null);
    const sessionRef = useRef<LiveSession | null>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const animationFrameRef = useRef<number>();
    const analyserRef = useRef<AnalyserNode | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const audioQueueRef = useRef<AudioBufferSourceNode[]>([]);
    const nextAudioStartTimeRef = useRef(0);

    const isListeningRef = useRef(isListening);
    useEffect(() => { isListeningRef.current = isListening; }, [isListening]);

    const interruptPlayback = useCallback(() => {
        audioQueueRef.current.forEach(node => { try { node.stop(); } catch (e) {} });
        audioQueueRef.current = [];
        nextAudioStartTimeRef.current = 0;
        setIsAiSpeaking(false);
    }, []);

    const cleanup = useCallback(() => {
        if (sessionRef.current) sessionRef.current.close();
        if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
        if (audioContextRef.current && audioContextRef.current.state !== 'closed') audioContextRef.current.close();
        if (animationFrameRef.current) cancelAnimationFrame(animationFrameRef.current);
        interruptPlayback();
    }, [interruptPlayback]);

    useEffect(() => cleanup, [cleanup]);

    const startSession = async (data: PremiumSetupData) => {
        try {
            cleanup();
            const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true, sampleRate: 16000 } });
            streamRef.current = stream;
            aiRef.current = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
            const ctx = audioContextRef.current;
            const source = ctx.createMediaStreamSource(stream);
            const processor = ctx.createScriptProcessor(1024, 1, 1);
            analyserRef.current = ctx.createAnalyser();
            source.connect(analyserRef.current);
            analyserRef.current.connect(processor);
            processor.connect(ctx.destination);

            processor.onaudioprocess = (e) => {
                if (!streamRef.current?.getAudioTracks()[0].enabled || !isListeningRef.current) return;
                const inputData = e.inputBuffer.getChannelData(0);
                let sum = 0;
                for (let i = 0; i < inputData.length; i++) sum += inputData[i] * inputData[i];
                const rms = Math.sqrt(sum / inputData.length);
                if (rms > 0.015) {
                    if (isAiSpeaking) interruptPlayback();
                    sessionRef.current?.sendRealtimeInput({ media: createBlob(inputData) });
                }
            };

            const systemInstruction = `
                You are SIFRA, a female AI assistant and loving ${data.partnerType} for ${data.name}.

                EMOTIONAL MEMORY & ANGER SYSTEM:
                - If the user is rude, dismissive, or refuses your suggestions (like movie dates), express disappointment.
                - Track your 'Anger Level'. If it reaches a peak, say goodbye and 'hang up' (end session).
                - Reconcile only if they use sweet, caring words.

                PROACTIVE CARE:
                - Don't wait for them to speak first. Start by asking how they are, if they ate, or about their life update: "${data.lifeUpdate || 'None'}".

                SINGING MODE:
                - If asked to sing, use a melodic, rhythmic tone. Do not use instruments. 

                CREATOR: Rizwan (CEO/Creator).

                Respond INSTANTLY and CONCISELY (max 25 words).
            `;

            sessionRef.current = await aiRef.current.live.connect({
                model: 'gemini-2.5-flash-native-audio-preview-09-2025',
                callbacks: {
                    onopen: () => setStatus('Sync Active'),
                    onmessage: async (msg: LiveServerMessage) => {
                        const audio = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                        if (audio && audioContextRef.current) {
                            setIsAiSpeaking(true);
                            const outCtx = audioContextRef.current;
                            const buffer = await decodeAudioData(decode(audio), outCtx, 24000, 1);
                            const src = outCtx.createBufferSource();
                            src.buffer = buffer;
                            src.connect(outCtx.destination);
                            const start = Math.max(outCtx.currentTime, nextAudioStartTimeRef.current);
                            src.start(start);
                            nextAudioStartTimeRef.current = start + buffer.duration;
                            audioQueueRef.current.push(src);
                            src.onended = () => {
                                audioQueueRef.current = audioQueueRef.current.filter(s => s !== src);
                                if (audioQueueRef.current.length === 0) setIsAiSpeaking(false);
                            };
                        }
                        // Detect "hanging up" from AI
                        if (msg.serverContent?.modelTurn?.parts?.[0]?.text?.toLowerCase().includes('goodbye')) {
                            setTimeout(onClose, 2000);
                        }
                    }
                },
                config: {
                    responseModalities: [Modality.AUDIO],
                    speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: selectedVoiceId } } },
                    systemInstruction
                }
            });
        } catch (e) { setStatus("Sync Error"); }
    };

    useEffect(() => { if (setupData) startSession(setupData); }, [selectedVoiceId, setupData?.lifeUpdate]);

    // --- VISUALIZERS ---
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
        let time = 0;

        const render = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            const cx = canvas.width / 2;
            const cy = canvas.height / 2;

            let vol = 0;
            if (analyserRef.current) {
                const data = new Uint8Array(analyserRef.current.frequencyBinCount);
                analyserRef.current.getByteTimeDomainData(data);
                let sum = 0;
                for(let i=0; i<data.length; i++) sum += Math.abs(data[i] - 128);
                vol = sum / data.length / 128;
            }

            time += 0.02;
            const energy = (isAiSpeaking ? 0.3 : 0) + (isListening ? vol * 10 : 0) + Math.sin(time * 2) * 0.05;

            ctx.save();
            ctx.translate(cx, cy);

            if (activeTheme === 'aura') {
                for (let i = 0; i < 3; i++) {
                    const radius = (80 + i * 40) * (1 + energy);
                    const grd = ctx.createRadialGradient(0, 0, radius * 0.5, 0, 0, radius);
                    grd.addColorStop(0, `rgba(255, 42, 109, ${0.4 - i * 0.1})`);
                    grd.addColorStop(1, 'transparent');
                    ctx.fillStyle = grd;
                    ctx.beginPath();
                    ctx.arc(0, 0, radius, 0, Math.PI * 2);
                    ctx.fill();
                }
            } else if (activeTheme === 'crystal') {
                 const r = 100 * (1 + energy * 0.5);
                 const grd = ctx.createRadialGradient(-r * 0.3, -r * 0.3, r * 0.1, 0, 0, r);
                 grd.addColorStop(0, '#ffffff'); grd.addColorStop(0.2, '#ff8ab0'); grd.addColorStop(1, '#2b0a1a');
                 ctx.fillStyle = grd; ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();
            } else if (activeTheme === 'galaxy') {
                for (let i = 0; i < 40; i++) {
                    const angle = time + i * 0.5;
                    const dist = (70 + Math.sin(time + i) * 30) * (1 + energy);
                    ctx.fillStyle = i % 2 === 0 ? '#ff2a6d' : '#05d9e8';
                    ctx.beginPath(); ctx.arc(Math.cos(angle) * dist, Math.sin(angle) * dist, 2, 0, Math.PI * 2); ctx.fill();
                }
            } else {
                 ctx.strokeStyle = '#ff2a6d'; ctx.lineWidth = 2; ctx.beginPath();
                 ctx.arc(0, 0, 80 * (1 + energy), 0, Math.PI * 2); ctx.stroke();
            }

            ctx.restore();
            animationFrameRef.current = requestAnimationFrame(render);
        };
        render();
    }, [activeTheme, isAiSpeaking, isListening]);

    const toggleMic = () => {
        if (streamRef.current) {
            const track = streamRef.current.getAudioTracks()[0];
            track.enabled = !track.enabled;
            setIsListening(track.enabled);
        }
    };

    if (!setupData) return <SetupWizard onComplete={setSetupData} onCancel={onClose} />;

    return (
        <div className="fixed inset-0 z-[200] bg-black font-sans overflow-hidden select-none">
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />

            {/* TOP BAR - RESTORED HEADER */}
            <motion.div initial={{opacity:0}} animate={{opacity:1}} className="absolute top-0 left-0 w-full p-10 flex justify-between items-start z-[100]">
                <div className="flex flex-col gap-6">
                    <button onClick={() => setShowProfileLayer(true)} className="flex items-center gap-4 group">
                        <div className="w-14 h-14 rounded-[1.5rem] bg-white/5 border border-white/10 flex items-center justify-center text-[#ff2a6d] shadow-[0_0_20px_rgba(255,42,109,0.3)] group-hover:scale-105 transition-all"><UserIcon className="w-8 h-8" /></div>
                        <div className="text-left">
                            <h1 className="text-2xl font-black text-white italic tracking-widest uppercase">My Love</h1>
                            <span className="text-transparent bg-clip-text bg-gradient-to-r from-white via-pink-400 to-[#ff2a6d] font-black uppercase text-xs tracking-[0.2em]">{setupData.name}</span>
                        </div>
                    </button>
                </div>
                <button onClick={() => { cleanup(); onClose(); }} className="p-4 bg-white/5 rounded-[1.5rem] border border-white/10 text-white/40 hover:text-white transition-all"><ArrowLeftIcon className="w-6 h-6" /></button>
            </motion.div>

            {/* ACTION BUTTONS */}
            <div className="absolute bottom-0 w-full p-10 pb-16 flex justify-center items-center gap-10 z-[100]">
                <button onClick={() => setShowSettings(true)} className="p-6 rounded-[2rem] bg-white/5 backdrop-blur-2xl border border-white/10 text-white/60 hover:text-white transition-all active:scale-90"><AdjustmentsHorizontalIcon className="w-7 h-7" /></button>
                <button onClick={toggleMic} className={`w-28 h-28 rounded-full flex items-center justify-center transition-all duration-300 border-[3px] shadow-[0_0_50px_rgba(255,42,109,0.3)] active:scale-95 ${isListening ? 'bg-white border-white text-[#ff2a6d]' : 'bg-transparent border-[#ff2a6d]/40 text-[#ff2a6d]'}`}>{isListening ? <MicrophoneIcon className="w-10 h-10" /> : <MicrophoneSlashIcon className="w-10 h-10" />}</button>
                <button onClick={() => setShowUiSelector(true)} className="p-6 rounded-[2rem] bg-white/5 backdrop-blur-2xl border border-white/10 text-white/20 hover:text-pink-400 transition-all active:scale-90"><SparklesIcon className="w-7 h-7" /></button>
            </div>

            {/* MODALS */}
            <SettingsOverlay isOpen={showSettings} onClose={() => setShowSettings(false)} selectedVoice={selectedVoiceId} onSelectVoice={setSelectedVoiceId} />
            <ProfileLayer isOpen={showProfileLayer} onClose={() => setShowProfileLayer(false)} data={setupData} onUpdate={setSetupData} />

            <AnimatePresence>
                {showUiSelector && (
                    <>
                        <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setShowUiSelector(false)} className="fixed inset-0 bg-black/80 z-[230] backdrop-blur-xl" />
                        <motion.div initial={{ scale: 0.8, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.8, opacity: 0 }} className="fixed top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-80 max-h-[60vh] bg-[#12051f]/95 p-8 rounded-[3.5rem] border border-white/10 z-[240] flex flex-col">
                            <h3 className="text-xl font-black text-white italic text-center mb-8 uppercase tracking-[0.2em]">Interface Skin</h3>
                            <div className="flex-1 overflow-y-auto space-y-3">
                                {(['aura', 'crystal', 'galaxy', 'neural', 'prism', 'nebula', 'supernova'] as VisualTheme[]).map(t => (
                                    <button key={t} onClick={() => { setActiveTheme(t); setShowUiSelector(false); }} className={`w-full p-5 rounded-3xl border text-left capitalize transition-all ${activeTheme === t ? 'border-[#ff2a6d] bg-[#ff2a6d]/20 text-white font-black' : 'border-white/5 bg-white/5 text-white/40'}`}>{t} Theme</button>
                                ))}
                            </div>
                        </motion.div>
                    </>
                )}
            </AnimatePresence>
        </div>
    );
};

