                            <button onClick={handleFinal} className="w-full py-6 mt-10 bg-gradient-to-r from-[#ff2a6d] to-[#ff0055] rounded-[2.5rem] font-black text-2xl shadow-[0_20px_60px_rgba(255,42,109,0.4)] hover:scale-105 transition-transform uppercase italic">Initialize Link</button>
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>
