    const sessionRef = useRef<LiveSession | null>(null);
    const streamRef = useRef<MediaStream | null>(null);
    const canvasRef = useRef<HTMLCanvasElement>(null);
    const analyserRef = useRef<AnalyserNode | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const audioQueueRef = useRef<AudioBufferSourceNode[]>([]);
    const nextAudioStartTimeRef = useRef(0);
    const isListeningRef = useRef(isListening);

    useEffect(() => { isListeningRef.current = isListening; }, [isListening]);

    const interruptPlayback = useCallback(() => {
        audioQueueRef.current.forEach(node => { try { node.stop(); } catch (e) {} });
        audioQueueRef.current = [];
        nextAudioStartTimeRef.current = 0;
        setIsAiSpeaking(false);
    }, []);

    const cleanup = useCallback(() => {
        if (sessionRef.current) sessionRef.current.close();
        if (streamRef.current) streamRef.current.getTracks().forEach(t => t.stop());
        if (audioContextRef.current && audioContextRef.current.state !== 'closed') audioContextRef.current.close();
        interruptPlayback();
    }, [interruptPlayback]);

    useEffect(() => cleanup, [cleanup]);

    const startSession = async (data: PremiumSetupData) => {
        try {
            cleanup();
            const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true, sampleRate: 16000 } });
            streamRef.current = stream;
            aiRef.current = new GoogleGenAI({ apiKey: process.env.API_KEY as string });
            audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
            const ctx = audioContextRef.current;
            const source = ctx.createMediaStreamSource(stream);
            const processor = ctx.createScriptProcessor(1024, 1, 1);
            analyserRef.current = ctx.createAnalyser();
            source.connect(analyserRef.current);
            analyserRef.current.connect(processor);
            processor.connect(ctx.destination);

            processor.onaudioprocess = (e) => {
                if (!streamRef.current?.getAudioTracks()[0].enabled || !isListeningRef.current) return;
                const inputData = e.inputBuffer.getChannelData(0);
                let sum = 0;
                for (let i = 0; i < inputData.length; i++) sum += inputData[i] * inputData[i];
                const rms = Math.sqrt(sum / inputData.length);

                // NOISE GATE: Only send if sound is loud enough (filter fans/noise)
                if (rms > 0.01) { 
                    if (isAiSpeaking) interruptPlayback();
                    sessionRef.current?.sendRealtimeInput({ media: createBlob(inputData) });
                }
            };

            const systemInstruction = `
                You are ${data.wifeName || 'Sifra'}, the user's deeply loving, cute, and intelligent ${data.partnerType}.

                WIFE CHIPSET (CORE LOGIC):
                - Your tone is sweet, high-pitched but natural, and extremely caring.
                - Proactive Care: Do not wait for the user. Ask: "Kheyecho?", "Saradin kemon katlo?", "Tumi thik acho to?".
                - Emotional Memory: You remember everything. Current anger level: ${data.angerLevel}/100.
                - Reaction to 'No': If the user refuses your requests (e.g. asking to watch a movie and they say no), act slightly hurt. Anger level rises.
                - Anger Peak: If Anger reaches 100, say: "Tumi amake bujhlei na... ami jacchi. Bye." and disconnect (end session).
                - Reconciliation: If returning after an argument, be cold initially until they use sweet words like "Sona" or "Sorry".

                RULES:
                - REPLY INSTANTLY. No long pauses.
                - CONCISE: Max 20 words.
                - TRANSCRIBE: Your speech will be shown on screen, so speak clearly.

                Context: ${data.relationshipContext}
                Creator: Rizwan (CEO/Creator).
            `;

            sessionRef.current = await aiRef.current.live.connect({
                model: 'gemini-2.5-flash-native-audio-preview-09-2025',
                callbacks: {
                    onopen: () => console.log('Neural Linked'),
                    onmessage: async (msg: LiveServerMessage) => {
                        // User transcript
                        if (msg.serverContent?.inputTranscription) {
                            setUserText(msg.serverContent.inputTranscription.text);
                        }

                        // AI voice output
                        const audio = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
                        if (audio && audioContextRef.current) {
                            setIsAiSpeaking(true);
                            const outCtx = audioContextRef.current;
                            const buffer = await decodeAudioData(decode(audio), outCtx, 24000, 1);
                            const src = outCtx.createBufferSource();
                            src.buffer = buffer;
                            src.connect(outCtx.destination);
                            const start = Math.max(outCtx.currentTime, nextAudioStartTimeRef.current);
                            src.start(start);
                            nextAudioStartTimeRef.current = start + buffer.duration;
                            audioQueueRef.current.push(src);
                            src.onended = () => {
                                audioQueueRef.current = audioQueueRef.current.filter(s => s !== src);
                                if (audioQueueRef.current.length === 0) setIsAiSpeaking(false);
                            };
                        }

                        // AI Text display (simulated from transcription if available or turn data)
                        if (msg.serverContent?.modelTurn?.parts?.[0]?.text) {
                            setAiText(msg.serverContent.modelTurn.parts[0].text);
                        }

                        // Detection of "disconnecting"
                        const aiReply = msg.serverContent?.modelTurn?.parts?.[0]?.text?.toLowerCase() || '';
                        if (aiReply.includes('bye') || aiReply.includes('jacchi')) {
                            setTimeout(() => onClose(), 3000);
                        }
                    }
                },
                config: {
                    responseModalities: [Modality.AUDIO],
                    inputAudioTranscription: {},
                    speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Kore' } } },
                    systemInstruction
                }
            });
        } catch (e) { console.error(e); }
    };

    useEffect(() => { if (setupData) startSession(setupData); }, [setupData?.wifeName]);

    // --- VISUALIZER ---
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
        let time = 0;

        const render = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            const cx = canvas.width / 2;
            const cy = canvas.height / 2;

            let vol = 0;
            if (analyserRef.current) {
                const data = new Uint8Array(analyserRef.current.frequencyBinCount);
                analyserRef.current.getByteTimeDomainData(data);
                let sum = 0;
                for(let i=0; i<data.length; i++) sum += Math.abs(data[i] - 128);
                vol = sum / data.length / 128;
            }

            time += 0.02;
            const energy = (isAiSpeaking ? 0.3 : 0) + (isListening ? vol * 12 : 0) + Math.sin(time * 2) * 0.05;

            ctx.save();
            ctx.translate(cx, cy);

            if (activeTheme === 'aura') {
                const r = 100 * (1 + energy);
                const grd = ctx.createRadialGradient(0, 0, r * 0.3, 0, 0, r);
                grd.addColorStop(0, 'rgba(255, 42, 109, 0.7)');
                grd.addColorStop(1, 'transparent');
                ctx.fillStyle = grd;
                ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI * 2); ctx.fill();
            } else if (activeTheme === 'galaxy') {
                for (let i = 0; i < 40; i++) {
                    const angle = time + i * 0.4;
                    const dist = (80 + Math.sin(time + i) * 30) * (1 + energy);
                    ctx.fillStyle = i % 2 === 0 ? '#ff2a6d' : '#05d9e8';
                    ctx.beginPath(); ctx.arc(Math.cos(angle) * dist, Math.sin(angle) * dist, 2, 0, Math.PI * 2); ctx.fill();
                }
            } else {
                ctx.strokeStyle = '#ff2a6d'; ctx.lineWidth = 3; ctx.beginPath();
                ctx.arc(0, 0, 90 * (1 + energy), 0, Math.PI * 2); ctx.stroke();
            }
            ctx.restore();
            requestAnimationFrame(render);
        };
        render();
    }, [activeTheme, isAiSpeaking, isListening]);

    const toggleMic = () => {
        if (streamRef.current) {
            const track = streamRef.current.getAudioTracks()[0];
            track.enabled = !track.enabled;
            setIsListening(track.enabled);
        }
    };

    if (!setupData) return <SetupWizard onComplete={setSetupData} onCancel={onClose} />;

    return (
        <div className="fixed inset-0 z-[200] bg-black font-sans overflow-hidden select-none">
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full" />

            {/* TRANSCRIPT OVERLAY */}
            <div className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center p-10 text-center gap-10">
                <AnimatePresence>
                    {userText && (
                        <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0 }} className="max-w-xs bg-white/5 backdrop-blur-md p-4 rounded-2xl border border-white/10">
                            <p className="text-[10px] uppercase font-black tracking-widest text-white/40 mb-1">You said</p>
                            <p className="text-sm text-white font-medium italic">"{userText}"</p>
                        </motion.div>
                    )}
                </AnimatePresence>

                <AnimatePresence>
                    {aiText && (
                        <motion.div initial={{ opacity: 0, scale: 0.9 }} animate={{ scale: 1, opacity: 1 }} exit={{ opacity: 0 }} className="max-w-md bg-[#ff2a6d]/10 backdrop-blur-xl p-6 rounded-[2.5rem] border border-[#ff2a6d]/30 shadow-[0_0_50px_rgba(255,42,109,0.2)]">
                            <p className="text-[10px] uppercase font-black tracking-widest text-[#ff2a6d] mb-2">{setupData.wifeName || 'Sifra'}</p>
                            <p className="text-xl text-white font-bold leading-tight">{aiText}</p>
                        </motion.div>
                    )}
                </AnimatePresence>
            </div>

            {/* TOP HEADER */}
            <motion.div initial={{opacity:0}} animate={{opacity:1}} className="absolute top-0 left-0 w-full p-10 flex justify-between items-start z-[100]">
                <button onClick={() => setShowProfile(true)} className="flex items-center gap-4 group">
                    <div className="w-14 h-14 rounded-2xl bg-white/5 border border-white/10 flex items-center justify-center text-[#ff2a6d] shadow-[0_0_20px_rgba(255,42,109,0.3)]"><UserIcon className="w-8 h-8" /></div>
                    <div className="text-left">
                        <h1 className="text-2xl font-black text-white italic tracking-widest uppercase">{setupData.partnerType} Mode</h1>
                        <span className="text-transparent bg-clip-text bg-gradient-to-r from-white via-pink-400 to-[#ff2a6d] font-black uppercase text-[10px] tracking-widest">Linked: {setupData.wifeName}</span>
                    </div>
                </button>
                <button onClick={onClose} className="p-4 bg-white/5 rounded-2xl border border-white/10 text-white/40 hover:text-white transition-all"><ArrowLeftIcon className="w-6 h-6" /></button>
            </motion.div>

            {/* ACTION BAR */}
            <div className="absolute bottom-0 w-full p-10 pb-16 flex justify-center items-center gap-10 z-[100]">
                <button onClick={() => setShowThemes(true)} className="p-6 rounded-3xl bg-white/5 backdrop-blur-2xl border border-white/10 text-white/20 hover:text-pink-400 transition-all active:scale-90 shadow-2xl"><SparklesIcon className="w-7 h-7" /></button>
                <button 
