                </button>
                <button onClick={() => setShowProfile(true)} className="p-6 rounded-3xl bg-white/5 backdrop-blur-2xl border border-white/10 text-white/60 hover:text-white transition-all active:scale-90 shadow-2xl"><AdjustmentsHorizontalIcon className="w-7 h-7" /></button>
            </div>

            {/* THEME MODAL */}
            <AnimatePresence>
                {showThemes && (
                    <div className="fixed inset-0 z-[300] flex items-center justify-center p-6">
                        <motion.div initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} onClick={() => setShowThemes(false)} className="absolute inset-0 bg-black/90 backdrop-blur-xl" />
                        <motion.div initial={{scale:0.8, opacity:0}} animate={{scale:1, opacity:1}} exit={{scale:0.8, opacity:0}} className="relative w-full max-w-sm bg-white/5 border border-white/10 rounded-[3rem] p-8">
                            <h3 className="text-xl font-black text-white text-center mb-8 uppercase tracking-widest italic">Skin Select</h3>
                            <div className="grid grid-cols-1 gap-3">
                                {(['aura', 'crystal', 'galaxy', 'neural', 'prism', 'nebula', 'supernova'] as VisualTheme[]).map(t => (
                                    <button key={t} onClick={() => { setActiveTheme(t); setShowThemes(false); }} className={`w-full p-5 rounded-2xl border text-left capitalize transition-all ${activeTheme === t ? 'border-[#ff2a6d] bg-[#ff2a6d]/20 text-white font-bold' : 'border-white/5 bg-white/5 text-white/40'}`}>{t} Theme</button>
                                ))}
                            </div>
                        </motion.div>
                    </div>
                )}
            </AnimatePresence>

            {/* PROFILE MODAL (EDIT WIFE) */}
            <AnimatePresence>
                {showProfile && (
                    <div className="fixed inset-0 z-[300] flex items-center justify-center p-6">
                        <motion.div initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} onClick={() => setShowProfile(false)} className="absolute inset-0 bg-black/90 backdrop-blur-xl" />
                        <motion.div initial={{x:'100%'}} animate={{x:0}} exit={{x:'100%'}} className="relative w-full max-w-lg h-[85vh] bg-[#0F0F0F] border border-white/10 rounded-[3rem] p-8 flex flex-col shadow-2xl">
                            <div className="flex justify-between items-center mb-10">
                                <h2 className="text-2xl font-black text-white uppercase italic tracking-widest">Soul Settings</h2>
                                <button onClick={() => setShowProfile(false)} className="p-2 bg-white/5 rounded-full"><XMarkIcon className="w-6 h-6 text-white" /></button>
                            </div>
                            <div className="flex-1 overflow-y-auto space-y-8 pr-2 custom-scrollbar pb-10">
                                <div className="space-y-4">
                                    <label className="text-[10px] text-white/30 uppercase font-black tracking-widest">Partner Name</label>
                                    <input value={setupData.wifeName} onChange={e => setSetupData({...setupData, wifeName: e.target.value})} className="w-full bg-white/5 border border-white/10 rounded-2xl p-4 text-white font-bold text-lg outline-none focus:border-[#ff2a6d]" />
