const MeetSifraAnimation = () => {
    const canvasRef = useRef<HTMLCanvasElement>(null);

    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;

        let animationFrameId: number;
        let time = 0;

        const resize = () => {
            const rect = canvas.getBoundingClientRect();
            canvas.width = rect.width * window.devicePixelRatio;
            canvas.height = rect.height * window.devicePixelRatio;
            ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
        };

        window.addEventListener('resize', resize);
        resize();

        const render = () => {
            time += 0.02;
            const { width, height } = canvas.getBoundingClientRect();
            ctx.clearRect(0, 0, width, height);

            const centerX = width * 0.6;
            const centerY = height / 2;

            // Draw multiple glowing rings
            for (let i = 0; i < 3; i++) {
                const radius = 25 + i * 12 + Math.sin(time + i) * 5;
                const opacity = 0.15 - i * 0.04;

                ctx.beginPath();
                ctx.arc(centerX, centerY, radius, 0, Math.PI * 2);
                ctx.strokeStyle = `rgba(255, 42, 109, ${opacity})`;
                ctx.lineWidth = 2;
                ctx.stroke();

                // Small particles orbiting
                const pAngle = time * (1 + i * 0.5) + i;
                const px = centerX + Math.cos(pAngle) * radius;
                const py = centerY + Math.sin(pAngle) * radius;

                ctx.beginPath();
                ctx.arc(px, py, 1.5, 0, Math.PI * 2);
                ctx.fillStyle = `rgba(255, 42, 109, ${opacity * 4})`;
                ctx.fill();
            }

            // Central core
            const coreRadius = 15 + Math.sin(time * 2) * 2;
            const gradient = ctx.createRadialGradient(centerX, centerY, 0, centerX, centerY, coreRadius);
            gradient.addColorStop(0, 'rgba(255, 42, 109, 0.8)');
            gradient.addColorStop(1, 'rgba(255, 0, 85, 0)');

            ctx.beginPath();
            ctx.arc(centerX, centerY, coreRadius, 0, Math.PI * 2);
            ctx.fillStyle = gradient;
            ctx.fill();

            animationFrameId = requestAnimationFrame(render);
        };

        render();
        return () => {
            cancelAnimationFrame(animationFrameId);
            window.removeEventListener('resize', resize);
        };
    }, []);

    return <canvas ref={canvasRef} className="absolute inset-y-0 right-0 w-1/2 h-full pointer-events-none" />;
};

