import React, { useEffect, useState } from 'react';
import { motion, useAnimation } from 'framer-motion';

interface SifraLiveLogoProps {
    size?: 'sm' | 'md' | 'lg' | 'xl';
    loop?: boolean;
    triggerKey?: any; // Change this to restart animation
    showCrown?: boolean;
}

const SifraLiveLogo: React.FC<SifraLiveLogoProps> = ({ size = 'lg', loop = false, triggerKey, showCrown = false }) => {
    const sizeMap = {
        sm: "h-10 w-10",
        md: "h-32 w-32",
        lg: "h-56 w-56",
        xl: "h-80 w-80"
    };

    const [isAnimating, setIsAnimating] = useState(true);

    useEffect(() => {
        if (!loop) {
            setIsAnimating(true);
            const timer = setTimeout(() => setIsAnimating(false), 5000);
            return () => clearTimeout(timer);
        }
    }, [triggerKey, loop]);

    // Animation times
    const starBurstTime = 0.5;
    const ropesDrawTime = 1.5;
    const aiTagTime = 2.2;
    const haloBloomTime = 3.0;

    return (
        <div className={`relative flex items-center justify-center ${sizeMap[size]}`}>
            {/* Rainbow Bloom Halo */}
            <motion.div 
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ 
                    opacity: isAnimating || loop ? [0, 0.4, 0.4] : 0.4,
                    scale: isAnimating || loop ? [0.8, 1.2, 1.2] : 1.2,
                    rotate: 360 
                }}
                transition={{
                    opacity: { delay: haloBloomTime, duration: 1 },
                    scale: { delay: haloBloomTime, duration: 1 },
                    rotate: { duration: 10, repeat: Infinity, ease: "linear" }
                }}
                className="absolute inset-0 rounded-full"
                style={{ 
                    background: 'conic-gradient(from 0deg, #ff0000, #ff7300, #fffb00, #48ff00, #00ffd5, #002bff, #7a00ff, #ff00c8, #ff0000)',
                    filter: size === 'sm' ? 'blur(8px)' : 'blur(30px)'
                }}
            />

            <svg viewBox="0 0 200 200" className="relative z-10 w-full h-full drop-shadow-[0_0_20px_rgba(255,95,175,0.5)]">
                <defs>
                    <linearGradient id="live_s_grad_v2" x1="0%" y1="0%" x2="100%" y2="100%">
                        <stop offset="0%" stopColor="#FF5FAF" />
                        <stop offset="100%" stopColor="#FFD26E" />
                    </linearGradient>
                    <linearGradient id="live_gold_grad_v2" x1="0%" y1="0%" x2="100%" y2="0%">
                        <stop offset="0%" stopColor="#D4AF37" />
                        <stop offset="50%" stopColor="#F9E27E" />
                        <stop offset="100%" stopColor="#B8860B" />
                    </linearGradient>
                </defs>

                {/* Star Burst Effect (Yellow Stars) */}
                {(isAnimating || loop) && [...Array(8)].map((_, i) => (
                    <motion.path
                        key={i}
                        d="M0,-2 L0.5,-0.5 L2,0 L0.5,0.5 L0,2 L-0.5,0.5 L-2,0 L-0.5,-0.5 Z"
                        fill="#FFD700"
                        initial={{ x: 100, y: 100, scale: 0, opacity: 0 }}
                        animate={{ 
                            x: 100 + Math.cos(i * 45 * Math.PI / 180) * 80,
                            y: 100 + Math.sin(i * 45 * Math.PI / 180) * 80,
                            scale: [0, 2, 0],
                            opacity: [0, 1, 0]
                        }}
                        transition={{ delay: 0.2, duration: 1.5, ease: "easeOut" }}
                    />
                ))}

                {/* Queen's Crown (Conditional) */}
                {showCrown && (
                    <motion.g
                        initial={{ y: -50, opacity: 0, scale: 0.5 }}
                        animate={{ y: 25, opacity: 1, scale: 1 }}
                        transition={{ delay: 4, duration: 1.5, type: "spring" }}
                    >
                        <path d="M70,40 L80,20 L100,35 L120,20 L130,40 L130,55 L70,55 Z" fill="url(#live_gold_grad_v2)" stroke="#fff" strokeWidth="1" />
                        <circle cx="100" cy="15" r="4" fill="#FFD700" />
                        <circle cx="75" cy="50" r="2" fill="#fff" />
                        <circle cx="125" cy="50" r="2" fill="#fff" />
                    </motion.g>
                )}

                {/* Golden Ribbons (Ropes) */}
                <motion.path 
                    d="M20 130C40 100 80 160 180 100C160 80 140 40 140 70C140 100 160 120 120 130" 
                    stroke="url(#live_gold_grad_v2)" 
                    strokeWidth="4" 
                    fill="none"
                    strokeLinecap="round"
                    initial={{ pathLength: 0, opacity: 0 }}
                    animate={{ 
                        pathLength: isAnimating || loop ? [0, 1] : 1, 
                        opacity: isAnimating || loop ? [0, 1] : 1 
                    }}
                    transition={{ delay: starBurstTime, duration: ropesDrawTime }}
                />
                <motion.path 
                    d="M30 140C60 120 100 130 160 110" 
                    stroke="url(#live_gold_grad_v2)" 
                    strokeWidth="6" 
                    fill="none"
                    strokeLinecap="round" 
                    initial={{ pathLength: 0, opacity: 0 }}
                    animate={{ 
                        pathLength: isAnimating || loop ? [0, 1] : 1, 
                        opacity: isAnimating || loop ? [0, 1] : 1 
                    }}
                    transition={{ delay: starBurstTime + 0.3, duration: ropesDrawTime }}
                />

                {/* CORE "S" */}
                <motion.text 
                    x="100" 
                    y="135" 
                    textAnchor="middle" 
                    style={{ 
                        fontFamily: 'serif', 
                        fontSize: '140px', 
                        fontWeight: '900', 
                        fill: 'url(#live_s_grad_v2)',
                        fontStyle: 'italic'
                    }}
                    initial={{ scale: 0, opacity: 0 }}
                    animate={{ 
                        scale: isAnimating || loop ? [0, 1] : 1, 
                        opacity: isAnimating || loop ? [0, 1] : 1 
                    }}
                    transition={{ duration: 0.8, type: "spring" }}
                >
                    S
                </motion.text>

                {/* AI Tag */}
                <motion.g
                    initial={{ x: 50, opacity: 0 }}
                    animate={{ 
                        x: isAnimating || loop ? [50, 0] : 0, 
                        opacity: isAnimating || loop ? [0, 1] : 1 
                    }}
                    transition={{ delay: aiTagTime, duration: 0.5 }}
                >
                    <rect x="135" y="85" width="28" height="14" rx="2" fill="white" />
                    <text 
                        x="149" 
                        y="96" 
                        textAnchor="middle" 
                        style={{ 
                            fontFamily: 'sans-serif', 
                            fontSize: '9px', 
                            fontWeight: '900', 
                            fill: '#FF5FAF'
                        }}
                    >
                        AI
                    </text>
                    <motion.rect 
                        x="135" y="85" width="5" height="14" fill="white"
                        animate={{ x: [-5, 25, -5] }}
                        transition={{ duration: 2, repeat: Infinity, repeatDelay: 1 }}
                        style={{ filter: 'blur(2px)', opacity: 0.6 }}
                    />
                </motion.g>
            </svg>
        </div>
    );
};

