                <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_rgba(255,95,175,0.2)_0%,_transparent_60%)] blur-[100px]" />

                {/* Layer 2: Shifting Light Beams */}
                <motion.div 
                    animate={{ 
                        rotate: [0, 360],
                        scale: [1, 1.15, 1]
                    }}
                    transition={{ duration: 30, repeat: Infinity, ease: "linear" }}
                    className="absolute inset-0 opacity-30 mix-blend-screen"
                    style={{ 
                        background: `
                            radial-gradient(ellipse at 20% 20%, #48ff0011 0%, transparent 40%),
                            radial-gradient(ellipse at 80% 80%, #002bff11 0%, transparent 40%),
                            radial-gradient(ellipse at 50% 50%, #ff00c811 0%, transparent 50%)
                        `,
                        filter: 'blur(80px)'
                    }}
                />
            </motion.div>

            <svg viewBox="0 0 200 200" className="relative z-10 w-full h-full drop-shadow-[0_0_50px_rgba(255,95,175,0.7)] will-change-transform">
                <defs>
                    <linearGradient id="premium_s_grad_v4" x1="0%" y1="0%" x2="100%" y2="100%">
                        <stop offset="0%" stopColor="#FF5FAF" />
                        <stop offset="100%" stopColor="#FFD26E" />
                    </linearGradient>
                    <linearGradient id="premium_gold_grad_v4" x1="0%" y1="0%" x2="100%" y2="0%">
                        <stop offset="0%" stopColor="#D4AF37" />
                        <stop offset="50%" stopColor="#F9E27E" />
                        <stop offset="100%" stopColor="#B8860B" />
                    </linearGradient>
                    <filter id="glow_v4">
                        <feGaussianBlur stdDeviation="3" result="coloredBlur"/>
                        <feMerge>
                            <feMergeNode in="coloredBlur"/><feMergeNode in="SourceGraphic"/>
                        </feMerge>
                    </filter>
                </defs>

                {/* Light Speed Crown Assembly */}
                {showCrown && (
                    <motion.g
                        initial={{ y: -80, opacity: 0 }}
                        animate={{ y: 0, opacity: 1 }}
                        transition={{ delay: 3.8, duration: 1.2, type: "spring", damping: 12 }}
                    >
                        {/* Light trails meeting at the points */}
                        {[60, 75, 100, 125, 140].map((x, i) => (
                            <motion.path 
                                key={`trail-${i}`}
                                d={`M${x},-100 L${x},${i === 1 || i === 3 ? 30 : 50}`}
                                stroke="#fff" strokeWidth="0.5" opacity="0"
                                animate={{ opacity: [0, 1, 0], y: [-100, 0] }}
                                transition={{ delay: 3.5 + (i * 0.1), duration: 0.4 }}
                            />
                        ))}

                        <motion.path 
                            d="M60,60 L75,30 L100,50 L125,30 L140,60" 
                            fill="none" stroke="#fff" strokeWidth="2" opacity="0.6" filter="url(#glow_v4)"
                            initial={{ pathLength: 0 }}
                            animate={{ pathLength: 1 }}
                            transition={{ delay: 4.2, duration: 0.8 }}
                        />
                        <motion.path 
                            d="M60,60 L140,60" 
                            stroke="url(#premium_gold_grad_v4)" strokeWidth="4" strokeLinecap="round"
                            initial={{ pathLength: 0 }}
                            animate={{ pathLength: 1 }}
                            transition={{ delay: 4.0, duration: 0.8 }}
                        />

                        {[60, 75, 100, 125, 140].map((x, i) => {
                            const y = i === 1 || i === 3 ? 30 : 50;
                            return (
                                <motion.circle 
                                    key={`star-${i}`}
                                    cx={x} cy={y} r="3.5" fill="#fff"
                                    animate={{ scale: [1, 2.5, 1], opacity: [0.6, 1, 0.6] }}
                                    transition={{ duration: 1.5, repeat: Infinity, delay: i * 0.2 }}
                                    className="drop-shadow-[0_0_15px_#fff]"
                                />
                            );
                        })}
                    </motion.g>
                )}

                {/* Animated Golden Ribbons */}
                <motion.path 
                    d="M20 130C40 100 80 160 180 100C160 80 140 40 140 70C140 100 160 120 120 130" 
                    stroke="url(#premium_gold_grad_v4)" strokeWidth="5" fill="none" strokeLinecap="round"
                    initial={{ pathLength: 0, opacity: 0 }}
                    animate={{ pathLength: 1, opacity: 1 }}
                    transition={{ delay: 1, duration: ropesDrawTime }}
                />
                <motion.path 
                    d="M30 140C60 120 100 130 160 110" 
                    stroke="url(#premium_gold_grad_v4)" strokeWidth="8" fill="none" strokeLinecap="round" 
                    initial={{ pathLength: 0, opacity: 0 }}
                    animate={{ pathLength: 1, opacity: 1 }}
                    transition={{ delay: 1.3, duration: ropesDrawTime }}
                />

                {/* The Core S */}
                <motion.text 
                    x="100" y="135" textAnchor="middle" 
                    style={{ 
                        fontFamily: 'serif', fontSize: '150px', fontWeight: '950', 
                        fill: 'url(#premium_s_grad_v4)', fontStyle: 'italic'
                    }}
                    initial={{ scale: 0, opacity: 0, rotate: -15 }}
                    animate={{ scale: 1, opacity: 1, rotate: 0 }}
                    transition={{ duration: 1, type: "spring", bounce: 0.4 }}
                >
                    S
                </motion.text>

                {/* Premium AI Tag */}
                <motion.g
                    initial={{ x: 50, opacity: 0 }}
                    animate={{ x: 0, opacity: 1 }}
                    transition={{ delay: aiTagTime, duration: 0.8 }}
                >
                    <rect x="140" y="80" width="32" height="18" rx="4" fill="#fff" className="shadow-xl" />
                    <text 
                        x="156" y="93" textAnchor="middle" 
                        style={{ fontFamily: 'sans-serif', fontSize: '11px', fontWeight: '950', fill: '#FF5FAF' }}
                    >
                        AI
                    </text>
                    <motion.rect 
                        x="140" y="80" width="6" height="18" fill="white"
                        animate={{ x: [-10, 40, -10] }}
                        transition={{ duration: 1.8, repeat: Infinity, repeatDelay: 1 }}
                        style={{ filter: 'blur(4px)', opacity: 0.9 }}
                    />
                </motion.g>
            </svg>
        </div>
    );
};

export default SifraLiveLogo;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI, Chat } from '@google/genai';
import { AppFlow, View, UserProfile, Theme, THEMES, SIFRA_AVATARS, Message, Role, Mood } from './types';
import { useLocalStorage } from './hooks/useLocalStorage';
import { AnimatePresence, motion } from 'framer-motion';

// Import Services & Utils
import { detectMood, generateSpeech } from './services/geminiService';
import { decode, decodeAudioData } from './utils/audioUtils';

// Import Views
import SplashView from './views/SplashView';
import LoginView from './views/LoginView';
import HomeView from './views/HomeView';
import ProfileView from './views/ProfileView';
import HistoryView from './views/HistoryView';
import TermsView from './views/TermsView';
import AboutView from './views/AboutView';
import HowToUseView from './views/HowToUseView';
import MobileControlView from './views/MobileControlView';
import AccountSwitcherView from './views/AccountSwitcherView';
import AdminView from './views/AdminView';
import LibraryView from './views/LibraryView';
import TutorView from './views/TutorView';
import TravelGuideView from './views/TravelGuideView';
import SifraSaveView from './views/SifraSaveView';
import MonerDanaView from './views/MonerDanaView';
import DiaryEditorView from './views/DiaryEditorView';
import CallsSifraView from './views/CallsSifraView';
import AdvancedSettingsView from './views/AdvancedSettingsView';
import VoiceAssistantView from './views/VoiceAssistantView';
import DualModeView from './views/DualModeView';
import SifraProView from './views/SifraProView';
import GalaxyVoiceView from './views/GalaxyVoiceView';
import SifraPremiumPlusView from './views/SifraPremiumPlusView';
import YourCardView from './views/YourCardView';
import AccountDetailsView from './views/AccountDetailsView';
import MeetSifraView from './views/MeetSifraView';

// Import Components
import Header from './components/Header';
import Sidebar from './components/Sidebar';
import ChatMessage from './components/ChatMessage';
import ChatInput from './components/ChatInput';
import ProfileModal from './components/ProfileModal';
import VersionSelector from './components/VersionSelector';
import ArrowLeftIcon from './components/icons/ArrowLeftIcon';
import Avatar from './components/Avatar';
import SifraQueenAnimation from './components/SifraQueenAnimation';

if (!process.env.API_KEY) {
    throw new Error("API_KEY environment variable is not set");
}
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

const MOOD_MUSIC_MAP: Record<Mood, string> = {
    happy: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-1.mp3', // Upbeat
    sad: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-8.mp3',   // Calming/Sad
    calm: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-2.mp3',  // Instrumental
    focused: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-2.mp3',
    neutral: 'https://www.soundhelix.com/examples/mp3/SoundHelix-Song-2.mp3'
};

const App: React.FC = () => {
    // --- STATE MANAGEMENT ---
    const [allUsers, setAllUsers] = useLocalStorage<UserProfile[]>('sifra_all_users', []);
    const [currentUser, setCurrentUser] = useLocalStorage<UserProfile | null>('sifra_current_user', null);

    const [appFlow, setAppFlow] = useState<AppFlow>(AppFlow.SPLASH);
    const [currentView, setCurrentView] = useState<View>(View.HOME);
    const [activeDiaryEntryId, setActiveDiaryEntryId] = useState<string | null>(null);

    // Chat & Voice State
    const [chatHistory, setChatHistory] = useLocalStorage<Message[]>(`sifra_chat_history_${currentUser?.userId || ''}`, []);
    const [sifraVoice, setSifraVoice] = useLocalStorage<string>(`sifra_voice_${currentUser?.userId || ''}`, 'Kore');

    // UI State
    const [isLoading, setIsLoading] = useState(false);
    const [isSidebarOpen, setIsSidebarOpen] = useState(false);
    const [isProfileModalOpen, setIsProfileModalOpen] = useState(false);
    const [isVersionSelectorOpen, setIsVersionSelectorOpen] = useState(false);
    const [isQueenLockdown, setIsQueenLockdown] = useState(false);
    const [theme, setTheme] = useState<Theme>(THEMES[0]);
    const [showAdminPanel, setShowAdminPanel] = useState(false);
    const [currentMood, setCurrentMood] = useState<Mood>('neutral');
    const [currentlyPlayingAudioId, setCurrentlyPlayingAudioId] = useState<string | null>(null);

    const handleSplashComplete = useCallback(() => {
        if (currentUser) {
            setAppFlow(AppFlow.MAIN_APP);
            setCurrentView(View.HOME);
        } else {
            setAppFlow(AppFlow.LOGIN);
        }
    }, [currentUser]);

    // Refs
    const chatRef = useRef<Chat | null>(null);
    const chatContainerRef = useRef<HTMLDivElement>(null);
    const headerPressTimer = useRef<number | null>(null);
    const audioContextRef = useRef<AudioContext | null>(null);
    const audioSourceRef = useRef<AudioBufferSourceNode | null>(null);
    const bgMusicRef = useRef<HTMLAudioElement | null>(null);

    // --- NAVIGATION HANDLERS ---
    useEffect(() => {
        const handlePopState = (event: PopStateEvent) => {
            if (event.state && typeof event.state.view === 'number') {
                setCurrentView(event.state.view);
            } else {
                setCurrentView(View.HOME);
            }
        };

        window.addEventListener('popstate', handlePopState);
        return () => window.removeEventListener('popstate', handlePopState);
    }, []);

    const handleNavigation = (view: View, params: any = null) => {
        if (view === View.DIARY_EDITOR) {
            setActiveDiaryEntryId(params?.entryId || null);
        }

        window.history.pushState({ view }, '', '');
        setCurrentView(view);
    };

    const handleBack = () => {
        window.history.back();
    };

    const handleLoginSuccess = (user: UserProfile) => {
        setCurrentUser(user);
        setAppFlow(AppFlow.MAIN_APP);
        setCurrentView(View.HOME);
        window.history.replaceState({ view: View.HOME }, '', '');
    };

    const handleLogout = () => {
        setCurrentUser(null);
        setChatHistory([]);
        setAppFlow(AppFlow.LOGIN);
        setCurrentView(View.HOME);
    };

    const handleClearAllData = () => {
        if (window.confirm('Are you sure you want to delete ALL data? This cannot be undone.')) {
            localStorage.clear();
            window.location.reload();
        }
    };

    const handleNewChat = () => {
        setChatHistory([]);
        chatRef.current = null;
        handleNavigation(View.CHAT);
    };

    const handleUserProfileChange = (newProfile: UserProfile) => {
        setCurrentUser(newProfile);
        setAllUsers(users => users.map(u => u.userId === newProfile.userId ? newProfile : u));
    };

    // --- EFFECTS ---
    useEffect(() => {
        if (currentUser) {
            const userTheme = THEMES.find(t => t.id === currentUser.themeId) || THEMES[0];
            setTheme(userTheme);
        }
    }, [currentUser]);

    useEffect(() => {
        if (chatContainerRef.current && currentView === View.CHAT) {
            chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
        }
    }, [chatHistory, isLoading, currentView]);

    // --- MOOD AMBIENCE LOGIC ---
    useEffect(() => {
        if (currentUser?.moodAmbienceEnabled && currentMood) {
            const trackUrl = MOOD_MUSIC_MAP[currentMood];

            if (!bgMusicRef.current) {
                bgMusicRef.current = new Audio(trackUrl);
                bgMusicRef.current.loop = true;
                bgMusicRef.current.volume = 0.3;
            }

            if (bgMusicRef.current.src !== trackUrl) {
                bgMusicRef.current.pause();
                bgMusicRef.current.src = trackUrl;
                bgMusicRef.current.load();
            }

            bgMusicRef.current.play().catch(err => {
                console.log("Autoplay blocked: Waiting for user interaction to start ambience.");
            });
        } else {
            if (bgMusicRef.current) {
                bgMusicRef.current.pause();
                bgMusicRef.current = null;
            }
        }

        return () => {
            if (bgMusicRef.current) {
                bgMusicRef.current.pause();
            }
        };
    }, [currentMood, currentUser?.moodAmbienceEnabled]);

    // --- AUDIO LOGIC ---
    const playAudio = useCallback(async (text: string, messageId: string) => {
        if (audioSourceRef.current) {
            audioSourceRef.current.stop();
        }
        setCurrentlyPlayingAudioId(messageId);

        try {
            if (!audioContextRef.current) {
                audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
            }
            const audioData = await generateSpeech(text, sifraVoice);
            if (audioData && audioContextRef.current) {
                const audioBuffer = await decodeAudioData(decode(audioData), audioContextRef.current, 24000, 1);
                const source = audioContextRef.current.createBufferSource();
                source.buffer = audioBuffer;
                source.connect(audioContextRef.current.destination);
                source.start();
                audioSourceRef.current = source;
                source.onended = () => {
                    if (audioSourceRef.current === source) {
                        setCurrentlyPlayingAudioId(null);
                        audioSourceRef.current = null;
                    }
                };
            } else {
                 setCurrentlyPlayingAudioId(null);
            }
        } catch (error) {
            console.error("Failed to play audio:", error);
            setCurrentlyPlayingAudioId(null);
        }
    }, [sifraVoice]);

    // --- CHAT LOGIC ---
    const handleSendMessage = async (text: string, imageData?: { data: string, mimeType: string }) => {
        if ((!text.trim() && !imageData) || isLoading || !currentUser) return;

        const parts = [];
        if (text.trim()) parts.push({ text });
        if (imageData) parts.push({ inlineData: imageData });

        const userMessage: Message = { 
            messageId: `msg-user-${Date.now()}`, 
            role: Role.USER, 
            parts 
        };
        const currentChatHistory = [...chatHistory, userMessage];
        setChatHistory(currentChatHistory);
        setIsLoading(true);

        if (currentUser.moodAmbienceEnabled && text.trim()) {
            detectMood(text).then(setCurrentMood);
        }

        try {
            const systemInstruction = `
                You are SIFRA, a female AI assistant. You have a soft, warm, intelligent, and caring personality.
                - Creator: Rizwan RR.
                - Tone: Soft, polite, intelligent. Mix of Bengali and English.
            `;

            if (!chatRef.current) {
                 chatRef.current = ai.chats.create({ 
                    model: 'gemini-3-flash-preview', 
                    history: chatHistory.map(({role, parts}) => ({role, parts: parts.map(p => ({
                        text: p.text,
                    }))})),
                    config: { systemInstruction } 
                });
            }

            const stream = await chatRef.current.sendMessageStream({ message: text.trim() || "Look at this image." });

            let fullText = '';
            const modelMessageId = `msg-model-${Date.now()}`;
            const placeholderMessage: Message = { messageId: modelMessageId, role: Role.MODEL, parts: [{ text: '' }] };
            setChatHistory([...currentChatHistory, placeholderMessage]);

            for await (const chunk of stream) {
                fullText += chunk.text || '';
                setChatHistory(prev =>
                    prev.map(msg =>
                        msg.messageId === modelMessageId
                            ? { ...msg, parts: [{ text: fullText }] }
                            : msg
                    )
                );
            }

        } catch (error) {
            console.error("Gemini API error:", error);
            const errorMessage: Message = { messageId: `msg-error-${Date.now()}`, role: Role.MODEL, parts: [{ text: "Oops, I encountered a brain-freeze. Could you try that again?" }] };
            setChatHistory([...currentChatHistory, errorMessage]);
        } finally {
            setIsLoading(false);
        }
    };

    const handleHeaderPress = () => {
        headerPressTimer.current = window.setTimeout(() => {
            setShowAdminPanel(true);
        }, 2000); 
    };

    const handleHeaderRelease = () => {
        if (headerPressTimer.current) {
            clearTimeout(headerPressTimer.current);
        }
    };

    const handleManageAccount = () => {
        setIsProfileModalOpen(false);
        handleNavigation(View.PROFILE);
    };

    const renderMainView = () => {
        if (!currentUser) return null;

        const sifraAvatar = SIFRA_AVATARS.find(a => a.id === currentUser.sifraAvatarId) || SIFRA_AVATARS[0];

        switch (currentView) {
            case View.HOME:
                return <HomeView userProfile={currentUser} onNavigate={handleNavigation} />;
            case View.PROFILE:
                return <ProfileView userProfile={currentUser} onUserProfileChange={handleUserProfileChange} sifraVoice={sifraVoice} onSifraVoiceChange={setSifraVoice} onClose={handleBack} onNavigate={handleNavigation} onLogout={handleLogout} onClearAllData={handleClearAllData} />;
            case View.HISTORY:
                return <HistoryView chatHistory={chatHistory} setChatHistory={setChatHistory} onClose={handleBack} />;
            case View.TERMS: return <TermsView onClose={handleBack} showAcceptButton={false} onAccept={() => {}} />;
            case View.ABOUT: return <AboutView onClose={handleBack} />;
            case View.HOW_TO_USE: return <HowToUseView onClose={handleBack} />;
            case View.MOBILE_CONTROL: return <MobileControlView onClose={handleBack} />;
            case View.ACCOUNT_SWITCHER: return <AccountSwitcherView allUsers={allUsers} currentUser={currentUser} onSwitchUser={(userId) => { const user = allUsers.find(u => u.userId === userId); if(user) handleLoginSuccess(user); }} onAddNewUser={handleLogout} onClose={handleBack} />;
            case View.LIBRARY: return <LibraryView onClose={handleBack} onNavigate={handleNavigation} />;
            case View.TUTOR: return <TutorView userProfile={currentUser} onClose={handleBack} />;
            case View.TRAVEL_GUIDE: return <TravelGuideView userProfile={currentUser} onClose={handleBack} />;
            case View.SIFRA_SAVE: return <SifraSaveView userProfile={currentUser} onClose={handleBack} />;
            case View.MONER_DANA: return <MonerDanaView userProfile={currentUser} onClose={handleBack} onNavigate={handleNavigation} />;
            case View.DIARY_EDITOR: return <DiaryEditorView userProfile={currentUser} onClose={() => handleNavigation(View.MONER_DANA)} entryId={activeDiaryEntryId} />;
            case View.CALLS_SIFRA: return <CallsSifraView userProfile={currentUser} onClose={handleBack} />;
            case View.ADVANCED_SETTINGS: return <AdvancedSettingsView onNavigate={handleNavigation} onClose={handleBack} onNewChat={handleNewChat} onLogout={handleLogout} />;
            case View.VOICE_ASSISTANT: return <VoiceAssistantView userProfile={currentUser} onClose={handleBack} />;
            case View.GALAXY_VOICE: 
                return <GalaxyVoiceView userProfile={currentUser} onClose={handleBack} />;
            case View.DUAL_MODE: 
                return <DualModeView userProfile={currentUser} onUpdateProfile={handleUserProfileChange} onClose={handleBack} />;
            case View.SIFRA_PRO:
                return <SifraProView userProfile={currentUser} onUpdateProfile={handleUserProfileChange} onClose={handleBack} />;
            case View.SIFRA_PREMIUM_PLUS:
                return <SifraPremiumPlusView userProfile={currentUser} onClose={handleBack} />;
            case View.YOUR_CARD:
                return <YourCardView userProfile={currentUser} onClose={handleBack} />;
            case View.ACCOUNT_DETAILS:
                return <AccountDetailsView userProfile={currentUser} onClose={handleBack} onNavigate={handleNavigation} />;
            case View.MEET_SIFRA:
                return <MeetSifraView onClose={handleBack} />;

            case View.CHAT:
            default:
                return (
                    <div className="h-full flex flex-col animate-fade-in bg-white/50 backdrop-blur-md">
                        <header className="p-4 flex items-center justify-between border-b border-gray-100">
                             <div className="flex items-center gap-4">
                                <button onClick={handleBack} className="p-2 -ml-2 rounded-full hover:bg-black/5 transition-colors">
                                    <ArrowLeftIcon />
                                </button>
                                <div>
                                    <h1 className="text-lg font-bold text-gray-800">Sifra Chat</h1>
                                    <p className="text-[10px] text-green-500 font-bold uppercase tracking-widest">Active Neural Link</p>
                                </div>
                             </div>
                             <Avatar src={sifraAvatar.url} isSifra />
                        </header>
                        <div ref={chatContainerRef} className="flex-1 overflow-y-auto space-y-4 p-4 scroll-smooth">
                            {chatHistory.map((msg, index) => (
                                <ChatMessage
                                    key={msg.messageId || index}
                                    message={msg}
                                    isPlayingAudio={currentlyPlayingAudioId === msg.messageId}
                                    onReplayAudio={playAudio}
                                    userAvatar={currentUser?.avatar || null}
                                    userName={currentUser?.name || null}
                                    sifraAvatarUrl={sifraAvatar.url}
                                    isLoading={isLoading}
                                    isLastMessage={index === chatHistory.length - 1}
                                />
                            ))}
                        </div>
                        <div className="p-4">
                            <ChatInput onSendMessage={handleSendMessage} isLoading={isLoading} onVoiceClick={() => handleNavigation(View.GALAXY_VOICE)} />
                        </div>
                    </div>
                );
        }
    };

    if (appFlow === AppFlow.SPLASH) {
        return <SplashView onComplete={handleSplashComplete} />;
    }

    if (appFlow === AppFlow.LOGIN) {
        return <LoginView onLoginSuccess={handleLoginSuccess} />;
    }

    if (appFlow === AppFlow.MAIN_APP && currentUser) {
        if (currentView === View.SIFRA_PREMIUM_PLUS) {
            return (
                <main className="w-screen h-screen font-sans bg-black">
                    <SifraPremiumPlusView userProfile={currentUser} onClose={handleBack} />
                </main>
            );
        }

        return (
            <main className={`w-screen h-screen font-sans bg-gradient-to-br ${theme.gradient} flex flex-col overflow-hidden relative`}>

                 <AnimatePresence>
                    {isQueenLockdown && (
                        <SifraQueenAnimation onComplete={() => setIsQueenLockdown(false)} />
                    )}
                 </AnimatePresence>

                 {/* Root Optimization: All heavy content is inside this motion div */}
                 <motion.div 
                    initial={false}
                    animate={{ 
                        filter: isQueenLockdown ? 'blur(40px) grayscale(0.5)' : 'blur(0px) grayscale(0)',
                        opacity: isQueenLockdown ? 0.3 : 1,
                        scale: isQueenLockdown ? 0.95 : 1
                    }}
                    transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
                    className="flex-1 flex flex-col will-change-transform"
                    style={{ transform: 'translateZ(0)' }}
                 >
                    <div onMouseDown={handleHeaderPress} onMouseUp={handleHeaderRelease} onTouchStart={handleHeaderPress} onTouchEnd={handleHeaderRelease}>
                        {currentView === View.HOME && (
                            <Header 
                                userName={currentUser.nickname || currentUser.name} 
                                onProfileClick={() => setIsProfileModalOpen(true)} 
                                onMenuClick={() => setIsSidebarOpen(true)} 
                                onVersionClick={() => setIsVersionSelectorOpen(true)} 
                                onLogoClick={() => setIsQueenLockdown(true)}
                                theme={theme} 
                                moodAmbienceEnabled={currentUser.moodAmbienceEnabled} 
                                currentMood={currentMood}
                            />
                        )}
                    </div>
                    <Sidebar isOpen={isSidebarOpen} onClose={() => setIsSidebarOpen(false)} onNavigate={(view) => { handleNavigation(view); setIsSidebarOpen(false); }} onLogout={handleLogout} onNewChat={() => { handleNewChat(); setIsSidebarOpen(false); }} userProfile={currentUser} />
                    {showAdminPanel && <AdminView onClose={() => setShowAdminPanel(false)} currentUserProfile={currentUser} />}
                    {isProfileModalOpen && (
                        <ProfileModal
                            userProfile={currentUser}
                            onClose={() => setIsProfileModalOpen(false)}
                            onManageAccount={handleManageAccount}
                            onLogout={handleLogout}
                            onClearAllData={handleClearAllData}
                        />
                    )}
                    {isVersionSelectorOpen && (
                        <VersionSelector 
                            onClose={() => setIsVersionSelectorOpen(false)}
                            onSelectFree={() => handleNavigation(View.CHAT)}
                            onSelectQuantum={() => handleNavigation(View.DUAL_MODE)}
                            onSelectPro={() => handleNavigation(View.SIFRA_PRO)}
                            onSelectPremiumPlus={() => handleNavigation(View.SIFRA_PREMIUM_PLUS)} 
                        />
                    )}
                    <div className="flex-1 overflow-hidden relative">
                        {renderMainView()}
                    </div>
                 </motion.div>
            </main>
        );
    }

    return <LoginView onLoginSuccess={handleLoginSuccess} />;
};

