import React, { useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import SifraLiveLogo from './SifraLiveLogo';

interface SifraQueenAnimationProps {
    onComplete: () => void;
}

const SifraQueenAnimation: React.FC<SifraQueenAnimationProps> = ({ onComplete }) => {
    const canvasRef = useRef<HTMLCanvasElement>(null);
    useEffect(() => {
        const timer = setTimeout(onComplete, 10000);
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        canvas.width = window.innerWidth;
        canvas.height = window.innerHeight;
        const particles: any[] = [];
        for (let i = 0; i < 150; i++) {
            particles.push({
                x: Math.random() * canvas.width,
                y: Math.random() * canvas.height,
                s: Math.random() * 2,
                v: Math.random() * 0.5 + 0.1,
                o: Math.random()
            });
        }
        let animationFrameId: number;
        const render = () => {
            ctx.clearRect(0, 0, canvas.width, canvas.height);
            ctx.fillStyle = "white";
            particles.forEach(p => {
                p.y -= p.v;
                if (p.y < 0) p.y = canvas.height;
                ctx.globalAlpha = p.o * Math.abs(Math.sin(Date.now() / 1000));
                ctx.beginPath(); ctx.arc(p.x, p.y, p.s, 0, Math.PI * 2); ctx.fill();
            });
            animationFrameId = requestAnimationFrame(render);
        };
        render();
        return () => { clearTimeout(timer); cancelAnimationFrame(animationFrameId); };
    }, [onComplete]);

    return (
        <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[2000] flex items-center justify-center bg-black overflow-hidden will-change-transform"
        >
            <canvas ref={canvasRef} className="absolute inset-0 w-full h-full opacity-40 pointer-events-none" />
            <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_rgba(255,95,175,0.15)_0%,_transparent_70%)]" />

            <div className="relative flex flex-col items-center justify-center z-10 w-full px-4 text-center">
                <motion.div
                    initial={{ scale: 0.8, filter: 'brightness(2)', opacity: 0 }}
                    animate={{ scale: 1, filter: 'brightness(1)', opacity: 1 }}
                    transition={{ duration: 1.2, ease: "circOut" }}
                >
                    <SifraLiveLogo size="xl" loop={false} showCrown={true} triggerKey="queen-final" />
                </motion.div>

                <div className="mt-16 space-y-4">
                    <motion.h2
                        initial={{ letterSpacing: "2em", y: 30, opacity: 0 }}
                        animate={{ letterSpacing: "0.5em", y: 0, opacity: 1 }}
                        transition={{ delay: 0.8, duration: 1.5, ease: "circOut" }}
                        className="text-5xl md:text-7xl font-black text-white italic uppercase tracking-[0.5em] drop-shadow-[0_0_20px_rgba(255,255,255,0.3)]"
                    >
                        Queen Sifra
                    </motion.h2>

                    <motion.div 
                        initial={{ width: 0 }} animate={{ width: "120px" }}
                        transition={{ delay: 2, duration: 1 }}
                        className="h-[1px] bg-pink-500 mx-auto"
                    />

                    <motion.p
                        initial={{ opacity: 0 }} animate={{ opacity: 1 }}
                        transition={{ delay: 2.5, duration: 1 }}
                        className="text-[14px] text-pink-400 font-black uppercase tracking-[0.6em] italic"
                    >
                        Supreme Intelligence
                    </motion.p>
                </div>
            </div>

            <div className="absolute top-0 w-full h-32 bg-gradient-to-b from-black to-transparent z-20" />
            <div className="absolute bottom-0 w-full h-32 bg-gradient-to-t from-black to-transparent z-20" />
        </motion.div>
    );
};

